# ══════════════════════════════════════════════════════════════════════════════
# MODELOS PYDANTIC
# ══════════════════════════════════════════════════════════════════════════════

class Message(BaseModel):
    """Mensaje del historial conversacional"""
    role: Literal["user", "assistant", "system"]
    content: str


class SearchRequest(BaseModel):
    """Request para búsqueda híbrida"""
    query: str = Field(..., min_length=1, max_length=2000)
    estado: Optional[str] = Field(None, description="Estado mexicano (ej: NUEVO_LEON)")
    top_k: int = Field(10, ge=1, le=50)
    alpha: float = Field(0.7, ge=0.0, le=1.0, description="Balance dense/sparse (1=solo dense)")
    fuero: Optional[str] = Field(None, description="Filtro por fuero: constitucional, federal, estatal o combinados")


class SearchResult(BaseModel):
    """Resultado individual de búsqueda"""
    id: str
    score: float
    texto: str
    ref: Optional[str] = None
    origen: Optional[str] = None
    jurisdiccion: Optional[str] = None
    entidad: Optional[str] = None
    silo: str
    pdf_url: Optional[str] = None  # URL del PDF oficial (GCS o fuente gubernamental)
    # Campos de jurisprudencia/tesis para CITATION_META
    registro: Optional[str] = None
    tesis_num: Optional[str] = None
    tipo_criterio: Optional[str] = None
    instancia_meta: Optional[str] = None
    materia_meta: Optional[str] = None
    # La cita tal como la redacta la Corte —«[J]; 11a. Época; 1a. Sala; Gaceta
    # S.J.F.; Libro 5, Abril de 2014; Tomo I; Pág. 451»—. Sólo la trae v3. Se
    # copia literal en vez de componerla, que es donde se cuelan los errores.
    localizacion: Optional[str] = None
    # True = jurisprudencia OBLIGATORIA. De 71.655 tesis sólo vinculan 17.930;
    # hasta ahora no se distinguía y todo se citaba igual.
    vincula: Optional[bool] = None
    # Campos LLM Tagging (conceptos semánticos para Concept Boost)
    conceptos_transversales: Optional[List[str]] = None
    tema_articulo: Optional[str] = None
    # Campos GraphRAG extraídos de jurisprudencia_nacional_v2
    ratio_decidendi: Optional[str] = None
    condicion_de_aplicacion: Optional[str] = None
    distincion: Optional[str] = None
    sentido_del_criterio: Optional[str] = None
    obiter_dicta: Optional[str] = None


class SearchResponse(BaseModel):
    """Response de búsqueda"""
    query: str
    estado_filtrado: Optional[str]
    resultados: List[SearchResult]
    total: int


# ── PDF por silo ───────────────────────────────────────────────────────────────
#
# REGLA QUE NO SE ROMPE: aquí sólo puede haber PDFs que sean *exactamente* el
# documento citado. Nunca un sustituto "parecido".
#
# Esto no es celo de estilo. El silo `bloque_constitucional` guarda la
# Constitución **y además todos los tratados de derechos humanos** — eso es lo
# que significa bloque de constitucionalidad. Cuando esta tabla se usaba como
# comodín por silo, un abogado que citaba la Convención Interamericana abría el
# PDF y se encontraba la Constitución. Peor todavía con los códigos locales.
# Mostrarle a un abogado un documento distinto del que citó es la peor falla
# posible de esta app: puede acabar en un escrito presentado ante un juez.
#
# Por eso `PDF_FALLBACK_URLS` ya NO se indexa por silo. La Constitución tiene su
# PDF porque es un documento concreto, y se sirve sólo cuando el documento es
# la Constitución. Si no sabemos cuál es el PDF, se devuelve None y la app dice
# honestamente que no hay PDF disponible.
PDF_CONSTITUCION = "https://ukcuzhwmmfwvcedvhfll.supabase.co/storage/v1/object/public/legal-docs/constitucion/CPEUM-2024.pdf"
_S_QRO = "https://ukcuzhwmmfwvcedvhfll.supabase.co/storage/v1/object/public/legal-docs/Queretaro/Leyes"

# Se conserva el nombre por compatibilidad con el resto del archivo, pero ya
