def _detect_materia(query: str, forced_materia: Optional[str] = None) -> Optional[List[str]]:
    """
    Detecta la materia jurídica de una consulta usando keywords.
    Capa 1 del Materia-Aware Retrieval: 0 latencia, 0 costo.
    
    Args:
        query: Consulta del usuario
        forced_materia: Si se proporciona, se usa directamente (override del frontend)
    
    Returns:
        Lista de máximo 2 materias detectadas, o None si no detecta ninguna
    """
    # Override: si el frontend forzó una materia, usarla directamente
    if forced_materia:
        normalized = forced_materia.upper().strip()
        if normalized in MATERIA_KEYWORDS:
            return [normalized]
        return None
    
    query_lower = query.lower()
    scores = {}
    
    for materia, keywords in MATERIA_KEYWORDS.items():
        # Contar cuántos keywords de cada materia aparecen
        count = sum(1 for kw in keywords if kw in query_lower)
        if count > 0:
            scores[materia] = count
    
    if not scores:
        return None
    
    # Ordenar por score descendente, tomar máximo 2
    sorted_materias = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    
    # Si la top materia tiene 2+ hits más que la segunda, solo devolver la top
    if len(sorted_materias) >= 2:
        top_score = sorted_materias[0][1]
        second_score = sorted_materias[1][1]
        if top_score >= second_score + 2:
            return [sorted_materias[0][0]]
        return [sorted_materias[0][0], sorted_materias[1][0]]
    
    return [sorted_materias[0][0]]


def _score_materia_relevance(result, detected_materias: List[str]) -> float:
    """
    Multi-signal scoring: evalúa qué tan relevante es un resultado para la materia detectada.
    Usa 3 señales: jurisdiccion metadata, nombre de ley (origen), y exclusiones negativas.
    
    Maneja inconsistencias legacy en el campo jurisdiccion almacenado en Qdrant
    (ej: 'administrativa' vs 'administrativo').
    
    Returns: float entre 0.0 y 1.0 (1.0 = máxima relevancia)
    """
    score = 0.5  # Punto neutral
    
    materias_upper = {m.upper() for m in detected_materias}
    origen_lower = (result.origen or "").lower()
    
    # Normalizar jurisdiccion del chunk (maneja variantes legacy)
    _JURISDICCION_NORMALIZE = {
        "administrativa": "ADMINISTRATIVO",
        "administrativo": "ADMINISTRATIVO",
        "penal": "PENAL",
        "civil": "CIVIL",
        "familiar": "FAMILIAR",
        "laboral": "LABORAL",
        "fiscal": "FISCAL",
        "mercantil": "MERCANTIL",
        "agrario": "AGRARIO",
        "constitucional": "CONSTITUCIONAL",
        "electoral": "ELECTORAL",
    }
    jur_raw = (result.jurisdiccion or "").lower()
    jur_normalized = _JURISDICCION_NORMALIZE.get(jur_raw, jur_raw.upper())
    
    # Expandir aliases para comparación
    _JUR_ALIASES = {
        "ADMINISTRATIVO": {"ADMINISTRATIVO", "FISCAL"},
        "FISCAL": {"FISCAL", "ADMINISTRATIVO"},
        "CIVIL": {"CIVIL", "FAMILIAR"},
        "FAMILIAR": {"FAMILIAR", "CIVIL"},
        "MERCANTIL": {"MERCANTIL"},
        "PENAL": {"PENAL"},
        "LABORAL": {"LABORAL"},
        "AGRARIO": {"AGRARIO"},
        "CONSTITUCIONAL": {"CONSTITUCIONAL"},
    }
    jur_expanded = _JUR_ALIASES.get(jur_normalized, {jur_normalized})
    
    # Señal 1: jurisdiccion normalizada coincide con materia detectada (+0.3)
    if jur_expanded & materias_upper:  # intersección no vacía
        score += 0.3
    
    # Señal 2: Nombre de la ley contiene keywords de la materia (+0.2)
    for m in materias_upper:
        kws = MATERIA_KEYWORDS.get(m, set())
        if any(kw in origen_lower for kw in kws):
            score += 0.2
            break
    
    # Señal 3: Nombre de la ley está en la lista de exclusiones (-0.5)
    exclusions = set()
    for m in materias_upper:
        exclusions.update(MATERIA_EXCLUSIONS.get(m, set()))
    if any(excl in origen_lower for excl in exclusions):
        score -= 0.5
    
    return max(0.0, min(1.0, score))


# Cuánto puede alejarse un resultado del mejor antes de considerarse ruido,
# cuando no hay materia detectada que permita un filtro más fino.
RAG_DISTANCIA_MAXIMA = float(os.getenv("RAG_DISTANCIA_MAXIMA", "0.30"))


def _filtrar_por_distancia(results: list, protected_silo: Optional[str] = None) -> list:
    """Criba de último recurso cuando no se detectó materia.

    Descarta lo que puntúa muy por debajo del mejor resultado. No sabe de
    materias — sabe que un documento tres décimas peor que el primero no está
    respondiendo la misma pregunta.

    Nunca descarta jurisprudencia, bloque constitucional ni el silo del estado
    elegido: son fuente primaria y a veces puntúan bajo por redacción, no por
    falta de pertinencia.
    """
    if not results:
        return results

    _PROTEGIDOS = {*JURIS_SILOS,
                   "bloque_constitucional"}
    piso = results[0].score - RAG_DISTANCIA_MAXIMA
    guardados, descartados = [], 0
    for r in results:
        if r.silo in _PROTEGIDOS or r.silo == protected_silo or r.score >= piso:
            guardados.append(r)
        else:
            descartados += 1

    if descartados:
        print(f"   🧹 SIN MATERIA — criba por distancia: descartados "
              f"{descartados} bajo {piso:.3f} (mejor={results[0].score:.3f})")
    return guardados


# ── Códigos nacionales: el hueco que el ranking no llenaba ───────────────────
#
# En México el delito lo define el código penal de cada estado, pero el
# PROCEDIMIENTO penal lo rige un solo ordenamiento nacional, el CNPP. Igual en
# civil con el CNPCF donde ya entró en vigor.
#
# Medido el 1-ago-2026: una consulta sobre el plazo para formular imputación
# devolvía 12 resultados, ninguno del CNPP —que está indexado con 493 chunks—.
# En CDMX devolvía la Ley de Agentes Inmobiliarios de Guanajuato. El CNPP
# pierde porque su texto embebido arranca con un encabezado de jerarquía
# enorme que diluye el artículo:
#
#   [Codigo NACIONAL DE PROCEDIMIENTOS PENALES | TÍTULO I ... | CAPÍTULO III
#    ... | DISPOSICIONES COMUNES] Artículo 191. ...
#
# En vez de pelear contra el ranking, se le reserva lugar: si la consulta es
# procesal, se hace una búsqueda dirigida contra leyes_federales filtrando por
# la materia que ya viene etiquetada en el payload, y esos artículos entran sí
# o sí.

_SENAL_PROCESAL = re.compile(
    r"\b(procedimiento|procesal|proceso|audiencia|emplaza|notificaci[óo]n|"
    r"plazo para|t[ée]rmino para|vinculaci[óo]n a proceso|imputaci[óo]n|"
    r"desahogo|ofrecimiento de prueba|contestar la demanda|apelaci[óo]n|"
    r"recurso de revocaci[óo]n|incidente|medida cautelar|prisi[óo]n preventiva|"
    r"juicio oral|etapa intermedia|acusaci[óo]n|sobreseimiento|"
    r"suspensi[óo]n condicional|carpeta de investigaci[óo]n|caducidad|"
    r"rebeld[íi]a|sentencia ejecutoriada|ejecuci[óo]n de sentencia)\b",
    re.IGNORECASE)
_SENAL_PENAL = re.compile(
    r"\b(penal|delito|delictiv|imputad|acusad|v[íi]ctima|ministerio p[úu]blico|"
    r"fiscal[íi]a|defensor|prisi[óo]n|querella|denuncia)\b", re.IGNORECASE)
_SENAL_CIVIL = re.compile(
    r"\b(civil|familiar|demanda|contrato|arrendamiento|sucesi[óo]n|"
    r"divorcio|alimentos|inmueble|propiedad|prescripci[óo]n|hipotec)\b",
    re.IGNORECASE)


# Figuras que sólo existen en un procedimiento y no necesitan más contexto:
# quien pregunta por la «vinculación a proceso» está en materia penal aunque no
# escriba la palabra «penal», y quien pregunta por el «emplazamiento» está en
# civil. Sin esto, «¿Cuál es el plazo para formular imputación?» no activaba el
# CNPP porque la consulta no contiene ninguna palabra genéricamente penal.
_SOLO_PENAL = re.compile(
    r"\b(vinculaci[óo]n a proceso|imputaci[óo]n|carpeta de investigaci[óo]n|"
    r"prisi[óo]n preventiva|etapa intermedia|auto de vinculaci[óo]n|"
    r"suspensi[óo]n condicional del proceso|procedimiento abreviado|"
    r"control de detenci[óo]n|sobreseimiento|acusaci[óo]n)\b", re.IGNORECASE)
_SOLO_CIVIL = re.compile(
    r"\b(emplaza|contestar la demanda|rebeld[íi]a|caducidad de la instancia|"
    r"litisconsorcio|reconvenci[óo]n|juicio ejecutivo|v[íi]a de apremio)\b",
    re.IGNORECASE)


def _detectar_consulta_procesal(query: str) -> Optional[str]:
    """`procesal_penal`, `procesal_civil` o None.

    Sólo devuelve algo cuando la consulta habla de PROCEDIMIENTO. Una pregunta
    por la pena del robo no necesita el CNPP; una por el plazo de la
    vinculación a proceso no se responde sin él.
    """
    if not query or not _SENAL_PROCESAL.search(query):
        return None
    if _SOLO_PENAL.search(query):
        return "procesal_penal"
    if _SOLO_CIVIL.search(query):
        return "procesal_civil"
    penal = len(_SENAL_PENAL.findall(query))
    civil = len(_SENAL_CIVIL.findall(query))
    if penal == 0 and civil == 0:
        return None
    return "procesal_penal" if penal >= civil else "procesal_civil"


async def _traer_codigo_nacional(materia: str, dense_vector, limite: int = 6):
    """Los artículos del código nacional que corresponden a la consulta."""
    try:
        res = await qdrant_client.query_points(
            collection_name="leyes_federales",
            query=dense_vector,
            using="dense",
            limit=limite,
            with_payload=True,
            query_filter=Filter(must=[FieldCondition(
                key="materia", match=MatchValue(value=materia))]),
        )
        salida = []
        for p in res.points:
            pl = p.payload or {}
            salida.append(SearchResult(
                id=str(p.id),
                score=float(p.score),
                texto=pl.get("texto") or pl.get("texto_raw") or "",
                ref=pl.get("ref"),
                origen=pl.get("cuerpo_legal_oficial") or pl.get("ley"),
                jurisdiccion=pl.get("materia"),
                entidad=pl.get("entidad") or "FEDERAL",
                silo="leyes_federales",
                pdf_url=pl.get("pdf_url") or pl.get("url_pdf"),
                tema_articulo=pl.get("tema_articulo"),
            ))
        return salida
    except Exception as e:
        print(f"   ⚠️ código nacional ({materia}): {err(e)}")
        return []


def _apply_materia_threshold(results: list, detected_materias: Optional[List[str]], threshold_gap: float = 0.25, strict_mode: bool = False, protected_silo: Optional[str] = None) -> list:
    """
    Capa 3 del Materia-Aware Retrieval: Post-retrieval threshold con multi-signal scoring.
    
    Tres capas de filtrado:
      1. Exclusiones negativas: Penaliza leyes que son falsos positivos conocidos
         (ej: "Ley de Propiedad Industrial" cuando materia=CIVIL)
      2. Multi-signal scoring: Evalúa jurisdiccion + nombre de ley + exclusiones
      3. Threshold por score: Descarta resultados de baja relevancia
    
    Dos modos:
      - soft (default): Penaliza score de resultados de materia ajena
      - strict (strict_mode=True): DESCARTA todo lo que no coincida,
        excepto jurisprudencia y constitucional
    
    Args:
        results: Lista de SearchResult ordenados por score
        detected_materias: Materias detectadas por _detect_materia()
        threshold_gap: Diferencia máxima tolerada vs top score (0.25 = 25%)
        strict_mode: Si True, hard-drop de materia ajena (forzado por usuario)
    
    Returns:
        Lista filtrada de SearchResult
    """
    if not results:
        return results

    if not detected_materias:
        # Sin materia detectada NO se filtraba absolutamente nada, y ahí nacía
        # el mezclado que reportan los usuarios: una consulta genérica ("¿qué
        # recurso procede contra esta resolución?") no dispara ninguna palabra
        # clave, así que los 40 documentos de todos los silos llegaban al
        # modelo sin criba y aparecía la Ley Apícola junto a un amparo.
        #
        # No se puede filtrar por materia si no hay materia, pero sí por
        # distancia al mejor resultado: si el primero puntúa 0.72 y otro 0.31,
        # ese segundo es ruido venga de donde venga. Se conservan siempre
        # jurisprudencia, bloque constitucional y el silo del estado elegido,
        # que son fuente primaria aunque puntúen bajo.
        return _filtrar_por_distancia(results, protected_silo)

    # Materia mapping expandido
    # Permite que "FAMILIAR" también acepte "CIVIL" (muchos estados tienen familia en CC)
    MATERIA_ALIAS = {
        "FAMILIAR": {"FAMILIAR", "CIVIL"},
        "ADMINISTRATIVO": {"ADMINISTRATIVO", "FISCAL"},
        "CIVIL": {"CIVIL", "FAMILIAR"},
        "PENAL": {"PENAL"},
        "LABORAL": {"LABORAL"},
        "MERCANTIL": {"MERCANTIL", "CIVIL"},
        "FISCAL": {"FISCAL", "ADMINISTRATIVO"},
        "AGRARIO": {"AGRARIO"},
        "CONSTITUCIONAL": {"CONSTITUCIONAL"},
    }
    
    materias_upper = {m.upper() for m in detected_materias}
    expanded_materias = set()
    for m in materias_upper:
        expanded_materias.update(MATERIA_ALIAS.get(m, {m}))
    
    # Construir set de exclusiones para las materias detectadas
    exclusions = set()
    for m in materias_upper:
        exclusions.update(MATERIA_EXCLUSIONS.get(m, set()))
    
    top_score = results[0].score if results else 0
    threshold = top_score - threshold_gap
    
    filtered = []
    dropped_count = 0
    penalized_count = 0
    
    for r in results:
        # SIEMPRE mantener jurisprudencia, constitucional, y el silo del estado seleccionado
        # El silo del estado seleccionado es la fuente primaria — nunca descartar por materia
        if r.silo in (*JURIS_SILOS, "bloque_constitucional") or r.silo == protected_silo:
            filtered.append(r)
            continue
        
        origen_lower = (r.origen or "").lower()
        
        # ── CAPA 1: EXCLUSIONES NEGATIVAS (máxima prioridad) ──
        # Si el nombre de la ley coincide con un falso positivo conocido,
        # penalizar agresivamente el score (no eliminar, para evitar errores)
        is_excluded = any(excl in origen_lower for excl in exclusions)
        if is_excluded:
            if strict_mode:
                dropped_count += 1
                print(f"      🚫 EXCLUIDO (strict): {r.origen[:60]}")
                continue
            else:
                # Soft mode: penalizar score a 30% del original
                r.score *= 0.3
                penalized_count += 1
                # No continuar — dejarlo pasar con score reducido
        
        # ── CAPA 2: MULTI-SIGNAL MATERIA SCORING ──
        materia_relevance = _score_materia_relevance(r, detected_materias)
        
        if materia_relevance >= 0.7:
            # Alta relevancia: mantener siempre
            filtered.append(r)
            continue
        elif materia_relevance >= 0.4:
            # Relevancia media: mantener si score es decente
            if r.score >= threshold or not strict_mode:
                filtered.append(r)
            else:
                dropped_count += 1
            continue
        else:
            # Baja relevancia
            if strict_mode:
                dropped_count += 1
                continue
            # Soft mode: mantener solo si score es alto
            if r.score >= threshold:
                r.score *= 0.6  # Penalización moderada
                penalized_count += 1
                filtered.append(r)
            else:
                dropped_count += 1
    
    mode_label = "ESTRICTO" if strict_mode else "SOFT"
    if dropped_count > 0 or penalized_count > 0:
        print(f"   🧹 MATERIA THRESHOLD ({mode_label}): Descartados={dropped_count} Penalizados={penalized_count} (materias={list(materias_upper)})")
    
    return filtered


# text-embedding-3-small corta en 8,192 tokens y devuelve 400 si te pasas.
# Sin tiktoken en el entorno el tope se pone en caracteres, y conviene pecar de
# corto: la prosa española ronda 3.5-4 caracteres por token, pero un texto denso
# en artículos, fracciones y números romanos tokeniza mucho peor. Con 20,000
# caracteres se aguanta incluso a 2.5 car./token (8,000 tokens), que es el peor
# caso realista. Poner 26,000 —lo que salía de multiplicar por 3.2— se pasaba
# del tope justo con el tipo de texto que provoca el problema.
MAX_CHARS_EMBEDDING = 20_000


def _acotar_para_embedding(texto: str) -> str:
    """Recorta lo que se va a embeber para no rebasar el tope del modelo.

    POR QUÉ ESTO EXISTE (10-ago-2026)
    ---------------------------------
    Un abogado abrió el análisis de una carpeta con 35 documentos —201,965
    caracteres, unos 50,500 tokens— y en la pantalla le apareció esto:

        Error: RetryError[<Future at 0x7a47a2b56110 state=finished
        raised BadRequestError>]

    El análisis de carpeta manda su instrucción entera como consulta, y esa
    consulta se embebe para buscar en el acervo. 50,500 tokens contra un tope
    de 8,192: la API devolvía 400, tenacity reintentaba tres veces y soltaba
    `RetryError`, cuyo texto crudo terminaba pintado como si fuera el análisis.

    Se acota aquí, en el único punto por el que pasan las doce llamadas, y no
    en cada una: cualquier ruta futura que embeba texto largo queda protegida
    sin acordarse de esto.

    Recortar el vector de búsqueda no degrada la respuesta: sirve para
    encontrar leyes parecidas al tema, y el tema ya está en los primeros miles
    de caracteres. El texto completo sigue viajando al modelo por su camino.
    """
    if len(texto) <= MAX_CHARS_EMBEDDING:
        return texto
    print(f"   ✂️ Consulta de {len(texto):,} caracteres acotada a "
          f"{MAX_CHARS_EMBEDDING:,} para el embedding")
    return texto[:MAX_CHARS_EMBEDDING]


@retry(
    stop=stop_after_attempt(3),
    wait=wait_exponential(multiplier=1, min=1, max=8),
    retry=retry_if_exception_type(Exception),
    before_sleep=lambda rs: print(f"   ⏳ Embedding retry #{rs.attempt_number} after error...")
)
async def get_dense_embedding(text: str, modelo: Optional[str] = None) -> List[float]:
    """Genera embedding denso usando OpenAI (con reintentos automáticos + semáforo)."""
    async with OPENAI_SEM:
        response = await openai_client.embeddings.create(
            model=modelo or EMBEDDING_MODEL,
            input=_acotar_para_embedding(text),
        )
        return response.data[0].embedding


# Los silos se consultan EN PARALELO y varios pueden ser de jurisprudencia, así
# que sin esto la misma consulta se embebería varias veces por petición. La
# caché es pequeña y se limpia sola: sólo tiene que sobrevivir a una ráfaga.
# Un dict normal basta y evita depender de un import que en este fichero llega
# mil líneas más abajo: desde Python 3.7 conserva el orden de inserción, que es
# lo único que hace falta para desalojar el más viejo.
_CACHE_EMB_JURIS: Dict[str, List[float]] = {}
_CACHE_EMB_MAX = 64


async def _embedding_juris(texto: str) -> List[float]:
    """El vector para la jurisprudencia v3, que usa otro modelo y otra dimensión."""
    llave = (texto or "")[:400]
    if llave in _CACHE_EMB_JURIS:
        return _CACHE_EMB_JURIS[llave]
    v = await get_dense_embedding(texto, modelo=EMBEDDING_MODEL_JURIS)
    _CACHE_EMB_JURIS[llave] = v
    if len(_CACHE_EMB_JURIS) > _CACHE_EMB_MAX:
        _CACHE_EMB_JURIS.pop(next(iter(_CACHE_EMB_JURIS)))
    return v


def get_sparse_embedding(text: str) -> SparseVector:
    """Genera embedding sparse usando BM25. Degrada a sparse vacío si el modelo aún carga."""
    if sparse_encoder is None:
        # Modelo BM25 todavía cargando en background — degradar a dense-only search
        return SparseVector(indices=[], values=[])
    # BM25 corre en local y no devuelve 400, pero con 200,000 caracteres tarda
    # y diluye los términos que de verdad distinguen la consulta. Se acota con
    # el mismo criterio que el denso para que ambos vectores miren lo mismo.
    embeddings = list(sparse_encoder.query_embed(_acotar_para_embedding(text)))
    if not embeddings:
        return SparseVector(indices=[], values=[])
    
    sparse = embeddings[0]
    return SparseVector(
        indices=sparse.indices.tolist(),
        values=sparse.values.tolist(),
    )


# ── RECENCY BOOST: criterios más recientes tienen más relevancia ──────
# Principio jurídico: los criterios más modernos prevalecen sobre los
# anteriores.  El multiplicador es suave (1.0–1.08) para no anular la
# relevancia semántica, pero suficiente para desempatar criterios similares.
import datetime as _dt

_CURRENT_YEAR = _dt.date.today().year
_RECENCY_BASE_YEAR = 2019           # Antes de 2019 → sin boost
_RECENCY_MAX_BOOST = 0.08           # +8% para el año actual

def _recency_multiplier(fecha_str: str) -> float:
    """
    Retorna un multiplicador ≥1.0 basado en qué tan reciente es la sentencia.
    - 2026 → 1.08  (boost máximo)
    - 2024 → ~1.06
    - 2020 → ~1.01
    - 2019 o antes → 1.00 (sin boost)
    - Sin fecha → 1.00 (sin boost)
    """
    if not fecha_str or len(fecha_str) < 4:
        return 1.0
    try:
        year = int(fecha_str[:4])
    except (ValueError, TypeError):
        return 1.0
    if year <= _RECENCY_BASE_YEAR:
        return 1.0
    span = max(1, _CURRENT_YEAR - _RECENCY_BASE_YEAR)
    ratio = min(1.0, (year - _RECENCY_BASE_YEAR) / span)
    return 1.0 + (_RECENCY_MAX_BOOST * ratio)


async def search_precedentes_holdings(
    query: str,
    tribunal: Optional[str] = None,
    circuit: str = "22",
    limit: int = 12,
) -> List[SearchResult]:
    """
    Búsqueda híbrida (RRF dense+sparse) en sentencias_holdings_{circuit}.
    Fallback a dense-only si Prefetch/RRF falla (e.g. qdrant-client Union bug).
    circuit: número de circuito como string ("22", "1", etc.)
    tribunal: ID del tribunal ("1TCC", "2TCC", "TCCPA", etc.) o None (todos)
    """
    # Colección unificada — filtramos por circuito en payload
    COLLECTION = "sentencias_holdings"

    try:
        dense_vec, sparse_vec = await asyncio.gather(
            get_dense_embedding(query),
            asyncio.get_running_loop().run_in_executor(None, get_sparse_embedding, query),
        )
        print(f"   ⚖️ Embeddings OK — dense_dim={len(dense_vec)}, sparse_indices={len(sparse_vec.indices)}")
    except Exception as emb_err:
        print(f"   ⚠️ search_precedentes_holdings embedding error: {emb_err}")
        return []

    # Filtro por circuito (payload) + tribunal si se especifica
    # circuito is stored as string for all circuits (keyword index)
    filter_conditions = [
        FieldCondition(key="circuito", match=MatchValue(value=str(circuit)))
    ]
    if tribunal:
        _TIPO_CODES = {"ADM", "CIV", "LAB", "PEN"}
        _MATERIA_MAP = {"ADM": "administrativa", "CIV": "civil", "LAB": "laboral", "PEN": "penal"}
        if tribunal.upper() in _TIPO_CODES:
            # Materia-level filter: use should-OR for tribunal_tipo (circuits 1/2/4) or materia (circuit 3)
            filter_conditions.append(
                Filter(should=[
                    FieldCondition(key="tribunal_tipo", match=MatchValue(value=tribunal.upper())),
                    FieldCondition(key="materia", match=MatchValue(value=_MATERIA_MAP.get(tribunal.upper(), tribunal.lower()))),
                ])
            )
        else:
            # Specific tribunal code like "1TCC_ADM" — works for ALL circuits
            # (circuit 3 was normalized by restore_jalisco_payload.py to use short codes)
            filter_conditions.append(
                FieldCondition(key="tribunal", match=MatchValue(value=tribunal))
            )
    qdrant_filter = Filter(must=filter_conditions) if filter_conditions else None
    print(f"   ⚖️ Filtro Qdrant: circuito={circuit}, tribunal={tribunal or 'todos'}")

    points = []
    try:
        if _SOLO_DENSO:
            # Ver el comentario de _SOLO_DENSO: el índice sparse no cabe en la
            # RAM del clúster y una ráfaga híbrida lo tira a timeouts.
            response = await qdrant_client.query_points(
                collection_name=COLLECTION,
                query=dense_vec,
                using="dense",
                limit=limit,
                query_filter=qdrant_filter,
                with_payload=True,
            )
        else:
            response = await qdrant_client.query_points(
                collection_name=COLLECTION,
                prefetch=[
                    Prefetch(query=dense_vec, using="dense", limit=limit * 2, filter=qdrant_filter),
                    Prefetch(query=sparse_vec, using="sparse", limit=limit * 2, filter=qdrant_filter),
                ],
                query=FusionQuery(fusion=Fusion.RRF),
                limit=limit,
                with_payload=True,
            )
        points = response.points
        print(f"   ⚖️ Búsqueda OK — {len(points)} puntos")
    except Exception as rrf_err:
        print(f"   ⚠️ RRF/Prefetch falló ({rrf_err}), intentando dense-only...")
        try:
            response = await qdrant_client.query_points(
                collection_name=COLLECTION,
                query=dense_vec,
                using="dense",
                limit=limit,
                query_filter=qdrant_filter,
                with_payload=True,
            )
            points = response.points
            print(f"   ⚖️ Dense-only OK — {len(points)} puntos")
        except Exception as dense_err:
            print(f"   ⚠️ Dense fallback también falló: {dense_err}")
            return []

    results: List[SearchResult] = []
    for p in points:
        pay = p.payload or {}
        trib = pay.get("tribunal") or ""
        exp = pay.get("expediente") or ""
        fecha = pay.get("fecha_sentencia") or ""
        sentido = pay.get("sentido") or ""
        materia = pay.get("materia") or ""
        holding_text = pay.get("holding") or ""

        # ref visible para la cita: "3TCC · AD-892/2022 · Concede · 2022"
        ref_parts = [x for x in [trib, exp, sentido.capitalize(), fecha[:4]] if x]
        ref = " · ".join(ref_parts)

        # Recency boost: criterios más recientes tienen más peso
        raw_score = p.score if p.score is not None else 0.0
        boosted = raw_score * _recency_multiplier(fecha)

        results.append(SearchResult(
            id=str(p.id),
            score=boosted,
            texto=holding_text,
            ref=ref,
            origen=f"{trib} — {circuit}° Circuito — {materia}",
            silo=f"sentencias_{circuit}_circuito",
            pdf_url=pay.get("pdf_url"),
        ))

    # Re-sort por score con recency ya aplicado
    results.sort(key=lambda r: -r.score)
    return results


async def search_precedentes_global(
    query: str,
    tribunal: Optional[str] = None,
    circuits: Optional[List[str]] = None,
    limit: int = 15,
) -> List[SearchResult]:
    """
    Búsqueda global en paralelo sobre todos los circuitos activos.
    Garantiza representación mínima de cada circuito (evita que un circuito con
    scores sistemáticamente más altos monopolice los resultados).
    circuits: lista explícita de circuitos; None = _ACTIVE_CIRCUITS.
    """
    targets = circuits if circuits is not None else _ACTIVE_CIRCUITS
    n = len(targets)
    # Minimum guaranteed results per circuit; remaining slots filled by score
    min_per = max(3, limit // n)
    limit_per_circuit = min_per + 5   # fetch extra so score top-up has candidates
    tasks = [
        search_precedentes_holdings(query, tribunal=tribunal, circuit=c, limit=limit_per_circuit)
        for c in targets
    ]
    per_circuit = await asyncio.gather(*tasks, return_exceptions=True)

    guaranteed: List[SearchResult] = []
    leftovers:  List[SearchResult] = []
    for i, r in enumerate(per_circuit):
        if isinstance(r, Exception):
            print(f"   ⚠️ search_precedentes_global error en circuito {targets[i]}: {r}")
        elif isinstance(r, list):
            print(f"   ⚖️ Circuito {targets[i]}: {len(r)} resultados")
            guaranteed.extend(r[:min_per])
            leftovers.extend(r[min_per:])

    # Fill remaining slots with highest-scoring extras from any circuit
    leftovers.sort(key=lambda x: x.score, reverse=True)
    remaining = max(0, limit - len(guaranteed))
    combined = guaranteed + leftovers[:remaining]
    # Final sort for LLM readability (higher score first)
    combined.sort(key=lambda x: x.score, reverse=True)
    print(f"   ⚖️ Global: {len(guaranteed)} garantizados + {min(remaining, len(leftovers))} top-up → {len(combined)} total")
    return combined


# ── SCJN: Suprema Corte (Pleno + Primera Sala + Segunda Sala) ─────────────────
_SCJN_SALAS_VALID = {"PLENO", "PRIMERA_SALA", "SEGUNDA_SALA"}


def _scjn_sala_label(sala: str) -> str:
    return {
        "PLENO": "Pleno",
        "PRIMERA_SALA": "Primera Sala",
        "SEGUNDA_SALA": "Segunda Sala",
    }.get(sala or "", "SCJN")


async def search_precedentes_scjn(
    query: str,
    sala: Optional[str] = None,
    limit: int = 15,
) -> List[SearchResult]:
    """
    Búsqueda híbrida en sentencias_scjn_holdings (Suprema Corte).
    sala: 'PLENO' | 'PRIMERA_SALA' | 'SEGUNDA_SALA' | None (todas).
    """
    COLLECTION = "sentencias_scjn_holdings"
    try:
        dense_vec, sparse_vec = await asyncio.gather(
            get_dense_embedding(query),
            asyncio.get_running_loop().run_in_executor(None, get_sparse_embedding, query),
        )
    except Exception as emb_err:
        print(f"   ⚠️ search_precedentes_scjn embedding error: {emb_err}")
        return []

    filter_conditions = []
    if sala and sala.upper() in _SCJN_SALAS_VALID:
        filter_conditions.append(FieldCondition(key="sala", match=MatchValue(value=sala.upper())))
    qdrant_filter = Filter(must=filter_conditions) if filter_conditions else None
    sala_label = _scjn_sala_label(sala) if sala else "todas las salas"
    print(f"   🏛️ SCJN: filtro sala={sala_label}, limit={limit}")

    points = []
    try:
        if _SOLO_DENSO:
            # Ver el comentario de _SOLO_DENSO.
            response = await qdrant_client.query_points(
                collection_name=COLLECTION,
                query=dense_vec,
                using="dense",
                limit=limit,
                query_filter=qdrant_filter,
                with_payload=True,
            )
        else:
            response = await qdrant_client.query_points(
                collection_name=COLLECTION,
                prefetch=[
                    Prefetch(query=dense_vec, using="dense", limit=limit * 2, filter=qdrant_filter),
                    Prefetch(query=sparse_vec, using="sparse", limit=limit * 2, filter=qdrant_filter),
                ],
                query=FusionQuery(fusion=Fusion.RRF),
                limit=limit,
                with_payload=True,
            )
        points = response.points
        print(f"   🏛️ SCJN búsqueda OK — {len(points)} puntos")
    except Exception as rrf_err:
        print(f"   ⚠️ SCJN RRF/Prefetch falló ({rrf_err}), intentando dense-only...")
        try:
            response = await qdrant_client.query_points(
                collection_name=COLLECTION,
                query=dense_vec,
                using="dense",
                limit=limit,
                query_filter=qdrant_filter,
                with_payload=True,
            )
            points = response.points
            print(f"   🏛️ SCJN dense-only OK — {len(points)} puntos")
        except Exception as dense_err:
            print(f"   ⚠️ SCJN dense fallback también falló: {dense_err}")
            return []

    results: List[SearchResult] = []
    for p in points:
        pay = p.payload or {}
        sala_p = pay.get("sala") or ""
        expediente = pay.get("expediente") or ""
        fecha = pay.get("fecha_sentencia") or ""
        sentido = pay.get("sentido") or ""
        materia = pay.get("materia") or ""
        tipo = pay.get("tipo_asunto") or ""
        ministro = pay.get("ministro_ponente") or ""
        holding_text = pay.get("holding") or ""

        sala_disp = _scjn_sala_label(sala_p)
        # ref visible: "SCJN · Primera Sala · ADR-123/2020 · Concede · 2020"
        ref_parts = [x for x in ["SCJN", sala_disp, expediente, sentido.capitalize() if sentido else "", fecha[:4]] if x]
        ref = " · ".join(ref_parts)
        origen_parts = [x for x in [sala_disp, tipo.replace("_", " ").title() if tipo else "", materia, ministro] if x]
        origen = " — ".join(origen_parts) if origen_parts else "Suprema Corte de Justicia de la Nación"

        results.append(SearchResult(
            id=str(p.id),
            score=(p.score if p.score is not None else 0.0) * _recency_multiplier(fecha),
            texto=holding_text,
            ref=ref,
            origen=origen,
            silo="sentencias_scjn_holdings",
            pdf_url=pay.get("pdf_url"),
        ))
    results.sort(key=lambda r: -r.score)
    return results


async def search_precedentes_unified(
    query: str,
    limit_scjn: int = 10,
    limit_tcc: int = 8,
) -> List[SearchResult]:
    """
    Búsqueda unificada: SCJN al frente + TCC en paralelo.
    Garantiza representación mínima de ambos para que el usuario vea
    primero la corte suprema y después los criterios de circuito.
    """
    scjn_task = search_precedentes_scjn(query=query, sala=None, limit=limit_scjn)
    tcc_task  = search_precedentes_global(query=query, tribunal=None, limit=limit_tcc)
    scjn_results, tcc_results = await asyncio.gather(scjn_task, tcc_task, return_exceptions=True)

    combined: List[SearchResult] = []
    if isinstance(scjn_results, list):
        combined.extend(scjn_results)
        print(f"   ⚖️ Unificado: {len(scjn_results)} SCJN")
    else:
        print(f"   ⚠️ search_precedentes_unified SCJN error: {scjn_results}")
    if isinstance(tcc_results, list):
        combined.extend(tcc_results)
        print(f"   ⚖️ Unificado: {len(tcc_results)} TCC")
    else:
        print(f"   ⚠️ search_precedentes_unified TCC error: {tcc_results}")

    return combined


# Maximum characters per document to prevent token overflow
MAX_DOC_CHARS = 6000

# ── JERARQUÍA NORMATIVA: Orden de autoridad legal (menor número = mayor jerarquía) ──
SILO_HIERARCHY_PRIORITY: Dict[str, int] = {
    # Nivel 0: Constitución y bloque constitucionalidad
    "bloque_constitucional": 0,
    # Nivel 1: Leyes federales / código nacional
    "leyes_federales": 1,
    "codigo_nacional": 1,
    # Nivel 2: Leyes estatales
    "leyes_estatales": 2,
    # Nivel 3: Jurisprudencia (complementaria, subordinada a norma)
    "jurisprudencia_nacional": 3,
    "jurisprudencia_nacional_v2": 3,
    "jurisprudencia_nacional_v3": 3,
    "jurisprudencia_tcc": 3,
    "jurisprudencia": 3,
}


def _get_jerarquia_label(silo: str) -> str:
    """
    Retorna una etiqueta de jerarquía normativa para un silo dado.
    Esta etiqueta se incluye en el XML del contexto para que el LLM
    pueda aplicar la regla de supremacía (REGLA #6 del system prompt).
    """
    level = SILO_HIERARCHY_PRIORITY.get(silo, 2)
    if level == 0:
        return "CONSTITUCION"
    if level == 1:
        return "LEY_FEDERAL"
    if level == 2:
        return "LEY_ESTATAL"
    if level == 3:
        return "JURISPRUDENCIA"
    return "DOCUMENTO"


def reorder_by_hierarchy(results: List[SearchResult]) -> List[SearchResult]:
    """
    Reordena resultados RAG respetando la jerarquía normativa mexicana:
    CONSTITUCION > LEY_FEDERAL > LEY_ESTATAL > JURISPRUDENCIA

    Dentro de cada nivel, mantiene el orden por score descendente (Cohere rerank).
    Esto asegura que el LLM vea primero la norma constitucional/legal vigente
    y después la jurisprudencia, evitando que tesis antiguas (ej. pre-Reforma 2024)
    dominen el contexto y generen respuestas obsoletas.
    """
    def sort_key(r: SearchResult):
        silo_priority = SILO_HIERARCHY_PRIORITY.get(r.silo, 2)
        return (silo_priority, -r.score)  # Menor level primero; mayor score primero
    return sorted(results, key=sort_key)




# ══════════════════════════════════════════════════════════════════════════════
# ARTICLE CROSS-REFERENCE INJECTION
# Cuando un precedente federal cita artículos de leyes federales (ej: "artículos
# 55 y 58 de la Ley sobre el Contrato de Seguro"), busca automáticamente esos
# artículos en leyes_federales y los inyecta al contexto para que el LLM tenga
# el texto literal de la ley, no solo la paráfrasis del precedente.
# ══════════════════════════════════════════════════════════════════════════════

# Map common law names from precedentes → canonical name in Qdrant
_LEY_NAME_MAP = {
    "ley sobre el contrato de seguro": "Ley Sobre el Contrato de Seguro",
    "ley del contrato de seguro": "Ley Sobre el Contrato de Seguro",
    "ley de contrato de seguro": "Ley Sobre el Contrato de Seguro",
    "código de comercio": "Código de Comercio",
    "codigo de comercio": "Código de Comercio",
    "código civil federal": "Código Civil Federal",
    "codigo civil federal": "Código Civil Federal",
    "ley federal del trabajo": "Ley Federal del Trabajo",
    "código penal federal": "Código Penal Federal",
    "codigo penal federal": "Código Penal Federal",
    "ley general de títulos y operaciones de crédito": "Ley General de Títulos y Operaciones de Crédito",
    "ley general de titulos y operaciones de credito": "Ley General de Títulos y Operaciones de Crédito",
    "ley de amparo": "Ley de Amparo",
    "ley general de sociedades mercantiles": "Ley General de Sociedades Mercantiles",
    "código fiscal de la federación": "Código Fiscal de la Federación",
    "codigo fiscal de la federacion": "Código Fiscal de la Federación",
    "ley del seguro social": "Ley del Seguro Social",
    "ley del impuesto sobre la renta": "Ley del Impuesto Sobre la Renta",
    "ley del impuesto al valor agregado": "Ley del Impuesto al Valor Agregado",
    "ley general de instituciones y sociedades mutualistas de seguros": "Ley General de Instituciones y Sociedades Mutualistas de Seguros",
    "ley de instituciones de seguros y de fianzas": "Ley de Instituciones de Seguros y de Fianzas",
    "código nacional de procedimientos penales": "Código Nacional de Procedimientos Penales",
    "codigo nacional de procedimientos penales": "Código Nacional de Procedimientos Penales",
    "ley general de víctimas": "Ley General de Víctimas",
    "ley general de victimas": "Ley General de Víctimas",
}

# Regex to find article citations in text
_ARTICLE_CITE_RE = re.compile(
    r'art[ií]culos?\s+'
    r'(\d+(?:\s*(?:bis|ter|qu[aá]ter|quinquies))?'
    r'(?:\s*,\s*\d+(?:\s*(?:bis|ter|qu[aá]ter|quinquies))?)*'
    r'(?:\s*(?:y|e)\s*\d+(?:\s*(?:bis|ter|qu[aá]ter|quinquies))?)?)'
    r'(?:\s*,?\s*(?:fracci[oó]n(?:es)?\s+[IVXLCDM]+(?:\s*,\s*[IVXLCDM]+)*(?:\s*(?:y|e)\s*[IVXLCDM]+)?)?)?'
    r'\s*(?:de\s+la|del)\s+'
    r'((?:Ley|Código|Codigo|Constitución|Constitucion|Reglamento)[A-ZÁÉÍÓÚa-záéíóúñÑ\s]+?)(?=\s*[,;.()\n]|\s+(?:establece|dispone|señala|prevé|regula|prescribe|consagra|previene|contempla|ordena|que\s)|$)',
    re.IGNORECASE
)


def _extract_cited_articles(texto: str) -> list:
    """Extract (article_numbers, law_name) tuples from text."""
    results = []
    for m in _ARTICLE_CITE_RE.finditer(texto):
        nums_raw = m.group(1)
        ley_raw = m.group(2).strip().rstrip(",. ")
        
        # Parse article numbers: "55, 58 y 70" → ["55", "58", "70"]
        nums = re.findall(r'(\d+)', nums_raw)
        
        # Normalize law name and look up canonical
        ley_lower = ley_raw.lower().strip()
        canonical = _LEY_NAME_MAP.get(ley_lower)
        
        # If not found by exact match, try substring matching
        if not canonical:
            for key, val in _LEY_NAME_MAP.items():
                if key in ley_lower or ley_lower in key:
                    canonical = val
                    break
        
        if canonical and nums:
            results.append((nums, canonical))
    
    return results


# ── Salto interno: el artículo que cita a otro artículo de su misma ley ──────
#
# El cruce que ya existía (inject_cross_referenced_articles) sólo mira DENTRO
# DE LOS PRECEDENTES y sólo trae artículos de `leyes_federales`. El abogado
# estatal —el usuario real de las 32 entidades— no recibía nada: su artículo
# dice «se seguirá el procedimiento del artículo 47 de este Código» y el 47
# jamás llegaba al contexto. Medido sobre producción: el 15 % de los artículos
# cita otro artículo, con 1.8 a 4.7 referencias cada uno.
#
# Se resuelve SÓLO dentro de la misma ley (mismo `origen`, misma colección).
# Esa restricción no es pereza: emparejar leyes por parecido de nombre produce
# citas equivocadas —llegó a ofrecerse el Código Administrativo por el
# Electoral—, así que aquí no se adivina ninguna ley. Si el texto nombra otra
# norma, esa referencia se descarta y la atiende el cruce federal.

_RE_ENCABEZADO_ART = re.compile(
    r'^\s*art[íi]culo\s*\.?\s*\d+[^\s]*\s*[\.\-–]?\s*', re.I)
_RE_CITA_ART = re.compile(
    r'art[íi]culos?\s+((?:\d{1,4}\s*(?:bis|ter|qu[áa]ter)?\s*[,;yeo]*\s*){1,8})', re.I)
# Si tras la cita aparece OTRA norma con nombre propio, no es una cita interna.
_RE_OTRA_NORMA = re.compile(
    r'\b(?:de|del)\s+(?:la\s+|el\s+)?'
    r'(?:Ley|C[óo]digo|Constituci[óo]n|Reglamento|Decreto|Tratado)\s+'
    r'(?!(?:vigente|anterior|citad[oa]))[A-ZÁÉÍÓÚ]', re.I)
_RE_MISMA_NORMA = re.compile(
    r'\b(?:de|del)\s+(?:est[ae]|el\s+presente|la\s+presente)\s+'
    r'(?:ley|c[óo]digo|reglamento|ordenamiento)', re.I)


def _articulos_citados_misma_ley(texto: str, propio: int | None) -> list:
    """Números de artículo citados dentro del mismo cuerpo legal."""
    if not texto:
        return []
    cuerpo = _RE_ENCABEZADO_ART.sub("", texto.strip(), count=1)
    encontrados: list = []
    for m in _RE_CITA_ART.finditer(cuerpo):
        # Ventana posterior: si nombra otra ley, la referencia no es interna.
        cola = cuerpo[m.end():m.end() + 90]
        if _RE_OTRA_NORMA.search(cola) and not _RE_MISMA_NORMA.search(cola):
            continue
        for n in re.findall(r'\d{1,4}', m.group(1)):
            try:
                num = int(n)
            except ValueError:
                continue
            if 1 <= num <= 9999 and num != propio and num not in encontrados:
                encontrados.append(num)
    return encontrados


# Qué campo guarda el nombre de la ley en cada colección. No es uniforme y no
# se puede adivinar: las colecciones antiguas indexan `origen`, las ingeridas
# con el script v3 indexan `ley`, y `leyes_federales` sólo tiene `ley`.
# Filtrar por la clave equivocada NO devuelve vacío: devuelve 400 «Index
# required but not found», así que el salto se caía en 19 de 33 colecciones.
#
# En vez de crear diecinueve índices nuevos —más trabajo para un Qdrant que va
# justo de memoria—, la clave se aprende en la primera consulta y se recuerda.
#
# El mapa va sembrado con lo medido contra producción el 7-ago-2026 para que
# ni la primera consulta pague el intento fallido. Si una colección cambia de
# forma, el aprendizaje de abajo la corrige sola.
_CLAVE_LEY_POR_COLECCION: dict = {
    "leyes_federales": "ley",
    "leyes_aguascalientes": "ley", "leyes_baja_california": "ley",
    "leyes_baja_california_sur": "ley", "leyes_campeche": "ley",
    "leyes_chiapas": "ley", "leyes_coahuila": "ley", "leyes_colima": "ley",
    "leyes_durango": "ley", "leyes_hidalgo": "ley", "leyes_nayarit": "ley",
    "leyes_oaxaca": "ley", "leyes_quintana_roo": "ley",
    "leyes_san_luis_potosi": "ley", "leyes_sonora": "ley",
    "leyes_tabasco": "ley", "leyes_tamaulipas": "ley",
    "leyes_tlaxcala": "ley", "leyes_yucatan": "ley", "leyes_zacatecas": "ley",
    "leyes_cdmx": "origen", "leyes_chihuahua": "origen",
    "leyes_edomex": "origen", "leyes_guanajuato": "origen",
    "leyes_guerrero": "origen", "leyes_jalisco": "origen",
    "leyes_michoacan": "origen", "leyes_morelos": "origen",
    "leyes_nuevo_leon": "origen", "leyes_puebla": "origen",
    "leyes_queretaro": "origen", "leyes_sinaloa": "origen",
    "leyes_veracruz": "origen",
}


async def _buscar_por_ley(qdrant_client_obj, coleccion: str, nombre_ley: str,
                          numeros: list, Filter, FieldCondition, MatchValue, MatchAny):
    """Artículos de una ley por número exacto, con la clave que esa colección use."""
    candidatas = [_CLAVE_LEY_POR_COLECCION.get(coleccion, "origen")]
    if candidatas[0] == "origen":
        candidatas.append("ley")
    else:
        candidatas.append("origen")

    for clave in candidatas:
        try:
            hallado = await qdrant_client_obj.scroll(
                collection_name=coleccion,
                limit=len(numeros),
                scroll_filter=Filter(must=[
                    FieldCondition(key=clave, match=MatchValue(value=nombre_ley)),
                    FieldCondition(key="articulo_num", match=MatchAny(any=numeros)),
                ]),
                with_payload=True,
                with_vectors=False,
            )
            _CLAVE_LEY_POR_COLECCION[coleccion] = clave   # aprendida
            return hallado
        except Exception:
            continue
    return None


async def inyectar_articulos_de_la_misma_ley(
    results: list,
    qdrant_client_obj,
    max_inyecciones: int = 6,
) -> list:
    """Trae al contexto los artículos que los resultados de ley citan."""
    from qdrant_client.models import Filter, FieldCondition, MatchValue, MatchAny

    presentes = {r.id for r in results}
    ya_tengo = {
        (r.silo, str(r.origen or ""), str(r.ref or ""))
        for r in results if r.silo and r.silo.startswith("leyes_")
    }

    # (colección, origen) → números pedidos, en orden de relevancia del citante
    pedidos: dict = {}
    for r in results:
        if not r.silo or not r.silo.startswith("leyes_"):
            continue
        propio = None
        m = re.match(r'^\s*art[íi]?c?u?l?o?\.?\s*[\s\.]*(\d{1,4})', str(r.ref or ""), re.I)
        if m:
            propio = int(m.group(1))
        for num in _articulos_citados_misma_ley(r.texto or "", propio):
            clave = (r.silo, str(r.origen or ""))
            pedidos.setdefault(clave, [])
            if num not in pedidos[clave]:
                pedidos[clave].append(num)

    if not pedidos:
        return results

    # UNA consulta por ley, no una por artículo. Medido contra producción:
    # seis búsquedas en serie costaban 3.2 s y en paralelo 539 ms, pero con
    # `MatchAny` los seis artículos llegan en un solo viaje. Esta capa corre en
    # el camino crítico de TODAS las consultas: el segundo que se ahorra pesa
    # más que los dos artículos que aporta.
    async def _buscar_ley(coleccion: str, origen: str, numeros: list):
        return coleccion, origen, await _buscar_por_ley(
            qdrant_client_obj, coleccion, origen, numeros,
            Filter, FieldCondition, MatchValue, MatchAny)

    tareas = []
    for (coleccion, origen), numeros in pedidos.items():
        if not origen or not numeros:
            continue
        tareas.append(_buscar_ley(coleccion, origen, numeros[:4]))
        if len(tareas) >= 3:      # tope de leyes distintas por consulta
            break

    hallazgos = await asyncio.gather(*tareas, return_exceptions=True)

    inyectados = []
    for resultado in hallazgos:
        if len(inyectados) >= max_inyecciones:
            break
        if isinstance(resultado, BaseException) or resultado is None:
            continue
        coleccion, origen, hallados = resultado
        if not hallados or not hallados[0]:
            continue
        for punto in hallados[0]:
            if len(inyectados) >= max_inyecciones:
                break
            pl = punto.payload or {}
            clave = (coleccion, origen, str(pl.get("ref") or ""))
            if str(punto.id) in presentes or clave in ya_tengo:
                continue
            inyectados.append(SearchResult(
                id=str(punto.id),
                # Por debajo de lo recuperado por la consulta: es apoyo del
                # argumento, no la respuesta a la pregunta.
                score=0.72,
                texto=pl.get("texto", ""),
                ref=pl.get("ref"),
                origen=pl.get("origen") or origen,
                jurisdiccion=pl.get("jurisdiccion"),
                silo=coleccion,
                pdf_url=pl.get("pdf_url") or pl.get("url_pdf") or pl.get("pdf"),
                entidad=pl.get("entidad"),
                materia_meta=pl.get("materia"),
                conceptos_transversales=pl.get("conceptos_transversales"),
                tema_articulo=pl.get("tema_articulo"),
            ))
            presentes.add(str(punto.id))
            ya_tengo.add(clave)

    if inyectados:
        print(f"   🔗 Salto interno: {len(inyectados)} artículos citados traídos al contexto")
        paso("cruzar", str(len(inyectados)))
        return results + inyectados
    return results


async def inject_cross_referenced_articles(
    results: list,
    qdrant_client_obj,
    max_injections: int = 8,
) -> list:
    """
    Scans precedente/holding results for cited federal law articles,
    looks them up in leyes_federales, and injects them into the results.
    
    Returns the augmented results list with cross-referenced articles prepended.
    """
    from qdrant_client.models import Filter, FieldCondition, MatchValue, MatchAny
    
    # Identify which silos contain precedentes
    _precedente_silos = {
        "sentencias_holdings", "sentencias_scjn_holdings",
        *JURIS_SILOS,
        "jurisprudencia_tcc",
    }
    # Also include circuit-specific silos
    for r in results:
        if r.silo and r.silo.startswith("sentencias_") and "circuito" in r.silo:
            _precedente_silos.add(r.silo)
    
    # Collect all cited articles from precedentes
    cited = {}  # (canonical_ley, art_num) → True
    existing_ids = {r.id for r in results}
    # Also track existing articles by ref to avoid duplicates even with different IDs
    existing_refs = {(r.origen or "", r.ref or "") for r in results if r.silo == "leyes_federales"}
    
    for r in results:
        if r.silo not in _precedente_silos:
            continue
        if not r.texto:
            continue
        
        for nums, canonical_ley in _extract_cited_articles(r.texto):
            for num in nums:
                key = (canonical_ley, num.strip())
                if key not in cited:
                    cited[key] = True
    
    if not cited:
        return results
    
    print(f"   📎 Cross-Ref: {len(cited)} artículos citados en precedentes, buscando en leyes_federales...")
    
    # Group by law for efficient queries
    by_law = {}
    for (ley, num) in cited:
        by_law.setdefault(ley, []).append(num)

    # ── SUSTITUIDO (7-ago-2026): del patrón de cadena al número exacto ──
    #
    # Antes se buscaba el artículo probando dos formas literales del campo
    # `ref`: «Artículo 55.» y «Artículo 55 ». Eso fallaba en silencio en
    # cuanto la colección escribía de otra manera —CDMX y Guanajuato usan
    # «Art. 55»—, y costaba hasta dos viajes a Qdrant POR ARTÍCULO.
    #
    # Ahora `articulo_num` existe y está indexado en las 34 colecciones de
    # leyes, así que se pregunta por igualdad exacta y con `MatchAny`: una
    # consulta por ley en vez de dos por artículo, y sin depender de cómo se
    # escribió la referencia. Las consultas van además en paralelo.
    injected = []
    try:
        async def _traer(ley: str, nums: list):
            try:
                return ley, await qdrant_client_obj.scroll(
                    collection_name="leyes_federales",
                    limit=len(nums),
                    scroll_filter=Filter(must=[
                        FieldCondition(key="ley", match=MatchValue(value=ley)),
                        FieldCondition(key="articulo_num", match=MatchAny(any=nums)),
                    ]),
                    with_payload=True,
                    with_vectors=False,
                )
            except Exception:
                return ley, None

        _peticiones = []
        for ley, nums in list(by_law.items())[:4]:
            _numeros = []
            for n in nums[:5]:
                try:
                    _numeros.append(int(str(n).strip()))
                except (TypeError, ValueError):
                    continue
            if _numeros:
                _peticiones.append(_traer(ley, _numeros))

        _respuestas = await asyncio.gather(*_peticiones, return_exceptions=True)

        for _r in _respuestas:
            if len(injected) >= max_injections:
                break
            if isinstance(_r, BaseException) or _r is None:
                continue
            ley, hallado = _r
            if not hallado or not hallado[0]:
                continue
            for point in hallado[0]:
                if len(injected) >= max_injections:
                    break
                if str(point.id) in existing_ids:
                    continue
                payload = point.payload or {}
                sr = SearchResult(
                    id=str(point.id),
                    score=0.90,  # High score so it appears prominently
                    texto=payload.get("texto", ""),
                    ref=payload.get("ref"),
                    origen=payload.get("origen") or ley,
                    jurisdiccion="Federal",
                    silo="leyes_federales",
                    # EL PDF OFICIAL. Faltaba aqui, y era el agujero mas
                    # visible de todos: estos articulos entran con score 0.90
                    # «so it appears prominently», asi que las citas que el
                    # abogado ve primero eran justo las que salian sin
                    # documento. Se leen las dos claves porque la ingesta de
                    # leyes guarda la misma URL en ambas.
                    pdf_url=payload.get("pdf_url") or payload.get("url_pdf"),
                    entidad=payload.get("entidad"),
                    materia_meta=payload.get("materia"),
                    conceptos_transversales=payload.get("conceptos_transversales"),
                    tema_articulo=payload.get("tema_articulo"),
                )
                injected.append(sr)
                existing_ids.add(str(point.id))

    except Exception as e:
        print(f"   ⚠️ Cross-Ref error: {err(e)}")

    if injected:
        print(f"   ✅ Cross-Ref: Inyectados {len(injected)} artículos de ley citados en precedentes")
        paso("cruzar", str(len(injected)))
        # Prepend injected articles so they appear before precedentes in context
        return injected + results
    
    return results


def format_results_as_xml(results: List[SearchResult], estado: Optional[str] = None, prose_mode: bool = False) -> str:
    """
    Formatea resultados en XML para inyección de contexto.
    Escapa caracteres HTML para seguridad.
    Trunca documentos largos para evitar exceder límite de tokens.
    Si estado está presente, marca documentos estatales como FUENTE_PRINCIPAL.
    Si prose_mode=True (modo redacción), omite los campos ratio GraphRAG para no
    interrumpir la síntesis de prosa judicial continua.
    """
    if not results:
        return "<documentos>Sin resultados relevantes encontrados.</documentos>"
    
    # Enrich results missing metadata (origen/ref) by inferring from text
    enrich_missing_metadata(results)
    
    xml_parts = ["<documentos>"]
    
    # Si hay estado, inyectar instrucción de prioridad DENTRO del XML
    if estado:
        estado_humano = estado.replace("_", " ").title()
        xml_parts.append(
            f'<!-- INSTRUCCIÓN: Los documentos marcados tipo="LEGISLACION_ESTATAL" de '
            f'{estado_humano} son la FUENTE PRINCIPAL. En tu sección Fundamento Legal, '
            f'TRANSCRIBE el texto de estos artículos PRIMERO con su [Doc ID: uuid]. '
            f'La jurisprudencia va DESPUÉS como complemento interpretativo. -->'
        )

    if any(r.silo == "doctrina" for r in results):
        xml_parts.append(
            '<!-- INSTRUCCIÓN DOCTRINA: Los documentos tipo="DOCTRINA" son obras '
            'jurídicas de referencia. Úsalos para enriquecer el concepto citándolos '
            'con su [Doc ID: uuid] como cualquier fuente. Si citas TEXTUAL: copia el '
            'pasaje CARÁCTER POR CARÁCTER del documento, máximo 40 palabras, entre '
            'comillas « », seguido de (autor, obra, página) y su [Doc ID]. PROHIBIDO '
            'poner comillas a una paráfrasis: si no copias exacto, parafrasea SIN '
            'comillas. La doctrina ilustra; el fundamento son la ley y la '
            'jurisprudencia. -->'
        )
    
    # ── REGLA DE JERARQUÍA: Reordenar para que CPEUM/leyes precedan jurisprudencia ──
    # Esto garantiza que el LLM vea primero la norma vigente y después las tesis.
    # Evita que jurisprudencia pre-reforma 2024 domine el análisis.
    results = reorder_by_hierarchy(results)

    for r in results:
        # Truncate long documents to fit within token limits
        texto = r.texto
        if len(texto) > MAX_DOC_CHARS:
            texto = texto[:MAX_DOC_CHARS] + "... [truncado]"
        
        escaped_texto = html.escape(texto)
        escaped_ref = html.escape(r.ref or "N/A")
        escaped_origen = html.escape(humanize_origen(r.origen) or "Desconocido")
        escaped_jurisdiccion = html.escape(r.jurisdiccion or "N/A")

        # 🚫 EXCLUSIÓN DE CITAS: Las sentencias de ejemplo NO son fuentes. 
        # Se usan solo para mimetizar estilo, por lo que las filtramos del XML de fuentes.
        if r.silo in SENTENCIA_SILOS.values():
            continue

        # Marcar documentos estatales como FUENTE PRINCIPAL cuando hay estado seleccionado
        # Aplica tanto al silo legacy (leyes_estatales) como a silos dedicados (leyes_edomex, etc.)
        _dedicated_silos = set(ESTADO_SILO.values())
        tipo_tag = ""
        if estado and (r.silo == "leyes_estatales" or r.silo in _dedicated_silos):
            tipo_tag = ' tipo="LEGISLACION_ESTATAL" prioridad="PRINCIPAL"'
        elif r.silo in (*JURIS_SILOS, "jurisprudencia_tcc", "jurisprudencia"):
            tipo_tag = ' tipo="JURISPRUDENCIA" prioridad="COMPLEMENTARIA"'
        elif r.silo == "bloque_constitucional":
            # Distinguish CPEUM from treaties/conventions within bloque_constitucional
            _o = (r.origen or "").lower()
            if any(kw in _o for kw in ("convención", "convencion", "pacto", "protocolo", "declaración", "declaracion", "reglas", "principios", "tratado", "pidcp", "pidesc", "cedaw", "cadh", "dudh", "cat")):
                tipo_tag = ' tipo="TRATADO_DDHH" prioridad="SUPREMA"'
            else:
                tipo_tag = ' tipo="CONSTITUCION" prioridad="SUPREMA"'
        elif r.silo in ("leyes_federales", "codigo_nacional"):
            tipo_tag = ' tipo="LEY_FEDERAL" prioridad="PRIMARIA"'
        elif r.silo == "doctrina":
            # La doctrina ilustra: prioridad explícita para que el modelo no la
            # trate como norma. La instrucción de cita exacta va aparte, abajo.
            tipo_tag = ' tipo="DOCTRINA" prioridad="ILUSTRATIVA"'
        
        # Obtener jerarquía para el XML
        jerarquia = _get_jerarquia_label(r.silo)
        
        # Campos GraphRAG de jurisprudencia_nacional_v2
        # En prose_mode (redacción judicial) se omiten: los campos pre-extraídos
        # fragmentan la síntesis y el modelo tiende a citar sumarios en vez de
        # tejer la jurisprudencia en prosa continua.
        ratio_tags = ""
        if r.silo in JURIS_SILOS and not prose_mode:
            if r.ratio_decidendi:
                ratio_tags += f'\n<ratio_decidendi>{html.escape(r.ratio_decidendi)}</ratio_decidendi>'
            if r.condicion_de_aplicacion:
                ratio_tags += f'\n<condicion_de_aplicacion>{html.escape(r.condicion_de_aplicacion)}</condicion_de_aplicacion>'
            if r.distincion:
                ratio_tags += f'\n<distincion>{html.escape(r.distincion)}</distincion>'
            if r.sentido_del_criterio:
                ratio_tags += f'\n<sentido_del_criterio>{html.escape(r.sentido_del_criterio)}</sentido_del_criterio>'

        # ── FIX 2026-05-25: Inyectar metadata de jurisprudencia en XML ──────
        # ANTES: registro, tesis_num, instancia etc. existían en SearchResult
        # pero NO se incluían en el XML. El system prompt pedía al LLM citar
        # con "Registro digital: [numero]" sin darle los datos reales → el LLM
        # INVENTABA registros, rubros e instancias = ALUCINACIONES CRÍTICAS.
        # AHORA: Los campos reales de Qdrant se inyectan como atributos XML.
        juris_attrs = ""
        _juris_silos = (*JURIS_SILOS,
                        "jurisprudencia_tcc", "jurisprudencia")
        if r.silo in _juris_silos:
            if r.registro:
                juris_attrs += f' registro="{html.escape(str(r.registro))}"'
            if r.tesis_num:
                juris_attrs += f' tesis="{html.escape(str(r.tesis_num))}"'
            if r.instancia_meta:
                juris_attrs += f' instancia="{html.escape(str(r.instancia_meta))}"'
            if r.tipo_criterio:
                juris_attrs += f' tipo_criterio="{html.escape(str(r.tipo_criterio))}"'
            if r.materia_meta:
                juris_attrs += f' materia="{html.escape(str(r.materia_meta))}"'

        xml_parts.append(
            f'<documento id="{r.id}" ref="{escaped_ref}" '
            f'origen="{escaped_origen}" silo="{r.silo}" '
            f'jerarquia="{jerarquia}" '
            f'jurisdiccion="{escaped_jurisdiccion}" score="{r.score:.4f}"{tipo_tag}{juris_attrs}>\n'
            f'{escaped_texto}{ratio_tags}\n'
            f'</documento>'
        )
    xml_parts.append("</documentos>")

    return "\n".join(xml_parts)


_STYLE_EXAMPLE_STRIP_PATTERNS = [
    re.compile(r'\[Doc ID:[^\]]*\]', re.IGNORECASE),
    re.compile(r'\[\s*\d+\s*\]'),  # referencias numéricas tipo [3]
    re.compile(r'Registro digital:?\s*\d+', re.IGNORECASE),
    re.compile(r'\b\d+[aª]?\.?/J\.?\s*\d+/\d{4}\b'),  # jurisprudencias tipo 1a./J. 46/2014
    re.compile(r'\bTesis\s+[IVX\d]+[\w./\-]*', re.IGNORECASE),
]


def _sanitize_style_example(texto: str) -> str:
    """Elimina citas específicas del texto del ejemplo para evitar que el LLM las copie."""
    for pat in _STYLE_EXAMPLE_STRIP_PATTERNS:
        texto = pat.sub("", texto)
    # Limpiar espacios dobles y puntuación huérfana
    texto = re.sub(r'\s+([,.;:])', r'\1', texto)
    texto = re.sub(r'\s{2,}', ' ', texto)
    texto = re.sub(r'\(\s*\)', '', texto)
    return texto.strip()


def format_sentencias_as_examples(results: list, max_examples: int = 3, max_chars: int = 2000) -> str:
    """Extrae resultados de silos de sentencias y los formatea como modelos de estilo.

    Estos ejemplos se inyectan en el prompt de redacción para que el LLM
    mimetice el tono, estructura y prosa judicial de alto nivel.
    NO son fuentes citables — se limpian las citas internas para prevenir
    que el LLM copie Doc IDs, registros o jurisprudencias inválidas.
    """
    _sentencia_silo_set = set(SENTENCIA_SILOS.values())
    ejemplos = [r for r in results if r.silo in _sentencia_silo_set]
    if not ejemplos:
        return ""

    # Top N por score
    ejemplos.sort(key=lambda r: r.score, reverse=True)
    ejemplos = ejemplos[:max_examples]

    parts = [
        "<modelos_de_estilo>",
        "<!-- ADVERTENCIA CRÍTICA: Estos fragmentos son SOLO referencias de PROSA JUDICIAL. "
        "NO los cites. NO copies ningún número, referencia, jurisprudencia o Doc ID que aparezca "
        "en su interior. Las ÚNICAS fuentes citables están en <documentos> con su Doc ID real. -->",
    ]
    for i, r in enumerate(ejemplos, 1):
        texto = _sanitize_style_example(r.texto)
        if len(texto) > max_chars:
            texto = texto[:max_chars] + "..."
        if len(texto) < 200:  # ejemplo demasiado corto tras sanitizar, descartar
            continue
        parts.append(
            f'<ejemplo n="{i}">\n'
            f'{html.escape(texto)}\n'
            f'</ejemplo>'
        )
    parts.append("</modelos_de_estilo>")

    # Si tras sanitizar no quedó ningún ejemplo útil, retornar vacío
    if len(parts) <= 3:
        return ""
    return "\n".join(parts)


# ══════════════════════════════════════════════════════════════════════════════
# VALIDADOR DE CITAS (Citation Grounding Verification)
# ══════════════════════════════════════════════════════════════════════════════

# Regex para extraer Doc IDs del formato [Doc ID: uuid/id]
DOC_ID_PATTERN = re.compile(r'\[Doc ID:\s*([^\]\s]+)\]', re.IGNORECASE)


def extract_doc_ids(text: str) -> List[str]:
    """
    Extrae todos los Doc IDs citados en el texto.
    Formato esperado: [Doc ID: uuid]
    """
    matches = DOC_ID_PATTERN.findall(text)
    return list(set(matches))  # Únicos


def _uuid_edit_distance(a: str, b: str) -> int:
    """Distancia de edición simplificada (Levenshtein) para UUIDs.
    Optimizada: solo compara los primeros 36 chars (largo de UUID)."""
    a, b = a[:36].lower(), b[:36].lower()
    if len(a) != len(b):
        return max(len(a), len(b))
    return sum(1 for x, y in zip(a, b) if x != y)


def repair_hallucinated_uuids(
    response_text: str,
    doc_id_map: Dict[str, "SearchResult"],
) -> str:
    """
    🔒 CANDADO ANTI-ALUCINACIÓN DE UUIDS — Post-procesamiento obligatorio.
    
    Los LLMs (especialmente en modo reasoning/thinking) tienden a:
    1. Alterar 1-3 caracteres de un UUID al reconstruirlo de memoria
    2. Inventar UUIDs que no existen en el contexto
    3. Truncar UUIDs (cortar los últimos caracteres)
    
    Este reparador busca cada [Doc ID: uuid] en la respuesta y, si no existe
    exactamente en doc_id_map, intenta repararlo con fuzzy match:
    - Prefix match (>= 28 chars coincidentes)
    - Edit distance <= 4 caracteres
    Si se encuentra un match, reemplaza el UUID alucinado por el real.
    """
    if not doc_id_map or not response_text:
        return response_text
    
    valid_ids = list(doc_id_map.keys())
    valid_ids_lower = {uid.lower(): uid for uid in valid_ids}
    
    def _find_best_match(hallucinated: str) -> Optional[str]:
        h = hallucinated.lower().strip()
        
        # Exact match (case-insensitive)
        if h in valid_ids_lower:
            return valid_ids_lower[h]
        
        # Strategy 1: Prefix match (UUID might be truncated or have trailing noise)
        for vid_lower, vid_original in valid_ids_lower.items():
            # Match if first 28+ chars of UUID match (UUID = 36 chars with dashes)
            prefix_len = min(len(h), len(vid_lower))
            if prefix_len >= 28:
                matching_chars = sum(1 for a, b in zip(h[:prefix_len], vid_lower[:prefix_len]) if a == b)
                if matching_chars >= 28:
                    return vid_original
        
        # Strategy 2: Edit distance (1-4 char differences = likely hallucination)
        best_dist = 5  # Max allowed edit distance
        best_match = None
        for vid_lower, vid_original in valid_ids_lower.items():
            dist = _uuid_edit_distance(h, vid_lower)
            if dist < best_dist:
                best_dist = dist
                best_match = vid_original
        
        return best_match
    
    repairs_made = 0
    
    def _repair(match):
        nonlocal repairs_made
        hallucinated_id = match.group(1)
        
        # Already valid? Skip
        if hallucinated_id in doc_id_map or hallucinated_id.lower() in valid_ids_lower:
            return match.group(0)
        
        repaired = _find_best_match(hallucinated_id)
        if repaired:
            repairs_made += 1
            print(f"   🔧 UUID REPARADO: {hallucinated_id[:16]}... → {repaired[:16]}...")
            return f"[Doc ID: {repaired}]"
        else:
            print(f"   ❌ UUID IRREPARABLE (sin match fuzzy): {hallucinated_id[:20]}...")
            return match.group(0)
    
    repaired_text = DOC_ID_PATTERN.sub(_repair, response_text)
    
    if repairs_made > 0:
        print(f"   🔒 REPARACIÓN COMPLETA: {repairs_made} UUIDs alucinados corregidos")
    
    return repaired_text


_RE_REGISTRO_CITADO = re.compile(
    r"[Rr]egistro(?:\s+digital)?\s*(?:n[uú]m(?:ero)?\.?)?\s*[:.]?\s*(\d{6,8})")


def registros_fuera_del_contexto(respuesta: str, search_results: List[SearchResult]) -> List[str]:
    """Registros digitales citados que NO estaban en el contexto recuperado.

    POR QUÉ ESTO NO SE PODÍA RESOLVER PIDIÉNDOLO (8-ago-2026)
    ---------------------------------------------------------
    El prompt maestro prohíbe inventar registros de forma explícita y en
    cuatro sitios distintos. Aun así, un abogado reportó que «al solicitarle
    tesis, SIEMPRE se equivoca». Al contrastar sus conversaciones contra el
    Semanario: los 180 registros citados EXISTÍAN —ni uno inventado— pero de
    12 pares (registro ↔ rubro) revisados, los 12 estaban MAL EMPAREJADOS.
    «TUTELA JUDICIAL EFECTIVA» (2000004) es en realidad «CHEQUES. SON TÍTULOS
    PAGADEROS A LA VISTA».

    Ninguno de esos registros estaba en nuestro corpus: el modelo los escribió
    de memoria y acertaron por azar. El espacio de registros es tan denso que
    casi cualquier número plausible corresponde a ALGUNA tesis real, así que
    comprobar la existencia contra el Semanario no detecta nada. Delatan el
    patrón las series correlativas —2000001-2000004, 2008402-2008407—: los
    registros reales de un mismo tema nunca salen seguidos.

    Eso es más grave que inventar un número: la cita PARECE verificable y
    resiste el primer clic. El abogado que la copia a un escrito queda
    expuesto ante un tribunal.

    La única defensa que no depende de la buena voluntad del modelo es
    aritmética: si el número no viaja en el contexto, no puede citarse.
    """
    if not respuesta:
        return []
    del_contexto = {
        str(r.registro).strip()
        for r in (search_results or [])
        if getattr(r, "registro", None)
    }
    fuera, vistos = [], set()
    for m in _RE_REGISTRO_CITADO.finditer(respuesta):
        reg = m.group(1)
        if reg in vistos:
            continue
        vistos.add(reg)
        if reg not in del_contexto:
            fuera.append(reg)
    return fuera


def build_doc_id_map(search_results: List[SearchResult]) -> Dict[str, SearchResult]:
    """
    Construye un diccionario de Doc ID -> SearchResult para validación rápida.
    """
    return {result.id: result for result in search_results}


def validate_citations(
    response_text: str,
    retrieved_docs: Dict[str, SearchResult]
) -> ValidationResult:
    """
    Valida que todas las citas en la respuesta del LLM correspondan
    a documentos realmente recuperados de Qdrant.
    
    Args:
        response_text: Texto de respuesta del LLM
        retrieved_docs: Diccionario de Doc ID -> SearchResult de docs recuperados
    
    Returns:
        ValidationResult con estadísticas y detalle de cada cita
    """
    cited_ids = extract_doc_ids(response_text)
    
    if not cited_ids:
        # Sin citas - permitido pero sin verificación
        return ValidationResult(
            total_citations=0,
            valid_count=0,
            invalid_count=0,
            citations=[],
            confidence_score=1.0  # Sin citas = no hay errores
        )
    
    validations = []
    valid_count = 0
    invalid_count = 0
    
    for doc_id in cited_ids:
        if doc_id in retrieved_docs:
            doc = retrieved_docs[doc_id]
            validations.append(CitationValidation(
                doc_id=doc_id,
                exists_in_context=True,
                status="valid",
                source_ref=doc.ref
            ))
            valid_count += 1
        else:
            validations.append(CitationValidation(
                doc_id=doc_id,
                exists_in_context=False,
                status="invalid",
                source_ref=None
            ))
            invalid_count += 1
    
    total = valid_count + invalid_count
    confidence = valid_count / total if total > 0 else 1.0
    
    return ValidationResult(
        total_citations=total,
        valid_count=valid_count,
        invalid_count=invalid_count,
        citations=validations,
        confidence_score=confidence
    )


def annotate_invalid_citations(response_text: str, invalid_ids: Set[str]) -> str:
    """
    Anota las citas inválidas en el texto con una advertencia visual.
    
    Ejemplo:
        [Doc ID: abc123] -> [Doc ID: abc123]  *[Cita no verificada]*
    """
    if not invalid_ids:
        return response_text
    
    def replace_invalid(match):
        doc_id = match.group(1)
        original = match.group(0)
        if doc_id.lower() in [i.lower() for i in invalid_ids]:
            return f"{original}  *[Cita no verificada]*"
        return original
    
    return DOC_ID_PATTERN.sub(replace_invalid, response_text)


def get_valid_doc_ids_prompt(retrieved_docs: Dict[str, SearchResult]) -> str:
    """
    Genera una lista de Doc IDs válidos para incluir en prompts de regeneración.
    """
    if not retrieved_docs:
        return "No hay documentos disponibles para citar."
    
    lines = ["DOCUMENTOS DISPONIBLES PARA CITAR (usa EXCLUSIVAMENTE estos Doc IDs — NO inventes otros):"]
    for doc_id, doc in retrieved_docs.items():
        ref = doc.ref or "Sin referencia"
        lines.append(f"  - [Doc ID: {doc_id}] → {ref[:100]}")
    
    return "\n".join(lines)




# ══════════════════════════════════════════════════════════════════════════════
# ARTICLE-AWARE RERANKING
# ══════════════════════════════════════════════════════════════════════════════

def detect_article_numbers(query: str) -> List[str]:
    """Detecta números de artículos mencionados explícitamente en la query."""
    pattern = r'art[ií]culos?\s+(\d+(?:\s*(?:bis|ter|qu[aá]ter))?)'
    matches = re.findall(pattern, query, re.IGNORECASE)
    return [m.strip() for m in matches]


def rerank_by_article_match(results: List[SearchResult], article_numbers: List[str]) -> List[SearchResult]:
    """
    Boostea resultados que contienen el número de artículo específico solicitado.
    Esto resuelve el problema de que artículos semánticamente lejanos pero
    específicamente solicitados no aparezcan en los resultados.
    """
    if not article_numbers:
        return results
    
    for r in results:
        for num in article_numbers:
            # Buscar "Artículo 941" o "Art. 941" en el texto del chunk
            if re.search(rf'art[ií]culos?\.?\s*{re.escape(num)}\b', r.texto, re.IGNORECASE):
                r.score += 0.5  # Boost significativo para match exacto
                print(f"   🎯 BOOST artículo {num} encontrado en {r.silo}: +0.5 score")
    
    results.sort(key=lambda x: x.score, reverse=True)
    return results


# Búsqueda densa a secas, y es una decisión, no un accidente.
#
# Historia completa, porque ya nos confundió una vez: durante meses el intento
# híbrido reventaba al instante por el bug de `Query` (typing.Union) y TODO
# caía al modo denso. Al arreglar el bug (commit 3fa550238) la parte sparse se
# ejecutó por primera vez… y el clúster se hundió: el índice sparse vive en
# disco y no cabe en 4 GiB de RAM. Medido el 31-jul-2026, misma ráfaga de 16
# búsquedas en paralelo:
#
#     híbrida (dense+sparse):  19,095 ms, picos de 19 s   ← timeouts de 30 s
#     densa a secas:              325 ms
#
# La calidad que los usuarios conocen ES la del modo denso. Cuando el clúster
# tenga RAM para el índice sparse (8 GiB+), poner False y medir otra vez.
_SOLO_DENSO = True

# Alias histórico: el código de fallback lo enciende si reapareciera el bug.
_HYBRID_PREFETCH_BROKEN = _SOLO_DENSO

async def hybrid_search_single_silo(
    collection: str,
    query: str,
    dense_vector: List[float],
    sparse_vector: SparseVector,
    filter_: Optional[Filter],
    top_k: int,
    alpha: float,
) -> List[SearchResult]:
    """
    Ejecuta búsqueda en un silo.
    Auto-detecta si la colección tiene sparse vectors para usar híbrido o solo dense.
    RESILIENTE: Si el filtro causa error 400 (índice faltante), reintenta SIN filtro.
    """
    global _HYBRID_PREFETCH_BROKEN

    # La v3 vive en otro espacio vectorial: si se le manda el vector de 1536
    # devuelve 400, esta función acaba en el except y devuelve lista vacía sin
    # decir por qué.
    #
    # VA AQUÍ Y NO DENTRO DE `_do_search`. Ponerlo dentro parecía inocente y
    # tumbó los 51 silos restantes: al haber una ASIGNACIÓN a `dense_vector`
    # dentro de la función anidada, Python la trata como local de toda ella, así
    # que en las colecciones donde la condición NO se cumple se leía antes de
    # existir. UnboundLocalError → except → cero resultados. Las leyes no
    # perdían la puja: ni siquiera se buscaban.
    if _vector_de(collection) != "dense":
        dense_vector = await _embedding_juris(query)

    async def _do_search(search_filter: Optional[Filter]) -> list:
        """Ejecuta la búsqueda con el filtro dado (protegida por semáforo)."""
        async with QDRANT_SEM:
            col_info = await qdrant_client.get_collection(collection)
            sparse_vectors_config = col_info.config.params.sparse_vectors
            has_sparse = sparse_vectors_config is not None and len(sparse_vectors_config) > 0
        
        # Threshold diferenciado: jurisprudencia y silos estatales necesitan mayor recall
        if collection in JURIS_SILOS:
            threshold = 0.02
        elif collection.startswith("leyes_") and collection != "leyes_federales":
            threshold = 0.02  # State silos: lower threshold for colloquial queries
        else:
            threshold = 0.03
        
        if has_sparse and not _HYBRID_PREFETCH_BROKEN:
            # Prefetch con RRF fusion.
            # Para jurisprudencia_nacional_v2: triple prefetch (sparse + dense + ratio)
            # Para otras colecciones: dual prefetch (sparse + dense)
            prefetches = [
                Prefetch(
                    query=sparse_vector,
                    using="sparse",
                    limit=top_k * 5,
                    filter=search_filter,
                ),
                Prefetch(
                    query=dense_vector,
                    using=_vector_de(collection),
                    limit=top_k * 5,
                    filter=search_filter,
                ),
            ]
            if collection in JURIS_SILOS:
                # 3er prefetch: busca por ratio_decidendi semánticamente
                prefetches.append(
                    Prefetch(
                        query=dense_vector,
                        using="ratio",
                        limit=top_k * 3,
                        filter=search_filter,
                    )
                )
            return await qdrant_client.query_points(
                collection_name=collection,
                prefetch=prefetches,
                query=FusionQuery(fusion=Fusion.RRF),
                limit=top_k,
                query_filter=search_filter,
                with_payload=True,
                score_threshold=None,  # RRF scores are on a different scale
            )
        else:
            return await qdrant_client.query_points(
                collection_name=collection,
                query=dense_vector,
                using=_vector_de(collection),
                limit=top_k,
                query_filter=search_filter,
                with_payload=True,
                score_threshold=threshold,
            )
    
    def _parse_results(results) -> List[SearchResult]:
        """Convierte puntos de Qdrant en SearchResult."""
        parsed = []
        for point in results.points:
            payload = point.payload or {}
            # Los silos EF (sentencias_ef y SCJN particionadas) almacenan el
            # contenido en `chunk_text`; otros silos usan `texto` o `text`.
            texto = _con_rubro(payload)
            origen_raw = payload.get("origen") or ""
            
            # ── Extract registro: payload > texto tags > origen prefix ──
            registro = str(payload.get("registro")) if payload.get("registro") else None
            if not registro:
                # Try [REGISTRO: NNNNN] in texto
                _reg_m = re.search(r'\[REGISTRO:\s*(\d+)\]', texto)
                if _reg_m:
                    registro = _reg_m.group(1)
            if not registro:
                # Try leading digits in origen like "2008492_I.3o.C..."
                _orig_m = re.match(r'^(\d{5,7})[_\s]', origen_raw)
                if _orig_m:
                    registro = _orig_m.group(1)
            
            # ── Extract tesis_num: payload > texto tags > ref ──
            # v2 la llama `numero_tesis`; v3, `clave_tesis`. Leer sólo una deja
            # la clave en blanco en todas las citas de la app.
            tesis_num = (payload.get("tesis") or payload.get("numero_tesis")
                         or payload.get("clave_tesis") or payload.get("tesis_num"))
            if not tesis_num:
                _tes_m = re.search(r'\[TESIS:\s*([^\]]+)\]', texto)
                if _tes_m:
                    tesis_num = _tes_m.group(1).strip()
            
            # ── Extract tipo: payload > texto tags ──
            tipo_criterio = payload.get("tipo", payload.get("tipo_criterio"))
            if not tipo_criterio:
                _tipo_m = re.search(r'\[TIPO:\s*([^\]]+)\]', texto)
                if _tipo_m:
                    tipo_criterio = _tipo_m.group(1).strip()
            
            # ── Extract instancia: payload > texto tags ──
            instancia = payload.get("instancia")
            if not instancia:
                _inst_m = re.search(r'\[INSTANCIA:\s*([^\]]+)\]', texto)
                if _inst_m:
                    instancia = _inst_m.group(1).strip()
            
            # ── Extract materia: payload > texto tags ──
            materia = payload.get("materia")
            if isinstance(materia, list):
                materia = ", ".join(str(m) for m in materia) if materia else None
            if not materia:
                _mat_m = re.search(r'\[MATERIA:\s*([^\]]+)\]', texto)
                if _mat_m:
                    materia = _mat_m.group(1).strip().rstrip(",")
            
            parsed.append(SearchResult(
                id=str(point.id),
                score=point.score,
                texto=texto,
                # Sin `ref` la interfaz rotula la cita como «Disposición legal» y
                # no la reconoce como tesis: el abogado se queda con un título de
                # ley, sin artículo y sin fuente. El rubro es lo que la nombra.
                ref=payload.get("ref") or payload.get("rubro") or tesis_num or (
                    f"Registro {registro}" if registro else None),
                # «REGISTRO_CLAVE.txt» cuando no hay origen propio: es la
                # tercera puerta del visor de tesis y de donde saca el número
                # para el enlace al Semanario. Ver `_origen_tesis`.
                origen=(origen_raw or _origen_tesis(payload) or None),
                jurisdiccion=payload.get("jurisdiccion"),
                entidad=payload.get("entidad"),
                silo=collection,
                pdf_url=payload.get("pdf_url") or payload.get("url_pdf"),
                registro=registro,
                tesis_num=tesis_num,
                tipo_criterio=tipo_criterio,
                instancia_meta=instancia,
                materia_meta=materia,
                # Sólo v3: la cita canónica redactada por la Corte, para
                # copiarla en vez de componerla, y si el criterio OBLIGA.
                localizacion=payload.get("localizacion"),
                vincula=payload.get("vincula"),
                # LLM Tagging fields (Concept Boost)
                conceptos_transversales=payload.get("conceptos_transversales"),
                tema_articulo=payload.get("tema_articulo"),
                ratio_decidendi=payload.get("ratio_decidendi"),
                condicion_de_aplicacion=payload.get("condicion_de_aplicacion"),
                distincion=payload.get("distincion") if payload.get("distincion") != "null" else None,
                sentido_del_criterio=payload.get("sentido_del_criterio"),
                obiter_dicta=payload.get("obiter_dicta") if payload.get("obiter_dicta") != "null" else None,
            ))
        return parsed
    
    try:
        # Intento 1: Búsqueda híbrida (prefetch sparse → dense rerank)
        results = await _do_search(filter_)
        search_results = _parse_results(results)
        
        # FALLBACK: Si hybrid devuelve 0 resultados pero la colección tiene sparse,
        # reintentar con SOLO dense. Esto ocurre cuando el sparse prefetch no encuentra
        # candidatos (ej: modelo BM25 diferente entre indexación y query).
        if not search_results:
            col_info = await qdrant_client.get_collection(collection)
            sparse_cfg = col_info.config.params.sparse_vectors
            has_sparse = sparse_cfg is not None and len(sparse_cfg) > 0
            if has_sparse:
                print(f"   ⚠️ Hybrid devolvió 0 en {collection}, fallback a dense-only...")
                threshold = 0.02 if collection in JURIS_SILOS else 0.03
                dense_results = await qdrant_client.query_points(
                    collection_name=collection,
                    query=dense_vector,
                    using=_vector_de(collection),
                    limit=top_k,
                    query_filter=filter_,
                    with_payload=True,
                    score_threshold=threshold,
                )
                search_results = _parse_results(dense_results)
                print(f"   ✅ Dense-only fallback: {len(search_results)} resultados en {collection}")
        
        return search_results
    
    except Exception as e:
        error_msg = str(e)
        # FALLBACK: typing.Union error (Python 3.14 + qdrant-client compat)
        # → bypass Prefetch/Query construction, use dense-only search
        # Set global flag so ALL subsequent searches skip hybrid attempt
        if "typing.Union" in error_msg or "Cannot instantiate" in error_msg:
            _HYBRID_PREFETCH_BROKEN = True
            print(f"   ⚠️ typing.Union error en {collection}, fallback a dense-only (hybrid DISABLED globally)...")
            try:
                threshold = 0.02 if collection in JURIS_SILOS else 0.03
                dense_results = await qdrant_client.query_points(
                    collection_name=collection,
                    query=dense_vector,
                    using=_vector_de(collection),
                    limit=top_k,
                    query_filter=filter_,
                    with_payload=True,
                    score_threshold=threshold,
                )
                search_results = _parse_results(dense_results)
                print(f"   ✅ Dense-only fallback: {len(search_results)} resultados en {collection}")
                return search_results
            except Exception as dense_e:
                print(f"   ❌ Dense-only fallback también falló en {collection}: {dense_e}")
                return []

        # Si el error es por índice faltante, reintentar SIN filtro de metadata
        if "400" in error_msg or "Index required" in error_msg:
            print(f"   ⚠️  Filtro falló en {collection} (índice faltante), reintentando sin filtro...")
            try:
                results = await _do_search(None)  # Sin filtro
                search_results = []
                for point in results.points:
                    payload = point.payload or {}
                    search_results.append(SearchResult(
                        id=str(point.id),
                        score=point.score,
                        texto=payload.get("texto", payload.get("text", "")),
                        ref=payload.get("ref"),
                        origen=payload.get("origen") or payload.get("ley"),
                        jurisdiccion=payload.get("jurisdiccion"),
                        entidad=payload.get("entidad"),
                        silo=collection,
                        pdf_url=payload.get("pdf_url") or payload.get("url_pdf"),
                    ))
                return search_results
            except Exception as retry_e:
                print(f"   ❌ Retry sin filtro también falló en {collection}: {retry_e}")
                return []
        
        print(f"   ❌ Error en búsqueda sobre {collection}: {err(e)}")
        return []



async def _extract_juris_concepts(query: str) -> str:
    """
    Extrae conceptos jurídicos clave de la consulta para buscar jurisprudencia.
    Devuelve una cadena de términos optimizados para matching con tesis.
    """
    try:
        response = await chat_client.chat.completions.create(
            model=CHAT_MODEL,
            messages=[
                {"role": "system", "content": (
                    "Eres un experto en jurisprudencia mexicana. Dado un query legal, "
                    "extrae 5-8 conceptos clave que aparecerían en tesis de la SCJN o "
                    "tribunales colegiados sobre este tema. Incluye: derechos involucrados, "
                    "figuras jurídicas, términos procesales y sinónimos jurídicos. "
                    "Responde SOLO con los términos separados por espacios, sin explicación."
                )},
                {"role": "user", "content": query}
            ],
            temperature=1,
            max_completion_tokens=80,
            **AYUDANTES_KW,
        )
        concepts = response.choices[0].message.content.strip()
        print(f"   ⚖️ Conceptos jurisprudencia extraídos: {concepts}")
        return concepts
    except Exception as e:
        print(f"   ⚠️ Extracción de conceptos falló: {err(e)}")
        return query  # Fallback: usar el query original

async def _extract_sentencia_temas(doc_content: str) -> str:
    """
    Extracción dinámica de temas jurídicos de una sentencia usando LLM rápido (CHAT_MODEL).
    Reemplaza las expresiones regulares para permitir RAG 'libre' de cualquier materia.
    """
    try:
        # Usar los primeros 15000 chars donde suele estar la litis / resultandos / vistos
        snippet = doc_content[:15000]
        response = await chat_client.chat.completions.create(
            model=CHAT_MODEL,
            messages=[
                {"role": "system", "content": (
                    "Analiza el siguiente fragmento de una sentencia o proyecto judicial "
                    "y extrae de 5 a 8 conceptos clave o frases cortas que describan el TEMA SUSTANTIVO CENTRAL "
                    "y LA ACCIÓN PRINCIPAL del caso. Ejemplo: 'acción reivindicatoria', 'rescisión de contrato civil', "
                    "'pensión alimenticia', 'divorcio incausado'. No uses oraciones completas. "
                    "Responde SOLO con los conceptos clave separados por comas."
                )},
                {"role": "user", "content": snippet}
            ],
            temperature=1,
            max_completion_tokens=80,
            **AYUDANTES_KW,
        )
        temas = response.choices[0].message.content.strip()
        print(f"   🧠 Extracción dinámica de temas (RAG Libre): {temas}")
        return temas
    except Exception as e:
        print(f"   ⚠️ Extracción dinámica falló: {err(e)}")
        return ""


async def _jurisprudencia_boost_search(query: str, exclude_ids: set) -> List[SearchResult]:
    """
    Búsqueda enfocada en jurisprudencia_nacional con score_threshold bajo
    para maximizar recall de tesis relevantes.
    """
    try:
        # El mismo tropiezo que en la búsqueda por silo: esta función SIEMPRE
        # consulta la jurisprudencia, así que su vector tiene que ser el del
        # modelo con que se vectorizó esa colección. Con el de por omisión
        # devolvía 400 y el refuerzo se quedaba mudo.
        _col_juris = FIXED_SILOS["jurisprudencia"]
        dense_vector = (await _embedding_juris(query)
                        if _vector_de(_col_juris) != "dense"
                        else await get_dense_embedding(query))
        sparse_vector = get_sparse_embedding(query)

        # Verificar si tiene sparse vectors
        col_info = await qdrant_client.get_collection(_col_juris)
        sparse_vectors_config = col_info.config.params.sparse_vectors
        has_sparse = sparse_vectors_config is not None and len(sparse_vectors_config) > 0

        if has_sparse:
            try:
                results = await qdrant_client.query_points(
                    collection_name=FIXED_SILOS["jurisprudencia"],
                    prefetch=[
                        Prefetch(query=sparse_vector, using="sparse", limit=50, filter=None),
                        Prefetch(query=dense_vector, using="ratio", limit=30, filter=None),
                    ],
                    query=dense_vector,
                    using=_vector_de(FIXED_SILOS["jurisprudencia"]),
                    limit=10,
                    query_filter=None,
                    with_payload=True,
                    score_threshold=0.01,  # Muy bajo para máximo recall
                )
            except Exception as prefetch_err:
                # Fallback if Prefetch crashes (typing.Union on Python 3.14)
                print(f"      ⚠️ Prefetch falló en juris boost: {prefetch_err}, usando dense-only...")
                results = await qdrant_client.query_points(
                    collection_name=FIXED_SILOS["jurisprudencia"],
                    query=dense_vector,
                    using=_vector_de(FIXED_SILOS["jurisprudencia"]),
                    limit=10,
                    query_filter=None,
                    with_payload=True,
                    score_threshold=0.01,
                )
        else:
            results = await qdrant_client.query_points(
                collection_name=FIXED_SILOS["jurisprudencia"],
                query=dense_vector,
                using=_vector_de(FIXED_SILOS["jurisprudencia"]),
                limit=10,
                query_filter=None,
                with_payload=True,
                score_threshold=0.01,  # Muy bajo para máximo recall
            )

        search_results = []
        for point in results.points:
            if str(point.id) in exclude_ids:
                continue
            payload = point.payload or {}
            # ── Identidad de la tesis ────────────────────────────────────────
            #
            # Esta ruta leia `ref` y `origen` del payload, y la coleccion
            # jurisprudencia_nacional_v2 NO TIENE esas claves: las suyas son
            # registro, numero_tesis, instancia, tipo, materia, epoca y rubro.
            # Ambas salian en None y, sobre todo, no se copiaba `registro`.
            #
            # Consecuencia en la app: sin `registro` ni `tesis_num`, el visor
            # no reconoce la cita como tesis —la rotula «Disposicion legal»— y
            # tampoco puede construir el enlace al Semanario
            # (sjf2.scjn.gob.mx/detalle/tesis/<registro>), que es el respaldo
            # que tienen las tesis cuando no hay PDF. El abogado se quedaba con
            # un titulo de ley, sin articulo y sin fuente que consultar. Es la
            # captura que reporto David.
            _registro = payload.get("registro")
            _registro = str(_registro) if _registro else None
            # v3 lo guarda como `clave_tesis`; v2 como `numero_tesis`. Sin
            # leer los dos, la app pierde la clave en TODAS las citas.
            _tesis_num = (payload.get("numero_tesis") or payload.get("clave_tesis")
                          or payload.get("tesis_num"))
            _materia = payload.get("materia")
            if isinstance(_materia, list):
                _materia = ", ".join(str(m) for m in _materia) if _materia else None

            search_results.append(SearchResult(
                id=str(point.id),
                score=point.score,
                texto=_con_rubro(payload),
                ref=(payload.get("ref") or payload.get("rubro") or _tesis_num
                     or (f"Registro {_registro}" if _registro else None)),
                origen=(payload.get("origen") or payload.get("ley")
                        or _origen_tesis(payload)),
                jurisdiccion=payload.get("jurisdiccion"),
                entidad=payload.get("entidad"),
                silo=FIXED_SILOS["jurisprudencia"],
                pdf_url=payload.get("pdf_url") or payload.get("url_pdf"),
                registro=_registro,
                tesis_num=_tesis_num,
                tipo_criterio=payload.get("tipo") or payload.get("tipo_criterio"),
                instancia_meta=payload.get("instancia"),
                materia_meta=_materia,
                localizacion=payload.get("localizacion"),
                vincula=payload.get("vincula"),
                ratio_decidendi=payload.get("ratio_decidendi"),
                condicion_de_aplicacion=payload.get("condicion_de_aplicacion"),
                distincion=payload.get("distincion") if payload.get("distincion") != "null" else None,
                sentido_del_criterio=payload.get("sentido_del_criterio"),
                obiter_dicta=payload.get("obiter_dicta") if payload.get("obiter_dicta") != "null" else None,
            ))
        
        print(f"      ⚖️ Boost query '{query[:60]}...' → {len(search_results)} tesis")
        return search_results
        
    except Exception as e:
        print(f"      ⚠️ Boost search falló: {err(e)}")
        return []


# ══════════════════════════════════════════════════════════════════════════════
# CROSS-SILO ENRICHMENT: Segunda pasada para encadenar fuentes
# ══════════════════════════════════════════════════════════════════════════════

def _extract_legal_refs(results: List[SearchResult], max_refs: int = 3) -> List[str]:
    """
    Extrae referencias legales (ley + artículo) de los textos recuperados.
    Retorna queries de enriquecimiento como: "artículo 17 CPEUM acceso justicia"
    """
    import re
    refs = []
    seen = set()
    
    # Patrones para extraer referencias legales mexicanas
    patterns = [
        # "artículo 19 Bis de la Ley de Procedimientos Administrativos"
        r'[Aa]rt[íi]culo\s+(\d+(?:\s*[Bb]is)?(?:\s*[A-Z])?)\s+(?:de\s+la\s+|del\s+)?(.{10,60}?)(?:\.|,|;|\n)',
        # "art. 17 CPEUM" or "art. 123 LFT"  
        r'[Aa]rt\.?\s*(\d+(?:\s*[Bb]is)?)\s+(?:de\s+la\s+|del\s+)?([A-ZÁÉÍÓÚÑ][A-Za-záéíóúñ\s]{3,40})',
        # "Ley Federal del Trabajo" sin artículo específico
        r'(Ley\s+(?:Federal|General|Org[áa]nica)\s+(?:del?\s+)?[A-Za-záéíóúñ\s]{5,50})',
    ]
    
    for r in results:
        text = r.texto[:2000] if r.texto else ""
        ref_str = r.ref or ""
        combined = f"{text} {ref_str}"
        
        for pattern in patterns[:2]:  # Solo los que tienen artículo + ley
            matches = re.findall(pattern, combined)
            for match in matches:
                if isinstance(match, tuple) and len(match) == 2:
                    art_num, ley_name = match
                    ley_clean = ley_name.strip()
                    key = f"{art_num}_{ley_clean[:20]}"
                    if key not in seen and len(refs) < max_refs:
                        refs.append(f"artículo {art_num} {ley_clean}")
                        seen.add(key)
    
    return refs


async def _cross_silo_enrichment(
    initial_results: List[SearchResult],
    query: str,
) -> List[SearchResult]:
    """
    Segunda pasada: busca jurisprudencia y constitución que fundamenten
    los artículos/leyes encontrados en la primera pasada.
    
    Lógica:
    1. Extraer refs legales (ley + artículo) de resultados iniciales
    2. Buscar en jurisprudencia_nacional tesis que citen esas leyes/artículos
    3. Buscar en bloque_constitucional artículos constitucionales relevantes
    4. Retornar resultados nuevos (sin duplicados)
    """
    refs = _extract_legal_refs(initial_results)

    enrichment_results = []
    existing_ids = {r.id for r in initial_results}
    enrichment_tasks = []

    # La Constitución se consulta SIEMPRE y con la pregunta del abogado, no
    # con una consulta derivada de las referencias ya halladas.
    #
    # Antes sólo se buscaba a partir de esas referencias, así que una pregunta
    # sobre un principio constitucional —«interés superior de la niñez»— no
    # disparaba ninguna búsqueda constitucional si la primera pasada no había
    # traído ya un artículo. Y si no había referencias, la función se salía
    # aquí mismo sin buscar nada. Por eso una consulta de derecho familiar
    # terminaba diciendo «el contexto no recupera el texto literal del
    # Artículo 4o»: nunca se preguntó por él.
    enrichment_tasks.append(_buscar_en_la_constitucion(query, top_k=4))

    if refs:
        print(f"   🔗 Cross-silo refs extraídas: {refs}")
    
        for ref in refs[:3]:
            # Buscar jurisprudencia que cite este artículo/ley
            juris_query = f"tesis jurisprudencia criterio judicial {ref}"
            enrichment_tasks.append(
                _do_enrichment_search(FIXED_SILOS["jurisprudencia"], juris_query)
            )

            # El bloque convencional (CoIDH, tratados) por su cuenta: aporta,
            # pero ya no le quita el sitio a la Constitución.
            const_query = f"constitución derecho fundamental garantía {ref}"
            enrichment_tasks.append(
                _do_enrichment_search("bloque_constitucional", const_query)
            )
    
    # Ejecutar todas las búsquedas en paralelo
    all_enriched = await asyncio.gather(*enrichment_tasks)
    
    for results in all_enriched:
        for r in results:
            if r.id not in existing_ids:
                enrichment_results.append(r)
                existing_ids.add(r.id)
    
    # Ordenar por score
    enrichment_results.sort(key=lambda x: x.score, reverse=True)
    return enrichment_results[:8]  # Max 8 resultados de enrichment


async def _do_enrichment_search(
    collection: str,
    query: str,
    filtro=None,
    top_k: int = 4,
) -> List[SearchResult]:
    """Ejecuta una búsqueda ligera para enrichment."""
    try:
        dense_vector = await get_dense_embedding(query)
        sparse_vector = get_sparse_embedding(query)
        results = await hybrid_search_single_silo(
            collection=collection,
            query=query,
            dense_vector=dense_vector,
            sparse_vector=sparse_vector,
            filter_=filtro,
            top_k=top_k,
            alpha=0.7,
        )
        return results
    except Exception as e:
        print(f"      ⚠️ Enrichment search falló en {collection}: {err(e)}")
        return []


async def _buscar_en_la_constitucion(consulta: str, top_k: int = 4) -> List[SearchResult]:
    """La Constitución compitiendo CONTRA SÍ MISMA, no contra el silo entero.

    EL PROBLEMA, MEDIDO (7-ago-2026)
    `bloque_constitucional` tiene 6,823 fragmentos y la CPEUM son 355: el 5 %.
    El otro 95 % son cuadernillos de la CoIDH (76 %), convenciones (13 %) y
    sentencias interamericanas (4 %).

    Y los párrafos de la CoIDH ganan siempre, porque están escritos SOBRE el
    concepto: para «interés superior de la niñez» puntúan 0.59-0.66 y el
    artículo 4º constitucional 0.39. Resultado: la norma suprema del orden
    jurídico mexicano no entraba nunca al contexto, y la respuesta salía
    diciendo «el contexto no recupera el texto literal del Artículo 4o».

    Con el filtro por tipo, ese mismo artículo 4º sale PRIMERO. No es un
    reordenamiento: es dejar de comparar una norma con sus comentaristas.
    """
    from qdrant_client.models import Filter, FieldCondition, MatchValue
    return await _do_enrichment_search(
        "bloque_constitucional",
        consulta,
        filtro=Filter(must=[FieldCondition(key="tipo", match=MatchValue(value="constitucion"))]),
        top_k=top_k,
    )


def _parse_article_number(text: str) -> Optional[int]:
    """Extrae el número de artículo de un campo `ref` o de un texto.

    OJO (7-ago-2026): el patrón anterior decía reconocer «Art. 123» pero NO
    podía: exigía `art` seguido de `[íi]culo`, así que la abreviatura nunca
    casaba. Como las colecciones estatales escriben «Art. 923» —y las
    federales «Artículo 923.»—, los artículos vecinos llevaban muertos para
    TODO el corpus estatal, en silencio y devolviendo cero. Lo delató el
    recuento diagnóstico: «5 leyes candidatas, 0 con nombre».

    Ahora «ículo» es opcional y «Sección 283» sigue sin casar, que es lo
    correcto: una sección no es un artículo.
    """
    import re
    # «Artículo 19» · «Art. 123» · «ARTÍCULO 45» · «Artículos 52 y 53»
    match = re.search(r'\bart(?:[íi]culos?|s)?\.?\s*(\d+)', text or "", re.I)
    if match:
        return int(match.group(1))
    return None


async def _fetch_neighbor_chunks(
    results: List[SearchResult],
    max_neighbors: int = 6,
    estado: Optional[str] = None,
) -> List[SearchResult]:
    """
    Neighbor Chunk Retrieval: para resultados de legislación con score alto,
    busca los artículos adyacentes (N-1, N+1) de la misma ley.
    
    Esto da al LLM contexto circundante: definiciones, excepciones y sanciones
    que suelen estar en artículos contiguos.
    
    SEGURIDAD: Solo busca vecinos en el silo del estado seleccionado + federales.
    Nunca contamina con leyes de otros estados.
    """
    # Determinar silos válidos para neighbor chunks
    valid_silos = {"leyes_federales", "leyes_estatales"}  # Legacy + federal siempre
    if estado:
        normalized_est = normalize_estado(estado)
        target_silo = ESTADO_SILO.get(normalized_est) if normalized_est else None
        if target_silo:
            valid_silos.add(target_silo)  # Incluir silo dedicado del estado seleccionado
    
    # Solo tomar top 5 de legislación con score alto del estado seleccionado
    legislation = [r for r in results 
                   if r.silo in valid_silos
                   and r.score > 0.3][:5]  # Threshold reducido: 0.4 → 0.3 para más cobertura
    
    if not legislation:
        return []
    
    # ── SUSTITUIDO (7-ago-2026): del barrido de 50 puntos al número exacto ──
    #
    # Antes, para hallar el artículo N-1 se traían CINCUENTA puntos filtrados
    # sólo por `origen` y se buscaba el vecino entre ellos en Python. Dos veces
    # por artículo y hasta cinco artículos: quinientos puntos leídos de Qdrant
    # por consulta para quedarse con seis. Y si el vecino no caía entre esos
    # cincuenta —que es lo normal en un código de mil artículos— no aparecía.
    #
    # Con `articulo_num` indexado en las 34 colecciones, los dos vecinos se
    # piden por igualdad exacta y todos los de una misma ley en UNA consulta.
    # Menos trabajo para Qdrant y un resultado que sí es el vecino.
    neighbors = []
    existing_ids = {r.id for r in results}

    # (colección, origen) → números vecinos buscados
    por_ley: dict = {}
    for r in legislation:
        art_num = _parse_article_number(r.ref or r.texto)
        if not art_num or not r.origen:
            continue
        clave = (r.silo, r.origen)
        for vecino in (art_num - 1, art_num + 1):
            if vecino < 1:
                continue
            por_ley.setdefault(clave, [])
            if vecino not in por_ley[clave]:
                por_ley[clave].append(vecino)

    async def _vecinos_de(coleccion: str, origen: str, numeros: list):
        # Misma cautela que el salto interno: la clave del nombre de la ley
        # cambia según cómo se ingirió cada colección.
        return coleccion, await _buscar_por_ley(
            qdrant_client, coleccion, origen, numeros,
            Filter, FieldCondition, MatchValue, MatchAny)

    _respuestas = await asyncio.gather(
        *[_vecinos_de(c, o, nums[:6]) for (c, o), nums in list(por_ley.items())[:4]],
        return_exceptions=True)

    for _r in _respuestas:
        if isinstance(_r, BaseException) or _r is None:
            continue
        coleccion, hallado = _r
        if not hallado or not hallado[0]:
            continue
        for point in hallado[0]:
            point_id = str(point.id)
            if point_id in existing_ids:
                continue
            payload = point.payload or {}
            neighbors.append(SearchResult(
                id=point_id,
                score=0.15,  # Score bajo: contexto, no resultado principal
                texto=payload.get("texto", payload.get("text", "")),
                # Sin `ref` la interfaz rotula la cita como «Disposición legal»
                # y no la reconoce como tesis. El rubro es lo que la identifica.
                ref=payload.get("ref") or payload.get("rubro") or tesis_num or (
                    f"Registro {registro}" if registro else None),
                origen=payload.get("origen") or payload.get("ley"),
                jurisdiccion=payload.get("jurisdiccion"),
                entidad=payload.get("entidad"),
                silo=coleccion,
                pdf_url=payload.get("pdf_url") or payload.get("url_pdf"),
            ))
            existing_ids.add(point_id)

    # El recuento dice POR QUÉ cuando sale cero: sin nombre de ley no hay a qué
    # ley pedirle el vecino, y ese era el caso que quedaba mudo.
    _sin_ley = sum(1 for r in legislation if not r.origen)
    print(f"   📄 Neighbor chunks: {len(neighbors)} artículos adyacentes "
          f"(de {len(legislation)} leyes candidatas, {len(por_ley)} con nombre; "
          f"{_sin_ley} sin nombre de ley)")
    return neighbors[:max_neighbors]


# ══════════════════════════════════════════════════════════════════════════════
# LAW-LEVEL ROUTING: Identifica leyes temáticamente faltantes y las inyecta
# ══════════════════════════════════════════════════════════════════════════════

async def _law_level_routing(
    query: str,
    merged: List[SearchResult],
    estado: Optional[str],
) -> List[SearchResult]:
    """
    Law-Level Routing: Usa el LLM para identificar leyes que DEBERÍAN estar
    en el contexto pero no fueron recuperadas por semantic search.
    
    Ejemplo: Para "multas de tránsito en Monterrey", identifica que la
    "Ley de Tránsito" debería estar, y si no lo está, busca chunks de esa ley.
    
    SEGURIDAD: Solo busca en el silo del estado seleccionado.
    """
    if not estado:
        return []  # Solo aplica cuando hay estado seleccionado
    
    normalized_est = normalize_estado(estado)
    if not normalized_est:
        return []
    
    target_silo = ESTADO_SILO.get(normalized_est)
    if not target_silo:
        return []

    # Verificar qué leyes ya están en el contexto
    existing_laws = set()
    for r in merged:
        if r.silo == target_silo and r.origen:
            existing_laws.add(r.origen)
    
    estado_display = estado.replace("_", " ").title()
    
    try:
        # Pedir al LLM que identifique leyes faltantes
        response = await chat_client.chat.completions.create(
            model=HYDE_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        f"Eres un experto en el ordenamiento jurídico del Estado de {estado_display}, México. "
                        f"Dada una consulta legal, identifica las 3-5 leyes ESTATALES de {estado_display} "
                        "que son MÁS RELEVANTES para resolver el caso. "
                        "Responde SOLO con los nombres de las leyes, uno por línea, sin numeración ni explicación. "
                        f"Usa los nombres oficiales (ej: 'Ley de Tránsito y Seguridad Vial para el Estado de {estado_display}')."
                    )
                },
                {"role": "user", "content": query}
            ],
            max_completion_tokens=200,
            temperature=1,
            **AYUDANTES_KW,
        )
        suggested_laws = response.choices[0].message.content.strip().split("\n")
        suggested_laws = [l.strip().strip("-•").strip() for l in suggested_laws if l.strip()]
        print(f"   📖 Law-Level Routing: LLM sugiere {len(suggested_laws)} leyes: {suggested_laws}")
        
        # Filtrar las que ya están en el contexto
        missing_laws = []
        for suggested in suggested_laws:
            suggested_lower = suggested.lower()
            already_found = False
            for existing in existing_laws:
                if existing and (
                    suggested_lower in existing.lower() or 
                    existing.lower() in suggested_lower or
                    # Match parcial: "Ley de Tránsito" ⊂ "Ley de Tránsito y Seguridad Vial para el Estado de..."
                    any(word in existing.lower() for word in suggested_lower.split() if len(word) > 4)
                ):
                    already_found = True
                    break
            if not already_found:
                missing_laws.append(suggested)
        
        if not missing_laws:
            print(f"   📖 Law-Level Routing: Todas las leyes sugeridas ya están en contexto ✅")
            return []
        
        print(f"   📖 Law-Level Routing: {len(missing_laws)} leyes FALTANTES: {missing_laws}")
        
        # Buscar chunks de las leyes faltantes en el silo del estado
        existing_ids = {r.id for r in merged}
        new_results = []
        
        for law_name in missing_laws[:3]:  # Max 3 leyes faltantes
            try:
                # Construir query específica para buscar artículos de esa ley
                law_query = f"{law_name}: {query}"
                law_dense = await get_dense_embedding(law_query)
                law_sparse = get_sparse_embedding(law_query)
                
                law_results = await hybrid_search_single_silo(
                    collection=target_silo,
                    query=law_query,
                    dense_vector=law_dense,
                    sparse_vector=law_sparse,
                    filter_=None,
                    top_k=5,
                    alpha=0.7,
                )
                
                for r in law_results:
                    if r.id not in existing_ids:
                        new_results.append(r)
                        existing_ids.add(r.id)
                        
            except Exception as e:
                print(f"      ⚠️ Law routing search falló para '{law_name}': {err(e)}")
                continue
        
        return new_results
        
    except Exception as e:
        print(f"   ⚠️ Law-Level Routing falló: {err(e)}")
        return []


# ══════════════════════════════════════════════════════════════════════════════
# ADVANCED RAG: HyDE (Hypothetical Document Embeddings)
# ══════════════════════════════════════════════════════════════════════════════

# ── SALUD DE LA RECUPERACIÓN ────────────────────────────────────────────────
# HyDE estuvo meses apagado y NADA avisó: cero documentos generados, ochenta y
# ocho tiempos agotados en diez horas, y la respuesta seguía saliendo —peor,
# pero saliendo—. Se descubrió porque un abogado notó que faltaba lo obvio.
#
# Una capa que puede apagarse sin romper nada hay que MEDIRLA encendida. Esto
# lleva la cuenta y `/salud/recuperacion` la publica para que la alarma diaria
# la lea. Es memoria del proceso, no base de datos: si Render corre varios
# obreros, cada uno ve lo suyo — suficiente, porque una caída de HyDE los
# afecta a todos por igual.
from collections import deque as _deque

_SALUD_VENTANA = 200          # últimos N intentos
_HYDE_INTENTOS: "_deque[tuple]" = _deque(maxlen=_SALUD_VENTANA)
_CONCEPTO_PASADAS: "_deque[tuple]" = _deque(maxlen=_SALUD_VENTANA)


def _anotar_hyde(resultado: str, ms: int = 0) -> None:
    """resultado: 'generado' | 'plazo_agotado' | 'error'"""
    try:
        _HYDE_INTENTOS.append((time.time(), resultado, ms))
    except Exception:
        pass


def _anotar_concepto(ancla_usada: str, nuevos: int) -> None:
    try:
        _CONCEPTO_PASADAS.append((time.time(), ancla_usada, nuevos))
    except Exception:
        pass


async def _generate_hyde_document(query: str, estado: Optional[str] = None) -> Optional[str]:
    """
    HyDE: Genera un documento jurídico hipotético que respondería a la query.
    Este documento hipotético se usa para generar el dense embedding,
    mejorando la recuperación para queries coloquiales.
    
    Si hay un estado seleccionado, el HyDE doc incluirá referencias a la legislación
    de ese estado para mejorar la afinidad semántica con el silo correcto.
    
    Ejemplo:
      Query: "me corrieron del trabajo sin razón"
      HyDE genera: "Artículo 47.- Son causas de rescisión de la relación de trabajo..."
      El embedding del HyDE doc es más cercano a los artículos reales.
    """
    if not HYDE_ENABLED:
        return None
    
    # No usar HyDE para queries que ya son técnicas o mencionan artículos
    if re.search(r'artículo\s+\d+', query, re.IGNORECASE):
        return None
    if len(query.split()) < 3:
        return None
    
    # Construir prompt state-aware
    estado_context = ""
    if estado:
        estado_display = estado.replace("_", " ").title()
        estado_context = (
            f" La consulta es específicamente sobre el Estado de {estado_display}. "
            f"Genera el fragmento como si fuera un artículo de una ley ESTATAL de {estado_display} "
            f"(ej: 'Ley de Tránsito para el Estado de {estado_display}', "
            f"'Código Civil para el Estado de {estado_display}', etc.). "
            f"Incluye el nombre de la ley estatal en el fragmento."
        )
    
    try:
        from google.genai import types as _gtypes
        _gemini = get_gemini_client()
        _hyde_system = (
            "Eres un experto en derecho mexicano. Genera un fragmento breve (150-250 palabras) "
            "de un artículo de ley o tesis de jurisprudencia mexicana que respondería "
            "directamente a la consulta del usuario. Escribe SOLO el texto legal, "
            "sin explicaciones ni preámbulos. Usa terminología jurídica técnica mexicana."
            + estado_context
        )
        _t_hyde = time.perf_counter()
        _hyde_resp = await asyncio.wait_for(
            _gemini.aio.models.generate_content(
                model=GEMINI_LITE_MODEL,
                contents=query,
                config=_gtypes.GenerateContentConfig(
                    system_instruction=_hyde_system,
                    temperature=0.3,
                    max_output_tokens=350,
                ),
            ),
            # Medido en producción el 22-ago-2026 sobre diez horas de tráfico:
            # «HyDE generado» 0 veces, «HyDE timeout» 88 veces. CIEN POR CIENTO
            # de fallos. El plazo de 1.5 s no lo alcanzaba nunca, así que la capa
            # entera llevaba meses muerta sin que nada lo dijera.
            #
            # Subirlo no cuesta latencia: HyDE se genera EN PARALELO con la
            # búsqueda, que tarda de cuatro a seis segundos. Ajustable sin
            # desplegar por si el proveedor se degrada.
            timeout=float(os.getenv('HYDE_PLAZO_SEG', '4.0')),
        )
        hyde_doc = (_hyde_resp.text or "").strip()
        if hyde_doc and len(hyde_doc) > 50:
            _anotar_hyde("generado", int((time.perf_counter() - _t_hyde) * 1000))
            print(f"   🔮 HyDE generado ({len(hyde_doc)} chars): {hyde_doc[:100]}...")
            return hyde_doc
        _anotar_hyde("error", int((time.perf_counter() - _t_hyde) * 1000))
    except asyncio.TimeoutError:
        _anotar_hyde("plazo_agotado", int((time.perf_counter() - locals().get('_t_hyde', time.perf_counter())) * 1000))
        print(f"   ⚠️ HyDE: se agotó el plazo de {os.getenv('HYDE_PLAZO_SEG', '4.0')}s "
              f"— se usa el concepto limpio")
    except Exception as e:
        _anotar_hyde("error", int((time.perf_counter() - locals().get('_t_hyde', time.perf_counter())) * 1000))
        print(f"   ⚠️ HyDE falló (usando query original): {err(e)}")

    return None


