class VozRequest(BaseModel):
    pregunta: str
    #: Estado del usuario, para saber qué colección estatal mirar.
    estado: Optional[str] = None
    #: Los últimos turnos. Se recortan: una conversación hablada es corta y
    #: arrastrar más historia sólo suma tokens de entrada en CADA turno — que es
    #: exactamente cómo un platinum anual llegó a topar el millón en el chat.
    historial: List[Message] = Field(default_factory=list)
    stream: bool = True


# ¿Esta pregunta necesita internet? El acervo tiene leyes y tesis; NO tiene
# opinión, doctrina, ni lo publicado la semana pasada. Preguntar por lo que
# dijo un jurista en un artículo no se responde con un código.
#
# Se detecta en vez de buscar siempre porque la web cuesta 3,2 s medidos —el
# presupuesto entero de un turno— y la mayoría de las preguntas no la necesita.
# El abogado que pregunta un plazo en audiencia no quiere doctrina.
_VOZ_PIDE_WEB = _re_mod.compile(
    r"\b(?:qu[ée]\s+(?:dijo|opina|opin[óo]|piensa|escribi[óo]|public[óo]|declar[óo]|sostiene))\b"
    r"|\b(?:art[íi]culo|ensayo|columna|entrevista|conferencia|ponencia|libro)\s+(?:de|del|publicad)"
    r"|\b(?:doctrina|doctrinal|acad[ée]mic\w+|jurista|autor|profesor)\b"
    r"|\b(?:not[ii]cia|reciente|[úu]ltim\w+\s+(?:reforma|semana|mes)|hoy|ayer|este a[ñn]o|202[4-9])\b",
    _re_mod.I)

_VOZ_MISION_WEB = (
    "Localiza lo que juristas y académicos hayan PUBLICADO sobre el tema: artículos de "
    "opinión, revistas jurídicas, blogs académicos y universitarios. Prioriza "
    "juridicas.unam.mx, revistas universitarias y publicaciones del propio autor. Da el "
    "título del texto, dónde se publicó y su fecha. Si citas a un autor, sé literal con lo "
    "que dijo. Responde en español de México y en tres frases como máximo."
)


def _dominio_legible(url: str) -> str:
    """El sitio, sin protocolo ni «www». En pantalla, «juridicas.unam.mx» dice
    más que una dirección de ochenta caracteres."""
    try:
        d = _re_mod.sub(r"^https?://(www\.)?", "", url or "").split("/")[0]
        return d or "internet"
    except Exception:
        return "internet"


async def _voz_web(pregunta: str) -> dict:
    """Busca doctrina y opinión en internet. Nunca lanza: si falla, se sigue.

    Los tres agentes que ya existen en `busqueda_web` miran SÓLO fuentes
    oficiales —DOF, SCJN, congresos estatales— y ninguno habría encontrado el
    artículo de Ferrajoli que preguntó David. Ésta es la misión que faltaba.
    """
    try:
        import httpx
        clave = os.getenv("OPENROUTER_API_KEY")
        if not clave:
            return {}
        async with httpx.AsyncClient(timeout=12.0) as cli:
            r = await cli.post(
                "https://openrouter.ai/api/v1/chat/completions",
                headers={"Authorization": f"Bearer {clave}"},
                json={"model": os.getenv("VOZ_MODELO_WEB", "perplexity/sonar"),
                      "max_tokens": 420, "temperature": 0.2,
                      "messages": [{"role": "system", "content": _VOZ_MISION_WEB},
                                   {"role": "user", "content": pregunta}]},
            )
            if r.status_code != 200:
                print(f"   🌐 VOZ web {r.status_code}"); return {}
            d = r.json()
        msg = (d.get("choices") or [{}])[0].get("message", {})
        urls = []
        for c in (d.get("citations") or msg.get("annotations") or []):
            if isinstance(c, str):
                urls.append(c)
            elif isinstance(c, dict):
                u = c.get("url") or (c.get("url_citation") or {}).get("url")
                if u:
                    urls.append(u)
        return {"texto": (msg.get("content") or "").strip(), "urls": urls[:5]}
    except Exception as e:
        print(f"   🌐 VOZ web falló (no fatal): {err(e)}")
        return {}


# Cuántos candidatos se piden por silo y por ancla. Eran CUATRO, y con cuatro
# se perdía lo que David reportó: preguntando por la tesis que exenta del pago
# de copias certificadas, la 2025216 —cuyo rubro dice literalmente «DERECHOS
# POR LA CERTIFICACIÓN DE COPIAS. SU PAGO NO ES OBLIGATORIO…»— quedaba fuera
# del corte y el agente contestaba con el arancel del estado. Medido el
# 24-ago-2026: con red de 12 entra en el cuarto puesto; con red de 4 no entra.
# El coste es de milisegundos —Qdrant devuelve 12 casi por lo mismo que 4—.
_VOZ_POR_SILO = 12

# La fusión es POR RANGO (RRF), no por score, y esto sí es un arreglo de fondo.
# Antes se ordenaban juntos los resultados de dos búsquedas distintas usando su
# coseno: números que NO son comparables entre sí, porque cada uno mide contra
# un vector distinto. El resultado era una lista que parecía ordenada y no lo
# estaba.
_VOZ_K_RRF = 12

# Y el concepto pesa más que la pregunta. No es un capricho: buscando con la
# pregunta entera —«qué artículos regulan el derecho del tanto en Querétaro»—
# el silo estatal devuelve la Ley del Deporte y el Código Penal; buscando el
# concepto limpio —«derecho del tanto»— devuelve, en los cinco primeros
# puestos, los artículos 2606, 964, 1186, 995 y 965 del Código Civil del
# Estado. El andamio de la pregunta envenena el vector; es el mismo mal que
# tuvo el chat con HyDE apagado.
_VOZ_PESO_CONCEPTO = 1.6

# ¿La pregunta va de criterios? Decide dos cosas: cuánto sitio se le da a la
# jurisprudencia y si se paga el reordenador.
_VOZ_ES_CRITERIO = _re_mod.compile(
    r"tesis|jurisprudenc|criterio|precedent|contradicci[óo]n|registro\s+\d{6}|"
    r"\bscjn\b|corte|colegiado|sala\b", _re_mod.I)


def _voz_registro_de(pl: dict, *cadenas: str) -> str:
    """El número de registro, lo lleve donde lo lleve.

    El acervo tiene TRECE formas de payload y el registro aparece en su propio
    campo, dentro del `ref` («2a./J. 173/2009 | Registro 165908») o delante del
    nombre del fichero («2025216_XXII.3o.A.C.1 A (11a.).txt»). La versión
    anterior sólo miraba el `ref`, y por eso con la tesis de las copias
    certificadas el agente dijo «no tengo su número de registro a la vista»
    teniéndolo en el nombre del fichero. Sin registro tampoco hay enlace al
    Semanario, así que el fallo se pagaba dos veces.
    """
    directo = pl.get("registro")
    if directo and str(directo).strip().isdigit():
        return str(directo).strip()
    for cad in cadenas:
        if not cad:
            continue
        m = _re_mod.search(r"[Rr]egistro\s*[:\s]\s*(\d{6,7})", cad)
        if m:
            return m.group(1)
        m = _re_mod.match(r"\s*(\d{6,7})[_\s]", cad)
        if m:
            return m.group(1)
    return ""


def _voz_documento(col: str, punto) -> Optional[dict]:
    """Convierte un punto de Qdrant en lo que el agente necesita para hablar.

    LO QUE SE DICE DE UNA TESIS ES EL RUBRO, NO LA CLAVE. David lo dijo tras
    oírlo: «cuando cita las tesis no se entiende nada por los números romanos».
    Tiene razón y es un problema de diseño, no de estilo: «XXII.3o.A.C.1 A
    (11a.)» leído por un sintetizador es una ristra de letras sueltas, mientras
    que el rubro —«DERECHOS POR LA CERTIFICACIÓN DE COPIAS. SU PAGO NO ES
    OBLIGATORIO…»— dice en una frase QUÉ resolvió el criterio, y el registro es
    lo único que se teclea en el Semanario para comprobarlo.

    Antes el rubro sólo se usaba si `ley` venía vacío; como `ley` cae de vuelta
    en `origen` —el nombre del fichero—, nunca estaba vacío y el rubro no se
    usaba jamás. De ahí que el modelo leyera la clave: era lo único legible que
    tenía delante.
    """
    def _txt(v) -> str:
        return "" if v is None else str(v).strip()

    pl = punto.payload or {}
    texto = _txt(pl.get("texto_raw") or pl.get("texto") or pl.get("text")
                 or pl.get("chunk_text") or pl.get("holding"))
    if not texto:
        return None                     # un documento sin texto no sostiene nada

    ref = _txt(pl.get("ref"))
    origen = _txt(pl.get("origen"))
    ley = _txt(pl.get("ley")) or origen
    rubro = _txt(pl.get("rubro"))
    registro = _voz_registro_de(pl, ref, origen, ley, texto[:200])
    clave = _txt(pl.get("numero_tesis") or pl.get("tesis") or pl.get("tesis_num"))
    if not clave and registro:
        # «2025216_XXII.3o.A.C.1 A (11a.).txt» — la clave va detrás del registro.
        m = _re_mod.match(r"\s*\d{6,7}_(.+?)\.txt\s*$", origen or ley or "")
        if m:
            clave = m.group(1).strip()
    es_tesis = bool(registro) or col.startswith("jurisprudencia")

    # El rótulo que verá el abogado en pantalla y que oirá por el altavoz.
    if es_tesis:
        etiqueta = rubro[:160] or (f"Tesis {clave}" if clave else "Tesis del Semanario Judicial")
        # El nombre del fichero NO es un rótulo. Si es lo único que hay, mejor
        # decir qué es que leer «165908_2a.J. 1732009.txt».
        if _txt(ley).endswith(".txt") or _re_mod.match(r"^\d{6,7}_", _txt(ley)):
            ley = etiqueta
        referencia = (f"{clave} · Registro {registro}" if clave and registro
                      else (f"Registro {registro}" if registro else clave or ref))
    else:
        # Una tarjeta sin rótulo es una tarjeta que no dice nada: se vieron dos
        # en blanco en la prueba. Si no hay ley ni origen, al menos que diga de
        # qué acervo salió.
        etiqueta = ley or {
            FIXED_SILOS["jurisprudencia"]: "Jurisprudencia del Semanario Judicial",
            FIXED_SILOS["constitucional"]: "Bloque constitucional",
            "doctrina": "Doctrina",
        }.get(col, "Acervo de Iurexia")
        referencia = ref

    enlace = _txt(pl.get("url_pdf") or pl.get("pdf"))
    if not enlace and registro:
        enlace = f"https://sjf2.scjn.gob.mx/detalle/tesis/{registro}"

    return {
        "coleccion": col,
        "score": float(punto.score or 0),
        "ley": etiqueta,
        "ref": referencia,
        "articulo": _txt(pl.get("articulo_num")),
        # 900 caracteres dejaban la tesis a medias justo donde dice lo que
        # resuelve. Con 1.400 cabe el rubro y el arranque del texto, y diez
        # documentos siguen siendo un contexto pequeño. Ahora 1.900, porque los
        # artículos largos —el 964 de Querétaro, con su aviso, su plazo y su
        # sanción— también se cortaban, y de un artículo cortado sale una
        # respuesta incompleta que además suena segura.
        "texto": texto[:1900],
        "pdf": enlace,
        "registro": registro,
        "rubro": rubro,
        "clave": clave,
        "es_tesis": es_tesis,
        "entidad": _txt(pl.get("entidad")),
    }


def _voz_llave(d: dict) -> str:
    """Dos trozos del mismo artículo son un solo documento.

    El Código Civil de Nuevo León está partido en trozos que arrastran todos el
    mismo `ref` («Art. 337»): en la prueba de David, CINCO de los diez huecos
    del contexto eran el mismo artículo cinco veces, y con ellos dentro no
    cabía el artículo que sí contestaba.
    """
    if d["registro"]:
        return f"reg:{d['registro']}"
    # El número de artículo sólo vale como llave si el texto EMPIEZA por él.
    # En el Código Civil de Nuevo León cinco trozos distintos vienen todos
    # etiquetados «Art. 337» —el corte de la ingesta arrastró la etiqueta— y
    # con la llave a ciegas se fundían en uno solo, tirando cuatro trozos de
    # arrendamiento que sí hacían falta.
    if d["articulo"] and _re_mod.match(
            rf"\s*(?:art[íi]culo|art[sº°]?\.)\s*{_re_mod.escape(d['articulo'])}\b",
            d["texto"], _re_mod.I):
        return f"{d['coleccion']}|{d['ley']}|art:{d['articulo']}"
    return f"{d['coleccion']}|{d['ley']}|{d['ref']}|{d['texto'][:80]}"


async def _voz_reordenar(consulta: str, docs: List[dict], top_n: int) -> List[dict]:
    """El cross-encoder de Cohere, y SÓLO para preguntas de criterio.

    Medido sobre el mismo banco (24-ago-2026): en «qué dice la jurisprudencia
    sobre la suplencia de la queja» el reordenador sube de UNA tesis pertinente
    a CINCO. Pero en «qué artículos regulan el derecho del tanto» hace lo
    contrario: inunda de tesis los diez huecos y deja fuera los artículos del
    código, porque el rubro de una tesis repite el concepto más veces que el
    texto del artículo. Por eso se paga sólo donde gana, no siempre —son 400 ms
    y en audiencia se notan.

    Se reordena por el CONCEPTO, no por la pregunta, por el mismo motivo por el
    que se busca así.
    """
    if not COHERE_RERANK_ENABLED or not docs or _http_pool is None:
        return docs[:top_n]
    try:
        cuerpos = [f"[{d['ley']} {d['ref']}] {d['rubro']} {d['texto']}"[:1500] for d in docs]
        async with COHERE_SEM:
            r = await _http_pool.post(
                "https://api.cohere.com/v2/rerank",
                headers={"Authorization": f"Bearer {COHERE_API_KEY}"},
                json={"model": COHERE_RERANK_MODEL, "query": consulta,
                      "documents": cuerpos, "top_n": min(top_n, len(cuerpos))},
                timeout=6.0,
            )
        if r.status_code != 200:
            print(f"   ⚠️ VOZ: reordenador HTTP {r.status_code} — se sigue con el orden propio")
            return docs[:top_n]
        return [docs[i["index"]] for i in r.json().get("results", []) if i["index"] < len(docs)]
    except Exception as e:
        # Nunca tumba un turno: si el reordenador falla, el orden de la fusión
        # ya es utilizable.
        print(f"   ⚠️ VOZ: reordenador falló (no fatal): {err(e)}")
        return docs[:top_n]


def _voz_sin_tildes(t: str) -> str:
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFD", (t or "").lower())
                   if unicodedata.category(c) != "Mn")


def _voz_empujon(concepto: str, d: dict) -> float:
    """Cuánto vale que el documento DIGA lo que se preguntó.

    La fusión por rango tiene un punto ciego: un documento que es el primero de
    un silo pequeño e irrelevante puntúa igual que el primero del silo que sí
    contesta. Preguntando «qué artículos regulan el derecho del tanto en
    Querétaro» se colaban dos Cuadernillos de la Corte Interamericana y el
    artículo 17 del Código Civil Federal, y se quedaban fuera los artículos
    964, 965 y 995 del Código Civil del Estado —que empiezan literalmente por
    «derecho del tanto»—.

    El desempate es lo más tonto y lo más fiable: si el texto del documento
    contiene la frase del concepto, sube; si contiene todas sus palabras con
    peso, sube menos. No hace falta un modelo para esto.
    """
    if not concepto:
        return 1.0
    frase = _voz_sin_tildes(concepto)
    cuerpo = _voz_sin_tildes(f"{d.get('rubro','')} {d.get('ley','')} {d.get('texto','')}")
    if frase and frase in cuerpo:
        return 1.6
    palabras = [p for p in _re_mod.findall(r"\w{4,}", frase)]
    if palabras and all(p in cuerpo for p in palabras):
        return 1.25
    return 1.0


def _voz_estado_del_perfil(user_id: str) -> Optional[str]:
    """La entidad del abogado, cuando la app no la manda.

    EL FALLO QUE EXPLICA LA QUEJA DE FONDO. La pantalla del Agente IA leía el
    estado de `user` —el objeto de sesión de Supabase, que no tiene ese
    campo— en vez de `profile`, que es donde vive. Resultado: TODAS las
    preguntas llegaban con `estado: null`, el silo del estado no se buscaba
    nunca, y a «qué artículos regulan el derecho del tanto en Querétaro» el
    agente contestaba con el Código Civil Federal y criterios de Michoacán.
    Eso es exactamente lo que David reportó: «no aporta lo que es el derecho
    del tanto como sí lo hace la consulta normal de Iurexia» —la web sí manda
    el estado—.

    Se arregla en la app en una línea, pero se arregla TAMBIÉN aquí: hay
    versiones instaladas y en TestFlight que seguirán mandando null durante
    semanas, y el servidor sabe perfectamente en qué estado ejerce quien
    pregunta. Cuesta una consulta a Supabase y sólo cuando falta el dato.
    """
    if not user_id or not supabase_admin:
        return None
    try:
        r = supabase_admin.table("user_profiles").select("estado") \
            .eq("id", user_id).limit(1).execute()
        if r.data and r.data[0].get("estado"):
            return str(r.data[0]["estado"])
    except Exception as e:
        print(f"   ⚠️ VOZ: no pude leer el estado del perfil: {err(e)}")
    return None


# ── El hilo de la conversación ───────────────────────────────────────────────
#
# David: «no quiero que el agente pierda el contexto de la pregunta anterior,
# sino que conecte con lo que estamos hablando».
#
# El historial YA se le pasaba al modelo, así que redactaba enlazando. Lo que
# NO enlazaba era la BÚSQUEDA: `_voz_buscar` sólo veía la pregunta nueva. Y ahí
# es donde se rompía la conversación de verdad — preguntar «¿y en materia
# laboral?» después de hablar de la suplencia de la queja buscaba literalmente
# «y en materia laboral», que no recupera nada, y el agente contestaba «no lo
# tengo en mi acervo» sobre un tema del que acababa de hablar.
#
# La regla: si la pregunta NO SE SOSTIENE SOLA, se le pega el tema del turno
# anterior antes de buscar. Y se detecta sin llamar a ningún modelo —eso serían
# dos segundos— con dos señales que bastan:
#
#   · es corta (menos de siete palabras), o
#   · empieza por una conjunción o trae un demostrativo sin sustantivo:
#     «¿y si…?», «¿eso aplica…?», «ahí qué pasa», «entonces…».
#
# Lo que NO se hace: arrastrar el tema cuando la pregunta se sostiene sola. Si
# el abogado cambia de asunto, cambia de asunto; pegarle el tema anterior
# envenenaría la búsqueda igual que la envenenaba el andamio de la pregunta.

_VOZ_SIGUE_EL_HILO = _re_mod.compile(
    r"^\s*(?:y|e|o|pero|entonces|además|ademas|también|tambien)\b"
    r"|^\s*¿?\s*(?:eso|ese|esa|esos|esas|ahí|ahi|allí|alli|lo mismo|igual)\b"
    r"|\b(?:en ese caso|en tal caso|y si|qué tal si|que tal si)\b",
    _re_mod.I)


def _voz_pregunta_con_hilo(pregunta: str, historial: list) -> str:
    """La pregunta que se va a BUSCAR, con el tema anterior si hace falta.

    No cambia lo que se le manda al modelo —eso lleva el historial completo—:
    cambia sólo el texto con el que se recupera del acervo.
    """
    limpia = (pregunta or "").strip()
    if not limpia:
        return limpia
    palabras = len(limpia.split())
    if palabras > 7 and not _VOZ_SIGUE_EL_HILO.search(limpia):
        return limpia                      # se sostiene sola: no se toca

    # El tema es la última pregunta del abogado, no la respuesta del agente: la
    # respuesta trae rubros y artículos que arrastrarían la búsqueda hacia lo ya
    # dicho en vez de hacia lo que se pregunta ahora.
    anterior = ""
    for m in reversed(historial or []):
        if getattr(m, "role", "") == "user" and (getattr(m, "content", "") or "").strip():
            anterior = m.content.strip()
            break
    if not anterior:
        return limpia
    print(f"   🧵 VOZ: la pregunta sigue el hilo — se busca con «{anterior[:40]}…»")
    return f"{anterior} {limpia}"


async def _voz_buscar(pregunta: str, estado: Optional[str]) -> List[dict]:
    """Recupera del acervo normativo. En paralelo, y sin sentencias.

    DOS ANCLAS, Y NO ES UN LUJO
    ---------------------------
    La primera versión buscaba con las palabras crudas de la pregunta y, en la
    primera prueba, «qué artículos regulan el derecho del tanto en Querétaro»
    devolvió la Ley del Deporte del Estado de Querétaro. Es exactamente el
    síntoma que tuvo el chat durante meses con HyDE apagado, y hay directriz
    expresa de no volver a perder la recuperación por concepto.

    Aquí no se puede usar HyDE: es una llamada más a un modelo y son dos
    segundos que la voz no tiene. Pero la otra ancla del chat —el concepto
    limpio— es un regex que no cuesta nada. Se buscan las dos y se FUNDEN POR
    RANGO, con el concepto pesando más.

    CUPOS QUE SE ADAPTAN A LA PREGUNTA
    ----------------------------------
    Un cupo plano de dos por silo dejaba fuera la tesis que contestaba, y a la
    vez, en cuanto se abría la mano, la jurisprudencia se comía los diez huecos
    en preguntas que pedían un artículo. Así que el cupo depende de lo que se
    pregunta: quien pide un criterio recibe criterios; quien pide un artículo
    recibe artículos, con jurisprudencia de acompañamiento y no al revés.
    """
    silos = list(FIXED_SILOS.values())
    silo_estado = ESTADO_SILO.get((estado or "").upper().strip())
    if silo_estado:
        silos.append(silo_estado)
    silos.append("doctrina")

    concepto = _texto_concepto(pregunta, estado) or ""
    anclas = [(pregunta, 1.0)]
    if concepto and concepto != pregunta:
        anclas.append((concepto, _VOZ_PESO_CONCEPTO))

    vectores = await asyncio.gather(*[get_dense_embedding(a) for a, _ in anclas])

    async def uno(col: str, vector, peso: float):
        try:
            r = await qdrant_client.query_points(
                collection_name=col, query=vector, limit=_VOZ_POR_SILO,
                with_payload=True, using="dense",
            )
            return col, peso, r.points
        except Exception as e:
            # Un silo que falla no tumba la respuesta: se sigue con los demás y
            # se deja constancia. Callarlo sería repetir el fallo mudo de HyDE.
            print(f"   🔇 VOZ: silo {col} falló ({err(e)}) — se sigue sin él")
            return col, peso, []

    tareas = [uno(c, vectores[i], anclas[i][1])
              for i in range(len(anclas)) for c in silos]
    resultados = await asyncio.gather(*tareas)

    puntos_rrf: dict = {}
    mejor: dict = {}
    for col, peso, puntos in resultados:
        for rango, p in enumerate(puntos):
            d = _voz_documento(col, p)
            if not d:
                continue
            k = _voz_llave(d)
            puntos_rrf[k] = puntos_rrf.get(k, 0.0) + peso / (_VOZ_K_RRF + rango)
            # De dos trozos del mismo artículo se queda el más largo: es el que
            # tiene el texto entero y no el arrastre del anterior.
            if k not in mejor or len(d["texto"]) > len(mejor[k]["texto"]):
                mejor[k] = d

    ordenados = [mejor[k] for k, _ in sorted(
        puntos_rrf.items(),
        key=lambda kv: -(kv[1] * _voz_empujon(concepto or pregunta, mejor[kv[0]])))]
    if not ordenados:
        return []

    criterio = bool(_VOZ_ES_CRITERIO.search(pregunta or ""))
    silo_juris = FIXED_SILOS["jurisprudencia"]

    if criterio:
        print("   ⚖️ VOZ: pregunta de criterio — jurisprudencia con cupo ampliado")
        elegidos = await _voz_reordenar(concepto or pregunta, ordenados[:40], VOZ_TOPE_DOCS)
    else:
        # Sin reordenador —no lo gana en preguntas de artículo—, pero con techo
        # a la jurisprudencia para que no desplace a la ley, y con sitio
        # garantizado para el silo del estado y para el federal.
        elegidos, vistos = [], {}
        # PRIMERO LA CASA. Si la pregunta es de un estado, sus artículos entran
        # antes que nada: preguntando por el derecho del tanto en Querétaro
        # llegaban tres artículos del código local y el resto de los huecos se
        # iba en federales y tesis, cuando el código del estado tiene la figura
        # repartida en cinco preceptos —copropietarios, usufructuario,
        # coherederos, socios, aparceros— y el abogado los quiere todos.
        if silo_estado:
            for d in ordenados:
                if len(elegidos) >= 5:
                    break
                if d["coleccion"] == silo_estado:
                    vistos[silo_estado] = vistos.get(silo_estado, 0) + 1
                    elegidos.append(d)
            ya_dentro = {id(x) for x in elegidos}
            ordenados = [d for d in ordenados if id(d) not in ya_dentro]
        for d in ordenados:
            if len(elegidos) >= VOZ_TOPE_DOCS:
                break
            col = d["coleccion"]
            # El bloque constitucional y la doctrina acompañan, no mandan: sus
            # Cuadernillos de la CoIDH ocupaban dos de los diez huecos en una
            # pregunta sobre el Código Civil de Querétaro.
            techo = {silo_juris: 3, "doctrina": 1,
                     FIXED_SILOS["constitucional"]: 1}.get(col, 5)
            if vistos.get(col, 0) >= techo:
                continue
            vistos[col] = vistos.get(col, 0) + 1
            elegidos.append(d)
        # Si con los techos no se llenaron los diez huecos, se completan con lo
        # mejor que quedó: un hueco vacío no ayuda a nadie.
        if len(elegidos) < VOZ_TOPE_DOCS:
            ya = {id(d) for d in elegidos}
            elegidos += [d for d in ordenados if id(d) not in ya][:VOZ_TOPE_DOCS - len(elegidos)]
        # Y lo de la entidad primero: es lo que rige para quien pregunta.
        if silo_estado:
            elegidos.sort(key=lambda d: d["coleccion"] != silo_estado)

    return elegidos[:VOZ_TOPE_DOCS]


def _voz_revisar_citas(texto: str, docs: List[dict], pregunta: str = "") -> tuple:
    """El respaldo sale SÓLO del acervo, nunca de la web.

    Es la regla que sostiene el producto. Un artículo de opinión que menciona
    el artículo 17 no autoriza a dictarlo como fundamento: un blog no es una
    ley. Si se aceptara, un día el agente diría «el artículo 17 establece X»
    apoyado en una columna de periódico, y ahí se pierde todo lo construido.
    Por eso `docs` aquí son únicamente los del acervo — el bloque web se pasa
    al modelo, pero no cuenta como aval."""
    """¿Dijo algún artículo que no le dimos?

    Devuelve (limpio, sospechas). Es deliberadamente conservador: sólo señala
    cuando hay prueba positiva de que el número no está en el contexto. Un
    detector que salta por las dudas se acaba apagando, y entonces no sirve el
    día que hace falta.
    """
    numeros_dados = {d["articulo"] for d in docs if d["articulo"]}
    for d in docs:
        # El número también puede venir dentro del `ref` («Artículo 2500.»).
        for m in re.finditer(r"(\d+)", d.get("ref") or ""):
            numeros_dados.add(m.group(1))
        # Y —esto faltaba— DENTRO DEL TEXTO del documento. Una tesis cuyo rubro
        # dice «es inaplicable el artículo 166 de la Ley de Hacienda del Estado»
        # respalda perfectamente que el agente cite el 166; mirar sólo los
        # metadatos lo daba por inventado y retiraba una respuesta correcta.
        # Le pasó a David en su primera prueba en el teléfono.
        #
        # Se buscan sólo los que van precedidos de «artículo», no todos los
        # números del texto: un año, un registro o una cantidad no respaldan
        # nada, y aceptarlos convertiría el candado en un adorno.
        # Y con la abreviatura, que es como está escrito medio acervo. El
        # Código Civil de Nuevo León no dice «artículo 2334»: dice «Art.
        # 2334.-». Mirando sólo la palabra entera, el verificador daba por
        # inventado un artículo que estaba delante, retiraba la respuesta
        # buena y el abogado oía «prefiero no dictarle un número» teniendo el
        # texto en el contexto. Pasó con «requisitos del arrendamiento en
        # Nuevo León» en el banco del 24-ago-2026.
        for m in re.finditer(r"\bart[íi]culos?\s+(\d{1,4})|\bart[sº°]?\.\s*(\d{1,4})",
                             d.get("texto") or "", re.I):
            numeros_dados.add(m.group(1) or m.group(2))

    # Los números que vienen EN LA PREGUNTA no cuentan. Cuando el abogado pide
    # «el artículo 9999» y el agente contesta «no tengo el artículo 9999», está
    # repitiendo la pregunta para negarla —que es exactamente la conducta que
    # queremos— y contarlo como invención retiraba la respuesta CORRECTA. Se vio
    # en la prueba de humo: la negativa buena se quedaba sin decir.
    numeros_dados |= set(re.findall(r"(\d{1,4})", pregunta or ""))

    citados = set(re.findall(r"art[íi]culos?\s+(\d{1,4})", texto, re.I))
    sospechas = sorted(c for c in citados if c not in numeros_dados)
    return (not sospechas), sospechas


# ── Lo que se dice y lo que se enseña ────────────────────────────────────────
#
# Dos arreglos que salen de oír la app, no de leer el código:
#
#   «cuando habla y cita las tesis no se entiende nada por los números romanos»
#   «me tira fuentes que ni siquiera cita habladas»
#
# El primero se ataca en el prompt —se le pide el rubro y el registro— pero el
# prompt es una petición, no una garantía, y esto se lee en voz alta delante de
# un juez. Así que además se borra la clave del texto ANTES de mandarlo a la
# voz. El segundo es de bulto: la pantalla pintaba los diez documentos
# recuperados aunque la respuesta se apoyara en dos.

# Una clave de tesis, en sus tres formas: la de Pleno o Sala («2a./J. 39/95»,
# «P./J. 20/2014»), la de Plenos de Circuito («PC.III.C. J/21 C (10a.)») y la
# de Tribunal Colegiado («XXII.3o.A.C.1 A (11a.)»). Se exige que haya barra o
# paréntesis de época para no morder nunca un «fracción II» ni un «artículo
# 17»: sin esa exigencia, cualquier romano seguido de punto sería sospechoso.
_VOZ_CLAVE_TESIS = _re_mod.compile(
    r"(?:\b(?:P|PC|\d[ªaº])\.(?:[A-Z]{1,4}\.)*\s*/?\s*J\.?\s*/?\s*\d+(?:/\d{2,4})?"
    r"(?:\s+[A-Z]{1,3})?(?:\s*\(\d{1,2}[ªaº]?\.\))?"
    r"|\b\d[ªaº]\.\s*[A-Z]{1,4}/\d{2,4}(?:\s*\(\d{1,2}[ªaº]?\.\))?"
    r"|\b[IVXLCDM]{1,6}\.\d{1,2}[ºo]\.[A-Za-z0-9º°.]{0,20}(?:\s+[A-Z]{1,3})?"
    r"(?:\s*\(\d{1,2}[ªaº]?\.\))?"
    r"|\b[IVXLCDM]{1,6}\.[A-Za-z0-9º°.]{1,24}(?:\s+[A-Z]{1,3})?\s*\(\d{1,2}[ªaº]?\.\))")


def _voz_sin_claves(texto: str, docs: List[dict]) -> str:
    """Quita del texto hablado las claves de tesis y deja el registro.

    No se borra la referencia: se SUSTITUYE por lo que sí sirve de oído. Si la
    clave que dijo el modelo es de un documento que tenemos, se cambia por «con
    registro 2025216»; si no lo es, se quita y la frase se queda con el rubro,
    que es lo que identifica al criterio hablando.
    """
    if not texto:
        return texto
    salida = texto
    # Primero las claves que conocemos, que son las que podemos cambiar por su
    # registro exacto.
    for d in sorted(docs, key=lambda x: -len(x.get("clave") or "")):
        clave = (d.get("clave") or "").strip()
        if not clave or clave not in salida:
            continue
        registro = (d.get("registro") or "").strip()
        salida = salida.replace(clave, f"con registro {registro}" if registro
                                and registro not in salida else "")
    # Y después, lo que quede con forma de clave aunque no sea de un documento
    # nuestro: dicho en voz alta es ruido igual.
    salida = _VOZ_CLAVE_TESIS.sub("", salida)
    # Costuras: dobles espacios, comas huérfanas y «la tesis , registro».
    salida = _re_mod.sub(r"\s+([,;.])", r"\1", salida)
    salida = _re_mod.sub(r"([,;])\s*([,;.])", r"\2", salida)
    salida = _re_mod.sub(r"\s{2,}", " ", salida)
    salida = _re_mod.sub(r"\(\s*\)", "", salida)
    return salida.strip()


def _voz_fuentes_citadas(texto: str, docs: List[dict], fuentes: List[dict]) -> List[dict]:
    """De los diez documentos, los que la respuesta usó de verdad.

    David lo dijo tras probarla: «me tira fuentes que ni siquiera cita
    habladas». Medido en el banco antes de arreglarlo: de diez fuentes
    pintadas, entre seis y ocho no se mencionaban. Eso no es transparencia, es
    ruido — y encima invita a abrir un PDF que no sostiene lo que se acaba de
    oír.

    Se cuenta como citada si el texto dice su registro, o su número de artículo
    precedido de «artículo», o tres palabras largas de su rótulo. Si no queda
    ninguna —una negativa, un cálculo— se devuelven todas: una pantalla vacía
    es peor que una pantalla de más.
    """
    if not texto or not docs:
        return fuentes
    bajo = texto.lower()
    citados = _re_mod.findall(r"art[íi]culos?\s+([\d\s,yo\.]+)", bajo)
    numeros = set()
    for tramo in citados:
        numeros.update(_re_mod.findall(r"\d{1,4}", tramo))

    usadas = []
    for d, f in zip(docs, fuentes):
        registro = (d.get("registro") or "").strip()
        if registro and registro in texto:
            usadas.append(f)
            continue
        articulo = (d.get("articulo") or "").strip() or "".join(
            _re_mod.findall(r"\d{1,4}", d.get("ref") or "")[:1])
        if articulo and articulo in numeros:
            usadas.append(f)
            continue
        rotulo = (d.get("rubro") or d.get("ley") or "").lower()
        palabras = [p for p in _re_mod.findall(r"\w{5,}", rotulo)][:4]
        if len(palabras) >= 3 and sum(1 for p in palabras if p in bajo) >= 3:
            usadas.append(f)
    # Las de internet no se filtran: si se buscaron, es porque la pregunta las
    # pedía, y el abogado tiene que poder ir a leerlas antes de citarlas él.
    usadas += [f for f in fuentes[len(docs):]]
    return usadas or fuentes


def _voz_frases(texto: str) -> List[str]:
    """Corta en frases SIN partir por dentro de unas comillas.

    Un rubro lleva punto: «Derecho del tanto. No se actualiza cuando la
    transmisión se realiza entre copropietarios». Cortando por el punto a
    secas, ese rubro son dos frases, y al podar la segunda quedó en pantalla
    «La tesis con rubro "Derecho del tanto. Hay un punto que no pude
    respaldar…»: una comilla abierta que no cierra y una cita descabezada.
    Lo vio David en el simulador el 24-ago-2026.
    """
    abre, cierra = "«“\"", "»”\""
    frases, actual, dentro = [], [], False
    for i, ch in enumerate(texto):
        actual.append(ch)
        if ch in abre and not dentro:
            dentro = True
        elif ch in cierra and dentro:
            dentro = False
        elif ch in ".!?" and not dentro:
            # Se corta sólo si lo que sigue es espacio y arranca otra frase.
            resto = texto[i + 1:i + 3]
            if resto[:1] in (" ", "\n", ""):
                frases.append("".join(actual))
                actual = []
    if actual:
        frases.append("".join(actual))
    # SIN `strip()`, y esto no es una manía. El texto llega por trozos del
    # modelo, y un trozo puede acabar en espacio —«El artículo » y luego «79»—.
    # Recortando aquí y volviendo a unir después, ese espacio se perdía y salía
    # «El artículo79», en la pantalla y en la voz. Se limpia al usarlas, no al
    # cortarlas.
    return [f for f in frases if f.strip()]


def _voz_primer_aliento(pendiente: str, minimo: int = 60) -> tuple:
    """El primer trozo se corta antes: en la primera coma que ya tenga cuerpo.

    Medido: la primera frase completa tardaba 5,9 s en salir —el modelo tiene
    que escribirla entera— y hasta entonces el teléfono estaba mudo. Pero una
    voz puede empezar a hablar en la primera cláusula: «La jurisprudencia
    sostiene que en amparo laboral la suplencia opera a favor del trabajador,»
    ya es algo que decir, y el sintetizador hace ahí una pausa natural.

    SÓLO PARA EL PRIMER TROZO. Después manda la frase completa, que suena
    mejor; esto es para que la conversación arranque, no para trocearla toda.
    """
    abre, cierra, dentro = "«“\"", "»”\"", False
    for i, ch in enumerate(pendiente):
        if ch in abre and not dentro:
            dentro = True
        elif ch in cierra and dentro:
            dentro = False
        elif ch in ",;:" and not dentro and i >= minimo:
            return pendiente[:i + 1].strip(), pendiente[i + 1:]
    return "", pendiente


def _voz_podar_sin_respaldo(texto: str, sospechas: List[str]) -> str:
    """Tira la frase que trae el número sin respaldo, no la respuesta entera.

    El candado —no dictar un artículo que no está en el acervo— es correcto y
    no se toca. Lo que estaba mal era el castigo: por UN número inventado en la
    quinta frase se retiraba todo, y el abogado oía «prefiero no dictarle un
    número» después de esperar tres segundos, sin nada aprovechable. Pasó en
    producción el 24-ago-2026 con «qué es el derecho del tanto»: el modelo
    coló un artículo 244 y se perdieron cuatro frases correctas.

    Se corta por frases, se tiran las que contienen el número señalado y se
    devuelve el resto. Si lo que queda no sostiene una respuesta, quien llama
    se queda con la retirada de siempre.
    """
    if not texto or not sospechas:
        return texto
    frases = _voz_frases(texto)
    numeros = "|".join(_re_mod.escape(n) for n in sospechas)
    patron = _re_mod.compile(rf"art[íi]culos?\s+[^.;]*?\b(?:{numeros})\b", _re_mod.I)
    quedan = [f for f in frases if not patron.search(f)]
    podado = " ".join(quedan).strip()
    # ¿Sobrevivió una respuesta de verdad? Hace falta cuerpo y al menos una
    # cita en pie; si no, mejor la negativa honrada que un muñón.
    if len(podado) < 120 or not _re_mod.search(r"art[íi]culo|registro|tesis", podado, _re_mod.I):
        return ""
    # Si la frase podada se llevó el cierre de unas comillas, se quita el que
    # quedó abierto: una cita a medias es peor que ninguna.
    for a, c in (("«", "»"), ("“", "”")):
        if podado.count(a) > podado.count(c):
            podado = podado.replace(a, "", podado.count(a) - podado.count(c))
    return podado + " Hay un punto que no pude respaldar en mi acervo y preferí omitirlo."


def _voz_anotar_caracteres(user_id: str, cuantos: int) -> None:
    """Suma al contador del día los caracteres que se van a hablar.

    Es lo que hace medible el gasto de ElevenLabs SIN depender de su API —la
    llave de la casa no tiene permiso de lectura de cuenta— y sobre todo lo
    hace medible por usuario, que es lo que la factura nunca dice.

    A fuego y olvido: si esto falla, la respuesta ya está dada y no se toca.
    """
    if not supabase_admin or cuantos <= 0:
        return
    try:
        # Por RPC y no con un UPDATE desde aquí: un leer-modificar-escribir se
        # pisa cuando dos respuestas terminan a la vez, y así el día se calcula
        # en hora de México DENTRO de la base, sin depender de la zona horaria
        # del proceso.
        supabase_admin.rpc("voz_sumar_caracteres",
                           {"p_user_id": user_id, "p_caracteres": int(cuantos)}).execute()
    except Exception as e:
        print(f"   ⚠️ VOZ: no pude anotar caracteres (no fatal): {err(e)}")


@app.post("/api/voz")
async def abogado_ia_voz(payload: VozRequest, authorization: str = Header(None)):
    """El Abogado IA. Respuesta hablada, corta y anclada a documentos reales."""
    if not payload.pregunta.strip():
        raise HTTPException(status_code=400, detail="No llegó la pregunta.")
    if not authorization:
        raise HTTPException(status_code=401, detail="Autenticación requerida")
    if not supabase_admin:
        raise HTTPException(status_code=503, detail="Servicio temporalmente no disponible")

    # 1) Quién pregunta. El token, siempre. Nunca un correo ni un id del cuerpo:
    #    catorce endpoints de este archivo se protegen con un `user_email` que
    #    escribe el cliente, y ese candado se abre tecleando otro correo.
    try:
        token = authorization.replace("Bearer ", "")
        user_resp = await asyncio.to_thread(supabase_admin.auth.get_user, token)
        user = user_resp.user
        if not user:
            raise HTTPException(status_code=401, detail="Token inválido")
        user_id, user_email = str(user.id), (user.email or "")
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=401, detail="Token inválido o expirado")

    # 2) El piloto. Dos cuentas.
    if not _voz_permitida(user_email, user_id):
        raise HTTPException(status_code=403, detail="El Agente IA está en pruebas cerradas.")

    # 3) El tope DIARIO. Va antes que la cuota mensual porque protege de otra
    #    cosa: la mensual cuida el margen; ésta cuida del accidente. Un teléfono
    #    que se queda escuchando en un bolsillo factura hasta agotar la batería,
    #    y cada turno son caracteres de ElevenLabs —el 96% del coste, medido—.
    #
    #    El contador vive en `voz_uso`, con RLS activada y CERO políticas: nadie
    #    salvo el servidor puede tocarlo. Es el patrón de salvame_usage_log, y
    #    es lo contrario de lo que permitía user_profiles hasta hoy.
    try:
        cuenta = await asyncio.to_thread(
            lambda: supabase_admin.rpc("voz_contar", {"p_user_id": user_id, "p_caracteres": 0}).execute()
        )
        llevados = int(cuenta.data or 0)
        if llevados > VOZ_TOPE_DIARIO:
            raise HTTPException(
                status_code=429,
                detail=f"Llegaste a las {VOZ_TOPE_DIARIO} preguntas de voz de hoy. "
                       f"Mañana se reinicia; mientras tanto, el chat sigue disponible.",
            )
    except HTTPException:
        raise
    except Exception as e:
        # Si el contador falla, NO se bloquea: se deja pasar y se avisa. Un
        # candado roto que cierra la puerta es peor que uno que no cuenta.
        print(f"[voz] contador diario falló (se deja pasar): {err(e)}")

    # 4) Y la cuota mensual del plan, que se descuenta de las mismas consultas.
    #    Un turno de voz cuesta lo mismo que una consulta escrita para el
    #    usuario, aunque para nosotros cueste distinto: es más fácil de
    #    entender y no obliga a explicar dos contadores.
    try:
        q = await asyncio.to_thread(
            lambda: supabase_admin.rpc("consume_query", {"p_user_id": user_id}).execute()
        )
        if q.data and not q.data.get("allowed", True):
            raise HTTPException(status_code=429, detail="Se te acabaron las consultas de este periodo.")
    except HTTPException:
        raise
    except Exception as e:
        print(f"[voz] cuota falló: {err(e)}")

    t0 = time.time()
    # La web arranca A LA VEZ que el RAG, no después: así sus 3,2 s corren
    # dentro de los del acervo en vez de sumarse.
    _con_web = bool(_VOZ_PIDE_WEB.search(payload.pregunta or "")) and \
        os.getenv("VOZ_WEB", "true").lower() != "false"
    _tarea_web = asyncio.create_task(_voz_web(payload.pregunta)) if _con_web else None
    # El RAG también arranca ya, en paralelo con la web. Se aguarda enseguida
    # —el contexto hace falta para el prompt— pero las dos esperas se solapan
    # en vez de sumarse.
    estado = (payload.estado or "").strip() or await asyncio.to_thread(
        _voz_estado_del_perfil, user_id)
    if estado and not (payload.estado or "").strip():
        print(f"   📍 VOZ: la app no mandó estado; el perfil dice {estado}")
    # Lo que se BUSCA lleva el hilo de la conversación; lo que se le manda al
    # modelo sigue siendo la pregunta tal cual, con su historial aparte.
    docs = await _voz_buscar(_voz_pregunta_con_hilo(payload.pregunta, payload.historial), estado)
    t_rag = time.time() - t0
    print(f"   🎙️ VOZ: {len(docs)} documentos en {t_rag*1000:.0f} ms · {correo_opaco(user_email)}")

    if not docs:
        return {
            "respuesta": ("No encontré nada sobre eso en mi acervo. "
                          "Dígamelo de otra forma o precise el ordenamiento."),
            "fuentes": [], "modelo": None,
        }

    # CADA DOCUMENTO, CON SUS CAMPOS SEPARADOS Y CON NOMBRE.
    #
    # Antes iba todo en una línea —«ley — ref»— y con las tesis eso significaba
    # entregarle al modelo el nombre del fichero y la clave, que es justo lo
    # ilegible. Si lo único que tiene delante es «2a./J. 39/95», eso es lo que
    # va a decir. Poniendo RUBRO y REGISTRO con su etiqueta, el modelo puede
    # cumplir la regla de decirlos, y se le recuerda en el propio documento
    # que la clave no se dicta.
    def _bloque(i: int, d: dict) -> str:
        if d.get("es_tesis"):
            cabeza = f"[{i+1}] TESIS"
            if d.get("rubro"):
                cabeza += f"\nRUBRO: {d['rubro']}"
            if d.get("registro"):
                cabeza += f"\nREGISTRO: {d['registro']}"
            if d.get("clave"):
                cabeza += f"\nCLAVE (NO LA DIGAS EN VOZ ALTA): {d['clave']}"
            return f"{cabeza}\nTEXTO: {d['texto']}"
        cabeza = f"[{i+1}] {d['ley']}"
        if d.get("ref"):
            cabeza += f" — {d['ref']}"
        return f"{cabeza}\n{d['texto']}"

    contexto = "\n\n".join(_bloque(i, d) for i, d in enumerate(docs))
    web = {}
    if _tarea_web is not None:
        try:
            web = await asyncio.wait_for(_tarea_web, timeout=9.0)
        except Exception:
            _tarea_web.cancel()
            web = {}
    if web.get("texto"):
        # Va SEPARADO del acervo y con su etiqueta. La distinción no es
        # cosmética: es la diferencia entre «la ley dice» y «un jurista opina».
        contexto += (
            "\n\n─── LO QUE SE ENCONTRÓ EN INTERNET (NO ES ACERVO) ───\n"
            + web["texto"][:1800]
            + ("\n\nFuentes: " + " · ".join(web.get("urls") or []) if web.get("urls") else "")
        )
        print(f"   🌐 VOZ: web con {len(web.get('urls') or [])} fuentes")

    mensajes = [{"role": "system", "content": _VOZ_SISTEMA}]
    # Seis turnos y no cuatro: una consulta jurídica hablada encadena —«¿y el
    # plazo?», «¿y si ya venció?», «¿eso aplica en materia laboral?»— y con
    # cuatro se perdía el asunto justo cuando la conversación se ponía útil.
    # Cada turno recortado a 600 caracteres, que es lo que impide que esto
    # crezca sin freno como pasó en el chat escrito.
    for m in payload.historial[-6:]:
        if m.role in ("user", "assistant"):
            mensajes.append({"role": m.role, "content": (m.content or "")[:600]})
    mensajes.append({"role": "user",
                     "content": f"DOCUMENTOS:\n{contexto}\n\nPREGUNTA: {payload.pregunta.strip()}"})

    fuentes = [{"ley": d["ley"], "ref": d["ref"], "pdf": d["pdf"],
                "registro": d.get("registro") or "", "entidad": d["entidad"]}
               for d in docs]
    # Las de internet van al final y con el enlace abierto: «según Ferrajoli»
    # sólo vale si el abogado puede ir a leerlo antes de citarlo él.
    for u in (web.get("urls") or [])[:3]:
        fuentes.append({"ley": _dominio_legible(u), "ref": "Publicación en internet",
                        "pdf": u, "entidad": "WEB"})

    if payload.stream:
        async def emitir():
            # EL AVISO VA LO PRIMERO DE TODO, antes incluso de las fuentes.
            #
            # Medido: colocado después del RAG salía a los 5,6 s, o sea cuando
            # la espera ya había ocurrido. Un relleno que llega tarde no
            # consuela: sólo suma ruido. Aquí sale con el primer byte de la
            # respuesta, mientras la búsqueda corre por detrás.
            if _con_web:
                yield json.dumps({"tipo": "buscando",
                                  "texto": "Permítame buscarlo, un segundo."}) + "\n"
            # Las fuentes van después: la pantalla puede pintarlas mientras el
            # modelo todavía redacta. En audiencia, eso es lo que el abogado
            # mira mientras escucha.
            yield json.dumps({"tipo": "fuentes", "fuentes": fuentes}) + "\n"
            # ── SE HABLA POR FRASES, NO AL FINAL ──────────────────────
            #
            # Con respuestas de tres a seis frases, esperar al texto entero son
            # de tres a seis segundos de silencio, y encima la voz de calidad
            # tarda otro segundo y medio en arrancar. De pie frente a un juez
            # eso parece una avería.
            #
            # Así que cada frase se manda en cuanto está completa y el teléfono
            # la va diciendo mientras el modelo sigue escribiendo. El `delta`
            # se mantiene para la PANTALLA —el texto aparece letra a letra como
            # hasta ahora—; la frase es para el ALTAVOZ.
            #
            # Y aquí está lo que hace que esto sea admisible: CADA FRASE SE
            # VERIFICA ANTES DE SALIR. Emitir sin comprobar rompería la regla
            # que sostiene el producto —no dictar un artículo que no está en el
            # acervo—, porque lo dicho, dicho está. La frase que cita un número
            # sin respaldo no se manda: es la misma poda de antes, aplicada
            # sobre la marcha en vez de al final.
            trozos, dichas, pendiente, retiradas = [], [], "", []

            def _cocinar(frase: str):
                """Verifica, limpia y decide si esa frase se puede decir."""
                frase = frase.strip()
                if not frase:
                    return None
                limpia, sospecha = _voz_revisar_citas(frase, docs, payload.pregunta)
                if not limpia:
                    retiradas.extend(sospecha)
                    return None
                return _voz_sin_claves(frase, docs).strip() or None

            try:
                flujo = await deepseek_client.chat.completions.create(
                    model=VOZ_MODELO, messages=mensajes, max_tokens=VOZ_MAX_TOKENS,
                    temperature=0.2, stream=True,
                    extra_body={"reasoning": {"enabled": False}},
                )
                async for parte in flujo:
                    if not parte.choices:
                        continue
                    delta = parte.choices[0].delta.content or ""
                    if not delta:
                        continue
                    trozos.append(delta)
                    yield json.dumps({"tipo": "delta", "texto": delta}) + "\n"
                    pendiente += delta
                    # Arrancar cuanto antes: mientras no se haya dicho nada, el
                    # primer trozo se corta en la primera coma con cuerpo.
                    # EL ARRANQUE SE CORTA EN LA PRIMERA COMA CON CUERPO.
                    #
                    # Esperar a la primera oración COMPLETA sonaba mejor, pero
                    # medido son 6 s de silencio antes de la primera palabra;
                    # cortando en la coma son 3. Y la pausa que deja una coma
                    # es la que el oído espera ahí de todas formas.
                    #
                    # Sólo el arranque: el resto va de una pieza, así que la
                    # respuesta entera tiene UNA costura, y encima al principio,
                    # que es donde menos se nota porque el abogado todavía está
                    # colocándose el teléfono.
                    if not dichas and len(pendiente) >= 90:
                        cabeza, resto = _voz_primer_aliento(pendiente, 70)
                        if cabeza:
                            primera = _cocinar(cabeza)
                            if primera:
                                dichas.append(primera)
                                yield json.dumps({"tipo": "frase", "texto": primera}) + "\n"
                                pendiente = resto
                            else:
                                pendiente = resto
                    frases = _voz_frases(pendiente)
                    if len(frases) > 1:
                        # La última siempre puede estar a medias: se guarda
                        # para la vuelta siguiente. Y una frase de tres
                        # palabras no se manda sola —«Sí.» suena
                        # entrecortado—: se junta con la que viene hasta
                        # juntar cuerpo suficiente para que suene a frase.
                        completas, resto = frases[:-1], frases[-1]
                        listas, junta = [], ""
                        for f in completas:
                            junta += f
                            # 180 y no 40: cada trozo es un audio aparte y cada
                            # costura se oye. Con trozos de una sola oración,
                            # una respuesta salían siete audios y siete pausas;
                            # juntando hasta 180 caracteres salen tres. La voz
                            # además entona mejor cuanto más contexto tiene.
                            # EL TROZO TIENE QUE DURAR MÁS DE LO QUE TARDA EL
                            # SIGUIENTE EN FABRICARSE. Ésa es toda la regla.
                            #
                            # Mandar el resto de la respuesta ENTERO al final
                            # parecía lo más limpio —una sola costura— pero
                            # dejaba justo el bache que David describió: «la
                            # primera coma deja una pausa muy larga». La razón
                            # es de aritmética: ese segundo trozo no se puede
                            # empezar a fabricar hasta que el modelo termina de
                            # escribir, y para entonces el primero ya casi se
                            # acabó de oír.
                            #
                            # Con trozos de 250 caracteres, cada uno dura unos
                            # 17 segundos hablados y el siguiente tarda 2,5 en
                            # estar listo: llega con quince segundos de sobra y
                            # el cambio no se oye. Más costuras, pero todas
                            # tapadas — que es mejor que una sola al aire.
                            if len(junta) >= 250:
                                listas.append(junta)
                                junta = ""
                        pendiente = junta + resto
                        for f in listas:
                            lista = _cocinar(f)
                            if lista:
                                dichas.append(lista)
                                yield json.dumps({"tipo": "frase", "texto": lista}) + "\n"
            except Exception as e:
                print(f"[voz] streaming reventó: {err(e)}")
                yield json.dumps({"tipo": "error", "mensaje": "No se pudo generar la respuesta."}) + "\n"
                return

            ultima = _cocinar(pendiente)
            if ultima:
                dichas.append(ultima)
                yield json.dumps({"tipo": "frase", "texto": ultima}) + "\n"

            texto = " ".join(d.strip() for d in dichas).strip()
            if retiradas:
                print(f"   ✂️ VOZ: {len(retiradas)} cita(s) sin respaldo retiradas: {sorted(set(retiradas))}")
            if not texto:
                # No sobrevivió nada: se dice que no, que es una respuesta
                # correcta, y no se dicta un número que no se puede respaldar.
                print(f"   🛑 VOZ: retirada por citar {sorted(set(retiradas))} sin respaldo")
                yield json.dumps({
                    "tipo": "retirada", "articulos": sorted(set(retiradas)),
                    "respuesta": ("Tengo la respuesta a medias y prefiero no dictarle un número "
                                  "que no puedo respaldar. Permítame buscarlo de otra forma."),
                }) + "\n"
                return
            if retiradas:
                texto += " Hay un punto que no pude respaldar en mi acervo y preferí omitirlo."

            # Las fuentes se vuelven a mandar recortadas a las que la respuesta
            # usó de verdad. La pantalla ya pintó la lista larga con el primer
            # byte —eso es lo que da la sensación de rapidez— y este segundo
            # envío la sustituye por la buena; la app repinta con cada evento
            # «fuentes», así que no hace falta tocarla.
            citadas = _voz_fuentes_citadas(texto, docs, fuentes)
            if len(citadas) != len(fuentes):
                print(f"   📚 VOZ: {len(citadas)} de {len(fuentes)} fuentes se citaron de viva voz")
                yield json.dumps({"tipo": "fuentes", "fuentes": citadas}) + "\n"

            _voz_anotar_caracteres(user_id, len(texto))
            print(f"   🎙️ VOZ: {time.time()-t0:.2f}s total · {VOZ_MODELO} · {len(texto)} chars "
                  f"· {len(dichas)} frases habladas")
            yield json.dumps({"tipo": "fin", "respuesta": texto, "fuentes": citadas}) + "\n"

        return StreamingResponse(
            emitir(), media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    try:
        r = await deepseek_client.chat.completions.create(
            model=VOZ_MODELO, messages=mensajes, max_tokens=VOZ_MAX_TOKENS,
            temperature=0.2, extra_body={"reasoning": {"enabled": False}},
        )
        respuesta = (r.choices[0].message.content or "").strip()
    except Exception as e:
        print(f"[voz] reventó: {err(e)}")
        raise HTTPException(status_code=502, detail="No se pudo generar la respuesta.")

    limpio, sospechas = _voz_revisar_citas(respuesta, docs, payload.pregunta)
    if not limpio and not _voz_podar_sin_respaldo(respuesta, sospechas):
        print(f"   🛑 VOZ: retirada por citar {sospechas} sin respaldo")
        respuesta = ("Tengo la respuesta a medias y prefiero no dictarle un número que no puedo "
                     "respaldar. Permítame buscarlo de otra forma.")
        fuentes = []
    else:
        if not limpio:
            print(f"   ✂️ VOZ: frase con {sospechas} podada; el resto se mantiene")
            respuesta = _voz_podar_sin_respaldo(respuesta, sospechas)
        respuesta = _voz_sin_claves(respuesta, docs)
        fuentes = _voz_fuentes_citadas(respuesta, docs, fuentes)

    _voz_anotar_caracteres(user_id, len(respuesta))
    print(f"   🎙️ VOZ: {time.time()-t0:.2f}s total · {VOZ_MODELO}")
    return {"respuesta": respuesta, "fuentes": fuentes, "modelo": VOZ_MODELO}


import array
import math

# ── El volumen ───────────────────────────────────────────────────────────────
#
# David: «en el teléfono le falta volumen». No era el altavoz —eso se arregló—
# ni el formato. Es LA VOZ: está grabada bajísima. Medido el 24-ago-2026 sobre
# la misma frase y el mismo modelo, en dBFS:
#
#     Liza      RMS -36,2   pico -17,6      ← la nuestra
#     Fernanda  RMS -26,9   pico  -6,9
#     Jaime     RMS -22,1   pico  -4,1
#     Carlos    RMS -14,4   pico  -0,9      ← nivel normal de voz
#
# Liza sale VEINTIDÓS decibelios por debajo de una voz normal. Ningún ajuste de
# la app lo compensa: el reproductor de iOS no puede subir por encima del uno,
# y el volumen del sistema ya estaba al máximo.
#
# Así que se nivela aquí, en el servidor, y no se toca la voz que David eligió.
# Se pide PCM en vez de MP3 —el mismo precio, ElevenLabs no cobra por formato—,
# se sube hasta un objetivo de sonoridad con un techo que impide que nada se
# salga por arriba, y se vuelve a comprimir a MP3. Medido: 24 ms de ganancia y
# 20 ms de codificación para diez segundos de audio; frente a los 2.300 ms que
# tarda la propia voz en generarse, no se nota.
#
# Y NO ES SÓLO PARA ELEVENLABS: el día que se cambie de proveedor, el nivel de
# salida se seguirá midiendo aquí. Es la capa que hace comparable una voz con
# otra.

# Sonoridad a la que se quiere llegar. -20 dBFS RMS es lo normal en habla
# grabada para reproducción; por encima empieza a sonar apretado.
VOZ_RMS_OBJETIVO = float(os.getenv("VOZ_RMS_OBJETIVO", "-20"))
# Ningún pico puede pasar de aquí. Deja margen para que el MP3 no distorsione
# al reconstruir la onda.
VOZ_PICO_TECHO = float(os.getenv("VOZ_PICO_TECHO", "-1.5"))
# Tope de ganancia. Sin él, un fragmento casi mudo se amplificaría hasta sacar
# a flote el ruido de fondo.
VOZ_GANANCIA_MAX = float(os.getenv("VOZ_GANANCIA_MAX", "24"))
VOZ_PCM_HZ = 22050
VOZ_MP3_KBPS = int(os.getenv("VOZ_MP3_KBPS", "64"))


def _voz_recortar_silencio(pcm: bytes, hz: int, cabeza_ms: int = 12,
                           cola_ms: int = 35, umbral_db: float = -45.0) -> bytes:
    """Quita el silencio que cada trozo trae pegado delante y detrás.

    ES LO QUE SE OÍA COMO PAUSA. David lo dijo tras probarlo: «me parece muy
    pausada la conversación entre comas y puntos». No era el ritmo de la voz:
    hablamos por frases, cada frase es un audio distinto, y CADA AUDIO viene
    con su propio silencio de cortesía. Medido en Azure el 24-ago-2026: hasta
    71 ms delante y 293 ms detrás. Sumados en cada costura, más el hueco de
    pedir el siguiente, la conversación se oía a trompicones.

    Se deja un resto —12 ms delante, 35 detrás— porque quitarlo del todo corta
    la última consonante. La separación entre oraciones la pone la entonación,
    no el silencio: el sintetizador ya baja el tono al terminar la frase, y ese
    descenso es lo que el oído lee como punto final.
    """
    m = array.array("h")
    m.frombytes(pcm[:len(pcm) - (len(pcm) % 2)])
    if not len(m):
        return pcm
    umbral = 32768 * (10 ** (umbral_db / 20))
    ini, fin = 0, len(m) - 1
    while ini < len(m) and abs(m[ini]) < umbral:
        ini += 1
    while fin > ini and abs(m[fin]) < umbral:
        fin -= 1
    if ini >= fin:
        return pcm                      # todo silencio: no se toca
    resto_ini = max(0, ini - int(hz * cabeza_ms / 1000))
    resto_fin = min(len(m), fin + int(hz * cola_ms / 1000))
    return m[resto_ini:resto_fin].tobytes()


def _voz_medir(muestras) -> tuple:
    """RMS y pico en dBFS. Devuelve (-99, -99) para el silencio."""
    if not len(muestras):
        return -99.0, -99.0
    pico = max(abs(x) for x in muestras)
    suma = 0.0
    for x in muestras:
        suma += float(x) * x
    rms = math.sqrt(suma / len(muestras))
    def _db(v):
        return 20 * math.log10(v / 32768) if v > 0 else -99.0
    return _db(rms), _db(pico)


def _voz_nivelar(pcm: bytes) -> tuple:
    """Sube el audio a una sonoridad normal sin dejar que nada se recorte.

    Devuelve (pcm_nivelado, decibelios_aplicados). La ganancia es la MENOR de
    dos: la que hace falta para llegar al objetivo de sonoridad, y la que cabe
    antes de tocar el techo de picos. Así una frase con una sílaba fuerte no se
    distorsiona y una frase floja sí se levanta.
    """
    muestras = array.array("h")
    muestras.frombytes(pcm[:len(pcm) - (len(pcm) % 2)])
    rms, pico = _voz_medir(muestras)
    if rms <= -98:
        return pcm, 0.0
    ganancia = min(VOZ_RMS_OBJETIVO - rms, VOZ_PICO_TECHO - pico, VOZ_GANANCIA_MAX)
    if ganancia <= 0.5:
        return pcm, 0.0
    factor = 10 ** (ganancia / 20)
    techo = int(32767 * (10 ** (VOZ_PICO_TECHO / 20)))
    for i, v in enumerate(muestras):
        s = int(v * factor)
        muestras[i] = techo if s > techo else (-techo if s < -techo else s)
    return muestras.tobytes(), ganancia


def _voz_a_mp3(pcm: bytes, hz: int = VOZ_PCM_HZ) -> bytes:
    """PCM a MP3. Si el codificador no está, quien llama se las arregla.

    La frecuencia se pasa porque no todos hablan igual: ElevenLabs devuelve
    22.050 Hz y Azure 24.000. Codificar a la frecuencia equivocada no falla —
    suena más grave o más agudo, que es peor que fallar.
    """
    import lameenc
    e = lameenc.Encoder()
    e.set_bit_rate(VOZ_MP3_KBPS)
    e.set_in_sample_rate(hz)
    e.set_channels(1)
    e.set_quality(5)          # 0 es el mejor y el más lento; 5 es el término medio
    e.silence()
    return bytes(e.encode(pcm)) + bytes(e.flush())


# ── La voz de Liza ───────────────────────────────────────────────────────────
#
# El audio se sirve DESDE AQUÍ y no desde el teléfono, por una razón que no es
# negociable: la llave de ElevenLabs no puede viajar dentro de la app. Una app
# publicada es un archivo que cualquiera descarga y abre; una llave ahí dentro
# es una llave regalada, y se paga por carácter.
#
# Liza la eligió David de oído, entre diez candidatas diciendo la misma frase
# jurídica —con su número de artículo, sus siglas y la negativa a dictar una
# tesis sin verificar—. Ver la carpeta voces-abogado.
#
# El modelo era el flash —265 ms hasta el primer byte, frente a 591 ms del de
# más calidad—, y se eligió por esos 326 ms. El 24-ago-2026 David comparó las
# dos a ciegas sobre la misma frase jurídica y se quedó con la de calidad:
# «me gusta la 3». Manda el oído, que es quien usa esto en una audiencia.
#
# Lo que cuesta, dicho claro: +326 ms en cada respuesta y el DOBLE de crédito
# por carácter (el flash va a mitad de precio). Un turno pasa de 0,2757 a unos
# 0,53 MXN; un platinum que gaste sus diez preguntas todos los días del mes
# cuesta unos 159 MXN sobre un plan de 599. Sigue habiendo margen, pero ya no
# es el 86%. Si algún día aprieta, se vuelve al flash cambiando VOZ_ELEVEN_MODELO
# —sin tocar código— y la voz sigue siendo la misma.
VOZ_ELEVEN_ID = os.getenv("VOZ_ELEVEN_ID", "kl7d390GatBPfqhRTyAl")   # Liza
VOZ_ELEVEN_MODELO = os.getenv("VOZ_ELEVEN_MODELO", "eleven_multilingual_v2")


# ── Los números, para el oído ────────────────────────────────────────────────
#
# David lo oyó y lo dijo así: «los números los lee mal, sería mejor "con el
# registro que ve en pantalla"». Tiene razón por partida doble.
#
# El registro es un número de siete cifras. Dicho en voz alta no sirve para
# nada: nadie lo memoriza de oído, y en la pantalla ya está escrito, con su
# enlace al Semanario. Así que no se dicta: se remite a la pantalla, que es
# donde se puede leer, tocar y comprobar.
#
# Y los demás números —el artículo, el plazo, la cantidad— se convierten a
# letras antes de mandarlos al sintetizador. No es un capricho: el modelo de
# voz rápido (flash) no normaliza el texto, así que «2606» le llega tal cual y
# lo resuelve como puede. «Dos mil seiscientos seis» no admite interpretación.
# Se hace aquí, en el TTS, y no en la respuesta, porque en PANTALLA el número
# tiene que seguir siendo un número: se lee mejor y se copia.

_VOZ_UNIDADES = ("cero", "uno", "dos", "tres", "cuatro", "cinco", "seis", "siete", "ocho",
                 "nueve", "diez", "once", "doce", "trece", "catorce", "quince", "dieciséis",
                 "diecisiete", "dieciocho", "diecinueve", "veinte", "veintiuno", "veintidós",
                 "veintitrés", "veinticuatro", "veinticinco", "veintiséis", "veintisiete",
                 "veintiocho", "veintinueve")
_VOZ_DECENAS = ("", "", "", "treinta", "cuarenta", "cincuenta", "sesenta", "setenta",
                "ochenta", "noventa")
_VOZ_CENTENAS = ("", "ciento", "doscientos", "trescientos", "cuatrocientos", "quinientos",
                 "seiscientos", "setecientos", "ochocientos", "novecientos")


def _voz_centenas(n: int) -> str:
    """De 0 a 999, dicho como se dice."""
    if n < 30:
        return _VOZ_UNIDADES[n]
    if n < 100:
        d, u = divmod(n, 10)
        return _VOZ_DECENAS[d] + (f" y {_VOZ_UNIDADES[u]}" if u else "")
    if n == 100:
        return "cien"
    c, r = divmod(n, 100)
    return _VOZ_CENTENAS[c] + (f" {_voz_centenas(r)}" if r else "")


def _voz_en_letras(n: int) -> str:
    """Hasta los millones, que es todo lo que aparece en un juicio."""
    if n < 1000:
        return _voz_centenas(n)
    if n < 1_000_000:
        millares, resto = divmod(n, 1000)
        cabeza = "mil" if millares == 1 else f"{_voz_centenas(millares)} mil"
        return cabeza + (f" {_voz_centenas(resto)}" if resto else "")
    millones, resto = divmod(n, 1_000_000)
    cabeza = "un millón" if millones == 1 else f"{_voz_en_letras(millones)} millones"
    return cabeza + (f" {_voz_en_letras(resto)}" if resto else "")


# «con registro 2025216», «registro digital 190370», «registro número 165908».
# Se sustituye SÓLO desde la palabra «registro» hacia adelante, sin tocar lo
# que la precede: así «con registro 190370, permite…» queda «con registro que
# aparece en pantalla, permite…» y la frase conserva su costura.
_VOZ_REGISTRO_DICHO = _re_mod.compile(
    r"registro(?:\s+digital)?(?:\s+n[úu]mero)?\s*[:\s]\s*\d{5,8}", _re_mod.I)

_VOZ_CIFRA = _re_mod.compile(r"\d[\d.,]*")


def _voz_para_el_oido(texto: str) -> str:
    """Deja el texto listo para el sintetizador: sin registros y sin cifras."""
    if not texto:
        return texto
    salida = _VOZ_REGISTRO_DICHO.sub("registro que aparece en pantalla", texto)

    def _a_letras(m):
        crudo = m.group(0).rstrip(".,")
        entero, _, decimal = crudo.replace(",", "").partition(".")
        if not entero.isdigit():
            return m.group(0)
        # Más de siete cifras no es una cantidad, es un identificador: no se
        # dicta, se remite a la pantalla.
        if len(entero) > 7:
            return "el número que aparece en pantalla"
        dicho = _voz_en_letras(int(entero))
        if decimal and decimal.isdigit():
            dicho += f" punto {_voz_en_letras(int(decimal))}"
        return dicho + m.group(0)[len(crudo):]

    salida = _VOZ_CIFRA.sub(_a_letras, salida)
    # El símbolo tampoco se lee solo.
    salida = _re_mod.sub(r"\s*%", " por ciento", salida)
    return salida


# ── Las dos voces, y de quién son ────────────────────────────────────────────
#
# David las eligió de oído el 24-ago-2026, tras oír quince candidatas con la
# misma respuesta y todas igualadas de volumen: **Valeria** para la voz de
# mujer y **Jorge** para la de hombre. Y añadió lo que ninguna de las dos
# resuelve por separado: «que el usuario elija si quiere voz de hombre o de
# mujer». Tiene razón — un abogado escucha esto en un pasillo y el timbre es
# cuestión de gusto, no de producto.
#
# POR QUÉ SE DEJA ELEVENLABS: no se borra, se pone de reserva. Si Azure
# devuelve un error o tarda de más, el agente sigue hablando con Liza en vez de
# quedarse mudo. Una función de voz que enmudece no es una función degradada,
# es una función rota.
#
# LO QUE CAMBIA EN DINERO, con nuestro consumo medido de 855 caracteres por
# turno: de ~3,5 MXN por respuesta a ~0,24 con Jorge (15 USD/M, precio
# confirmado al SKU de Microsoft) y ~0,35 con Valeria. La voz deja de costar
# 350 veces lo que cuesta pensar la respuesta y pasa a costar unas 24.
#
# LO QUE HAY QUE VIGILAR: Valeria es de la familia MAI-Voice-2 y está en VISTA
# PREVIA —sin SLA, puede cambiar—. Por eso el reparto de voces vive en un mapa
# y no repartido por el código: el día que Microsoft la mueva, se cambia una
# línea. La suplente natural es `es-MX-DaliaNeural`, que es GA y puntuó 18.

AZURE_REGION = os.getenv("AZURE_SPEECH_REGION", "eastus")
AZURE_LLAVE = os.getenv("AZURE_SPEECH_KEY", "")

# El timbre que pidió cada quien → la voz y el estilo con que se le contesta.
# Jorge lleva `chat` porque es su único estilo conversacional y con él subió de
# 17 a 18 en el jurado; Valeria va NEUTRA, sin estilo, que es como gustó.
VOZ_AZURE = {
    "mujer":  ("es-MX-Valeria:MAI-Voice-2", None),
    "hombre": ("es-MX-JorgeNeural", "chat"),
}
VOZ_AZURE_POR_DEFECTO = os.getenv("VOZ_AZURE_DEFECTO", "mujer")


async def _voz_azure(texto: str, timbre: str) -> Optional[bytes]:
    """PCM crudo de Azure, listo para nivelar. None si algo va mal.

    Se pide PCM y no MP3 a propósito: el nivelado y la compresión son nuestros,
    iguales para todos los proveedores. Así una voz no suena más fuerte que
    otra por venir de otra casa —que es justo el fallo que trajo aquí—.
    """
    if not AZURE_LLAVE:
        return None
    voz, estilo = VOZ_AZURE.get(timbre) or VOZ_AZURE[VOZ_AZURE_POR_DEFECTO]
    # El texto va escapado: una respuesta jurídica trae comillas y ampersands,
    # y un SSML mal formado devuelve 400 con el agente en mitad de una frase.
    seguro = (texto.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))
    dentro = (f"<mstts:express-as style='{estilo}'>{seguro}</mstts:express-as>"
              if estilo else seguro)
    ssml = ("<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' "
            "xmlns:mstts='https://www.w3.org/2001/mstts' xml:lang='es-MX'>"
            f"<voice name='{voz}'>{dentro}</voice></speak>")
    try:
        async with httpx.AsyncClient(timeout=30.0) as cli:
            r = await cli.post(
                f"https://{AZURE_REGION}.tts.speech.microsoft.com/cognitiveservices/v1",
                content=ssml.encode("utf-8"),
                headers={"Ocp-Apim-Subscription-Key": AZURE_LLAVE,
                         "Content-Type": "application/ssml+xml",
                         "X-Microsoft-OutputFormat": "raw-24khz-16bit-mono-pcm",
                         "User-Agent": "iurexia-agente-ia"})
        if r.status_code != 200:
            print(f"   🔇 VOZ Azure {r.status_code}: {r.text[:160]}")
            return None
        return r.content
    except Exception as e:
        print(f"   🔇 VOZ Azure reventó: {err(e)}")
        return None


class VozHablarRequest(BaseModel):
    texto: str
    #: «mujer» o «hombre». Lo manda la app con lo que el abogado eligió en la
    #: pantalla; si no llega, se contesta con la voz por defecto.
    voz: Optional[str] = None


# ── Lo que se repite se guarda ───────────────────────────────────────────────
#
# El saludo de bienvenida es SIEMPRE el mismo texto y sólo hay dos voces. Pagar
# por sintetizarlo en cada apertura de la pantalla —y, peor, hacer esperar al
# abogado segundo y medio antes de oír nada— es tirar dinero y paciencia por
# algo que no cambia.
#
# Se guardan sólo las frases CORTAS: el saludo, los avisos, el «permítame
# buscarlo». Las respuestas jurídicas no se repiten nunca, así que cachearlas
# sólo llenaría la memoria del contenedor. Y el tope de entradas existe porque
# esto vive en un proceso que no se reinicia en semanas.
from collections import OrderedDict as _OrderedDict
_VOZ_CACHE: dict = _OrderedDict()
_VOZ_CACHE_MAX_CHARS = 220
_VOZ_CACHE_ENTRADAS = 40


def _voz_cache_leer(voz: str, texto: str) -> Optional[bytes]:
    if len(texto) > _VOZ_CACHE_MAX_CHARS:
        return None
    dato = _VOZ_CACHE.get(f"{voz}|{texto}")
    if dato is not None:
        _VOZ_CACHE.move_to_end(f"{voz}|{texto}")
    return dato


def _voz_cache_guardar(voz: str, texto: str, mp3: bytes) -> None:
    if len(texto) > _VOZ_CACHE_MAX_CHARS or not mp3:
        return
    _VOZ_CACHE[f"{voz}|{texto}"] = mp3
    while len(_VOZ_CACHE) > _VOZ_CACHE_ENTRADAS:
        _VOZ_CACHE.popitem(last=False)


@app.post("/api/voz/hablar")
async def abogado_ia_hablar(payload: VozHablarRequest, authorization: str = Header(None)):
    """Convierte a audio lo que el Abogado IA acaba de decir.

    Va en streaming para que el teléfono empiece a reproducir con el primer
    trozo en vez de esperar el archivo entero: es la diferencia entre responder
    y parecer que se quedó pensando.
    """
    texto = (payload.texto or "").strip()
    if not texto:
        raise HTTPException(status_code=400, detail="No llegó texto.")
    # Tope de seguridad: una respuesta hablada larga no existe, y cada carácter
    # se factura. Si llega algo enorme es un fallo aguas arriba, no una consulta.
    if len(texto) > 1200:
        texto = texto[:1200]
    # Lo que se dice NO es lo que se lee: en pantalla el registro es un número
    # con su enlace; por el altavoz es una ristra de siete cifras que nadie
    # retiene. Aquí se convierte para el oído, y sólo aquí.
    hablado = _voz_para_el_oido(texto)
    if hablado != texto:
        texto = hablado

    clave = os.getenv("ELEVENLABS_API_KEY")
    if not clave:
        raise HTTPException(status_code=503, detail="La voz no está configurada.")
    if not authorization or not supabase_admin:
        raise HTTPException(status_code=401, detail="Autenticación requerida")

    try:
        token = authorization.replace("Bearer ", "")
        user_resp = await asyncio.to_thread(supabase_admin.auth.get_user, token)
        user = user_resp.user
        if not user:
            raise HTTPException(status_code=401, detail="Token inválido")
        user_id, user_email = str(user.id), (user.email or "")
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=401, detail="Token inválido o expirado")

    if not _voz_permitida(user_email, user_id):
        raise HTTPException(status_code=403, detail="El Agente IA está en pruebas cerradas.")

    import httpx

    ajustes = {"stability": 0.45, "similarity_boost": 0.8,
               "style": 0.15, "use_speaker_boost": True}

    async def _pedir(formato: str) -> Optional[bytes]:
        url = (f"https://api.elevenlabs.io/v1/text-to-speech/{VOZ_ELEVEN_ID}"
               f"?output_format={formato}")
        try:
            async with httpx.AsyncClient(timeout=60.0) as cli:
                r = await cli.post(url, json={"text": texto, "model_id": VOZ_ELEVEN_MODELO,
                                              "voice_settings": ajustes},
                                   headers={"xi-api-key": clave})
            if r.status_code != 200:
                print(f"   🔇 VOZ TTS {r.status_code}: {r.text[:200]}")
                return None
            return r.content
        except Exception as e:
            print(f"   🔇 VOZ TTS reventó: {err(e)}")
            return None

    # ── Azure primero, ElevenLabs de reserva ─────────────────────────────
    #
    # Se pide PCM y no MP3 en los dos: el nivelado y la compresión son
    # nuestros e iguales para ambos, así una voz no suena más fuerte que otra
    # por venir de otra casa.
    t_voz = time.time()
    timbre = (payload.voz or "").strip().lower()
    if timbre not in VOZ_AZURE:
        timbre = VOZ_AZURE_POR_DEFECTO

    guardado = _voz_cache_leer(timbre, texto)
    if guardado is not None:
        print(f"   🔊 VOZ: {len(texto)} caracteres · {timbre} · DE CACHÉ · "
              f"{len(guardado)//1024} KB · {correo_opaco(user_email)}")
        return Response(content=guardado, media_type="audio/mpeg",
                        headers={"Cache-Control": "no-store"})
    crudo = await _voz_azure(texto, timbre)
    hz_crudo = 24000 if crudo else VOZ_PCM_HZ
    quien = f"Azure/{timbre}"
    if not crudo:
        if AZURE_LLAVE:
            print("   ⚠️ VOZ: Azure no respondió — se habla con la voz de reserva")
        crudo = await _pedir(f"pcm_{VOZ_PCM_HZ}")
        quien = "ElevenLabs/Liza"
    if crudo:
        try:
            crudo = await asyncio.to_thread(_voz_recortar_silencio, crudo, hz_crudo)
            nivelado, subida = await asyncio.to_thread(_voz_nivelar, crudo)
            mp3 = await asyncio.to_thread(_voz_a_mp3, nivelado, hz_crudo)
            _voz_cache_guardar(timbre, texto, mp3)
            print(f"   🔊 VOZ: {len(texto)} caracteres · {quien} · +{subida:.1f} dB · "
                  f"{len(mp3)//1024} KB · {(time.time()-t_voz)*1000:.0f} ms · "
                  f"{correo_opaco(user_email)}")
            return Response(content=mp3, media_type="audio/mpeg",
                            headers={"Cache-Control": "no-store"})
        except Exception as e:
            # Si el codificador falta o falla, NO se queda mudo el agente: se
            # sirve el MP3 de siempre, bajo de volumen pero audible.
            print(f"   ⚠️ VOZ: no pude nivelar ({err(e)}) — se sirve sin nivelar")

    mp3 = await _pedir("mp3_22050_32")
    if not mp3:
        raise HTTPException(status_code=502, detail="La voz no respondió.")
    print(f"   🔊 VOZ: {len(texto)} caracteres a Liza · SIN NIVELAR · {correo_opaco(user_email)}")
    return Response(content=mp3, media_type="audio/mpeg",
                    headers={"Cache-Control": "no-store"})


# ── Oír al abogado cuando el teléfono no sabe ────────────────────────────────
#
# El dictado lo hace el teléfono: en iPhone es el de Apple y es excelente, es
# gratis, es instantáneo y la voz no sale del aparato. Eso NO se toca.
#
# El problema es Android. Ahí el reconocimiento depende del fabricante y de que
# estén los servicios de Google: en un gama baja, o en un teléfono sin ellos,
# sencillamente no hay dictado y la app enseñaba «este dispositivo no permite
# dictado». Para un abogado en un pasillo eso es quedarse sin medio producto.
#
# Este endpoint es la red: recibe el audio y devuelve el texto. Se usa SÓLO
# cuando el teléfono no puede o falla, nunca por delante del suyo.
#
# POR QUÉ AZURE: ya está contratado para la voz, cuesta alrededor de un dólar
# por hora de audio —una pregunta de diez segundos son unos cinco centavos de
# peso— y entiende el vocabulario forense sin entrenarlo. Medido el 24-ago-2026
# con cinco preguntas jurídicas: cinco de cinco correctas, y en la de los
# artículos escribió «2606» donde el audio decía «dos mil seiscientos seis»,
# que es justo como lo quiere el buscador.
#
# Y POR QUÉ LA API DE TRANSCRIPCIÓN RÁPIDA Y NO LA DE AUDIO CORTO, que era lo
# primero que probé: porque acepta el formato que los teléfonos graban de
# verdad. El endpoint clásico quiere WAV o OGG-OPUS, y `expo-audio` en Android
# sólo sabe grabar AAC —no ofrece Opus—. Transcodificar en el servidor exigiría
# ffmpeg en el contenedor por una función de reserva. La rápida traga el m4a
# tal cual, tarda 668 ms en vez de 1.300, y el fichero pesa 17 KB en vez de 143,
# que en la red de un juzgado es la diferencia entre funcionar y no.
VOZ_OIDO_MAX_BYTES = 2 * 1024 * 1024      # un minuto largo de AAC; más es un fallo


@app.post("/api/voz/escuchar")
async def abogado_ia_escuchar(request: Request, authorization: str = Header(None)):
    """Convierte a texto lo que el abogado acaba de decir. Reserva de Android."""
    audio = await request.body()
    if not audio:
        raise HTTPException(status_code=400, detail="No llegó audio.")
    if len(audio) > VOZ_OIDO_MAX_BYTES:
        raise HTTPException(status_code=413, detail="El audio es demasiado largo.")
    if not AZURE_LLAVE:
        raise HTTPException(status_code=503, detail="El dictado de reserva no está configurado.")

    if not authorization or not supabase_admin:
        raise HTTPException(status_code=401, detail="Autenticación requerida")
    try:
        token = authorization.replace("Bearer ", "")
        user_resp = await asyncio.to_thread(supabase_admin.auth.get_user, token)
        user = user_resp.user
        if not user:
            raise HTTPException(status_code=401, detail="Token inválido")
        user_id, user_email = str(user.id), (user.email or "")
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=401, detail="Token inválido o expirado")

    if not _voz_permitida(user_email, user_id):
        raise HTTPException(status_code=403, detail="El Agente IA está en pruebas cerradas.")

    t0 = time.time()
    frontera = uuid.uuid4().hex
    cuerpo = b"".join([
        f"--{frontera}\r\nContent-Disposition: form-data; name=\"audio\"; "
        f"filename=\"pregunta.m4a\"\r\nContent-Type: application/octet-stream\r\n\r\n".encode(),
        audio,
        f"\r\n--{frontera}\r\nContent-Disposition: form-data; name=\"definition\"\r\n"
        f"Content-Type: application/json\r\n\r\n".encode(),
        json.dumps({"locales": ["es-MX"]}).encode(),
        f"\r\n--{frontera}--\r\n".encode(),
    ])
    try:
        async with httpx.AsyncClient(timeout=30.0) as cli:
            r = await cli.post(
                f"https://{AZURE_REGION}.api.cognitive.microsoft.com/speechtotext/"
                f"transcriptions:transcribe?api-version=2024-11-15",
                content=cuerpo,
                headers={"Ocp-Apim-Subscription-Key": AZURE_LLAVE,
                         "Content-Type": f"multipart/form-data; boundary={frontera}"})
        if r.status_code != 200:
            print(f"   👂 VOZ oído {r.status_code}: {r.text[:160]}")
            raise HTTPException(status_code=502, detail="No se pudo transcribir.")
        d = r.json()
    except HTTPException:
        raise
    except Exception as e:
        print(f"   👂 VOZ oído reventó: {err(e)}")
        raise HTTPException(status_code=502, detail="No se pudo transcribir.")

    texto = ((d.get("combinedPhrases") or [{}])[0].get("text") or "").strip()
    print(f"   👂 VOZ: {len(audio)//1024} KB · {len(texto)} caracteres · "
          f"{(time.time()-t0)*1000:.0f} ms · {correo_opaco(user_email)}")
    # Devolver cadena vacía NO es un error: el abogado pudo pulsar sin hablar, o
    # el pasillo estaba demasiado ruidoso. La app lo distingue y le pide que
    # repita, en vez de mandar una consulta en blanco al modelo.
    return {"texto": texto, "motivo": "" if texto else "no_entendido"}


# ── Admin: Toggle sentencia access for a user ────────────────────────────────
@app.post("/admin/users/{user_id}/toggle-sentencia")
async def admin_toggle_sentencia(user_id: str, authorization: str = Header(...)):
    """Toggle can_access_sentencia for a user (admin only)."""
    admin = await _verify_admin(authorization)

    try:
        # Get current value
        result = supabase_admin.table('user_profiles') \
            .select('can_access_sentencia, email') \
            .eq('id', user_id) \
            .limit(1) \
            .execute()

        if not result.data or len(result.data) == 0:
            raise HTTPException(404, "User not found")

        row = result.data[0]
        current = row.get('can_access_sentencia', False)
        user_email = row.get('email', 'unknown')
        new_value = not current

        supabase_admin.table('user_profiles') \
            .update({'can_access_sentencia': new_value}) \
            .eq('id', user_id) \
            .execute()

        action = "enable_sentencia" if new_value else "disable_sentencia"
        _log_admin_action(admin["email"], action, user_id, {"user_email": user_email})
        print(f"   🔄 Sentencia access for {correo_opaco(user_email)} ({user_id}): {current} → {new_value}")

        return {"success": True, "can_access_sentencia": new_value}
    except HTTPException:
        raise
    except Exception as e:
        print(f"❌ Toggle sentencia error: {err(e)}")
        raise HTTPException(status_code=500, detail=f"Error al cambiar acceso: {str(e)}")



