# GENIO JURÍDICO — Multi-Genio Cache Management Endpoints
# ══════════════════════════════════════════════════════════════════════════════

class GenioActivateRequest(BaseModel):
    genio_id: str = Field("amparo", description="ID del genio: 'amparo' o 'mercantil'")

class GenioKillRequest(BaseModel):
    genio_id: Optional[str] = Field(None, description="ID del genio a matar. None = todos.")

@app.post("/genio/activate")
async def activate_genio(request: GenioActivateRequest = GenioActivateRequest()):
    """Pre-create the context cache for a specific genio.

    Always returns the full status (including last_error) regardless of success/failure.
    Safe to call multiple times — SAFETY LOCKs prevent duplicate caches.
    """
    from cache_manager import get_or_create_cache, get_cache_status

    try:
        cache_name = await get_or_create_cache(request.genio_id)
        status = get_cache_status(request.genio_id)
        return {
            "success": cache_name is not None,
            "genio_id": request.genio_id,
            "cache_name": cache_name,
            **status
        }
    except Exception as e:
        from cache_manager import get_cache_status
        import traceback
        status = get_cache_status(request.genio_id)
        return {
            "success": False,
            "genio_id": request.genio_id,
            "cache_name": None,
            "error": str(e),
            "traceback": traceback.format_exc(),
            **status
        }


@app.get("/genio/status")
async def genio_status():
    """Return current cache status for all genios."""
    from cache_manager import get_cache_status
    return get_cache_status()  # No arg = all genios


@app.post("/genio/kill")
async def kill_genio(request: GenioKillRequest = GenioKillRequest()):
    """Kill switch — delete cache for one genio or ALL genios."""
    from cache_manager import delete_all_caches
    await delete_all_caches(request.genio_id)
    msg = f"Cache '{request.genio_id}' deleted" if request.genio_id else "All caches deleted"
    return {"success": True, "message": msg}


@app.get("/genio/debug")
async def debug_genio(genio_id: str = "amparo"):
    """Diagnostic endpoint — attempts cache creation for a genio."""
    from cache_manager import _create_cache, get_cache_status
    import traceback as tb

    result = {"attempted": True, "genio_id": genio_id}
    try:
        cache_name = await _create_cache(genio_id)
        status = get_cache_status(genio_id)
        result.update({
            "success": cache_name is not None,
            "cache_name": cache_name,
            **status,
        })
    except Exception as e:
        status = get_cache_status(genio_id)
        result.update({
            "success": False,
            "error": str(e),
            "error_type": type(e).__name__,
            "traceback": tb.format_exc(),
            **status,
        })
    return result



# ══════════════════════════════════════════════════════════════════════════════
# MOTOR DE FIRMA ELECTRÓNICA AVANZADA (E.FIRMA SAT / FIREL) — IN-HOUSE
# ══════════════════════════════════════════════════════════════════════════════
@app.post("/api/efirma/validar")
async def api_efirma_validar(
    cer_file: UploadFile = File(...),
    key_file: UploadFile = File(...),
    password: str = Form(...),
):
    """
    Comprueba las credenciales sin firmar nada: que el certificado esté vigente,
    que la contraseña abra el .key y que ambos archivos sean del mismo trámite.

    Sirve para que la app confirme la e.firma al darla de alta y pueda mostrar el
    nombre y RFC del titular antes de que firme ningún documento.
    """
    from efirma_service import ErrorEfirma, validar_par_credenciales

    cer_bytes = await cer_file.read()
    key_bytes = await key_file.read()

    if not cer_bytes or not key_bytes:
        raise HTTPException(status_code=400, detail="Los archivos .cer y .key no pueden estar vacíos.")

    try:
        info = await asyncio.to_thread(validar_par_credenciales, cer_bytes, key_bytes, password)
        return {"success": True, **info}
    except ErrorEfirma as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        # Nunca incluir la contraseña ni la llave en el mensaje ni en el log.
        print(f"⚠️ e.firma validar: fallo inesperado ({type(e).__name__})")
        raise HTTPException(status_code=500, detail="No se pudieron validar las credenciales.")


@app.post("/api/efirma/sign")
async def api_efirma_sign(
    cer_file: UploadFile = File(...),
    key_file: UploadFile = File(...),
    password: str = Form(...),
    pdf_file: UploadFile = File(...),
    razon: str = Form("Firma electrónica avanzada del titular"),
    lugar: str = Form("México"),
):
    """
    Firma un PDF con la e.firma (SAT) o FIREL del titular y **devuelve el PDF
    firmado**, no el original.

    Devuelve el archivo binario directamente (application/pdf) para que la app
    lo pueda guardar o compartir tal cual. Los datos de la firma van en
    cabeceras `X-Firma-*`, porque el cuerpo es el propio PDF.

    Ojo con el historial de este endpoint: antes respondía `success: true` y
    devolvía metadatos aunque el PDF nunca se firmara. Ahora, si la firma no se
    incrusta, esto falla con error — no existe forma de recibir un archivo sin
    firmar creyendo que la lleva.
    """
    from efirma_service import ErrorEfirma, firmar_pdf_efirma

    cer_bytes = await cer_file.read()
    key_bytes = await key_file.read()
    pdf_bytes = await pdf_file.read()

    if not cer_bytes or not key_bytes:
        raise HTTPException(status_code=400, detail="Los archivos .cer y .key no pueden estar vacíos.")
    if not pdf_bytes:
        raise HTTPException(status_code=400, detail="No se recibió el PDF a firmar.")

    try:
        pdf_firmado, metadatos = await asyncio.to_thread(
            firmar_pdf_efirma, pdf_bytes, cer_bytes, key_bytes, password, razon, lugar
        )
    except ErrorEfirma as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        print(f"⚠️ e.firma sign: fallo inesperado ({type(e).__name__})")
        raise HTTPException(status_code=500, detail="No se pudo firmar el documento.")

    from fastapi.responses import Response

    nombre_salida = (pdf_file.filename or "documento.pdf").rsplit(".", 1)[0]
    return Response(
        content=pdf_firmado,
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'attachment; filename="{nombre_salida}-firmado.pdf"',
            "X-Firma-Firmante": metadatos["firmante"],
            "X-Firma-RFC": metadatos["rfc"],
            "X-Firma-Serie": metadatos["numero_serie"],
            "X-Firma-Fecha": metadatos["fecha_firma"],
            "X-Firma-Hash": metadatos["hash_documento_firmado"],
            # Que la app pueda leer estas cabeceras desde el navegador (web).
            "Access-Control-Expose-Headers": (
                "X-Firma-Firmante, X-Firma-RFC, X-Firma-Serie, X-Firma-Fecha, X-Firma-Hash"
            ),
        },
    )


# ═══════════════════════════════════════════════════════════════════════════════
# SUSCRIPCIONES DE APPLE (StoreKit) — compras dentro de la app de iPhone
# ═══════════════════════════════════════════════════════════════════════════════
#
# El "cómo" y el "por qué" de la verificación están en apple_iap.py. Aquí sólo
# viven los dos endpoints HTTP y la escritura del perfil.

class VerificarCompraAppleRequest(BaseModel):
    purchase_token: str
    #: 'ios' → StoreKit; 'android' → Google Play. Decide con qué tienda se verifica.
    plataforma: str = "ios"
    #: Sólo Android lo usa, y es opcional: la API v2 de Play ya dice qué se compró.
    product_id: Optional[str] = None


def _escribir_plan(user_id: str, plan: str, origen: dict) -> None:
    """
    Deja el plan del usuario en `user_profiles`, el mismo campo que actualiza el
    webhook de Stripe. Es la única fuente de verdad: ni la app ni la web deciden.
    """
    if not supabase_admin:
        raise HTTPException(status_code=503, detail="Supabase no está configurado")

    supabase_admin.table("user_profiles").update(
        {"subscription_type": plan}
    ).eq("id", user_id).execute()

    print(f"🍎 Apple → user={user_id} plan={plan} {origen}")


@app.post("/api/apple/verificar-compra")
async def verificar_compra_apple(
    payload: VerificarCompraAppleRequest,
    authorization: str = Header(None),
):
    """
    Activa el plan tras una compra hecha con StoreKit en el iPhone.

    La app manda el JWS que le devolvió Apple; aquí se comprueba la firma contra
    el certificado raíz de Apple y, si todo cuadra, se escribe el plan. La app
    sólo cierra la transacción con StoreKit cuando esto responde 200 — por eso un
    fallo aquí no le cuesta el plan a nadie: StoreKit reintenta al reabrir.
    """
    import asyncio
    import apple_iap

    if not supabase_admin:
        raise HTTPException(status_code=503, detail="Servicio temporalmente no disponible")
    if not authorization:
        raise HTTPException(status_code=401, detail="Autenticación requerida")

    # 1) ¿Quién es? (el token de Supabase manda, no lo que diga el cuerpo)
    try:
        token = authorization.replace("Bearer ", "")
        user_resp = await asyncio.to_thread(supabase_admin.auth.get_user, token)
        user = user_resp.user
        if not user:
            raise HTTPException(status_code=401, detail="Token inválido")
        user_id = str(user.id)
    except HTTPException:
        raise
    except Exception as e:
        print(f"⚠️ Apple verificar-compra, auth falló: {err(e)}")
        raise HTTPException(status_code=401, detail="Token inválido o expirado")

    # 2) ¿El comprobante es de la tienda que dice, de esta app, y de un
    #    producto nuestro? Cada tienda se comprueba a su manera: el de Apple es
    #    un JWS que trae su propia firma, y el de Google es un token opaco que
    #    hay que ir a consultarle a la Play Developer API.
    es_android = (payload.plataforma or "ios").lower() in ("android", "play", "google")
    tienda = "Google Play" if es_android else "Apple"

    try:
        if es_android:
            import google_play
            compra = await asyncio.to_thread(
                google_play.verificar_compra, payload.purchase_token, payload.product_id
            )
        else:
            compra = await asyncio.to_thread(
                apple_iap.verificar_transaccion, payload.purchase_token
            )
    except apple_iap.CompraInvalida as e:
        # 422 y no 500: el comprobante llegó, pero no es válido. Que la app no
        # lo reintente en bucle.
        raise HTTPException(status_code=422, detail=str(e))
    except Exception as e:
        # Las de Google se importan aquí para no exigir el módulo si no se usa.
        import google_play as _gp
        if isinstance(e, _gp.CompraInvalida):
            raise HTTPException(status_code=422, detail=str(e))
        if isinstance(e, _gp.PlayNoConfigurado):
            # 503 y no 422: la compra puede ser perfectamente buena, lo que
            # falla es nuestra configuración. Con un 5xx la app NO cierra la
            # transacción y Play la vuelve a entregar cuando esto se arregle.
            print(f"⚠️ Play sin configurar: {err(e)}")
            raise HTTPException(
                status_code=503,
                detail="La verificación con Google Play no está disponible todavía.",
            )
        print(f"⚠️ verificar-compra ({tienda}) reventó: {err(e)}")
        raise HTTPException(status_code=500, detail=f"No se pudo verificar la compra con {tienda}")

    # 3) Compras ya reembolsadas o retiradas no dan plan.
    if compra.revocada:
        raise HTTPException(status_code=422, detail="Esta compra fue reembolsada o revocada.")

    # 4) Si la app mandó el `appAccountToken`, tiene que ser de quien pide.
    #    Evita que alguien reutilice el comprobante de otra persona para
    #    activarse el plan en su propia cuenta.
    if compra.app_account_token and compra.app_account_token.lower() != user_id.lower():
        print(
            f"🚨 Apple: comprobante de otra cuenta. token={compra.app_account_token} user={user_id}"
        )
        raise HTTPException(
            status_code=403, detail="Esta compra pertenece a otra cuenta de Iurexia."
        )

    # 5) Ya se puede conceder.
    await asyncio.to_thread(
        _escribir_plan,
        user_id,
        compra.plan,
        {"tx": compra.transaction_id, "producto": compra.product_id, "env": compra.entorno, "tienda": tienda},
    )

    return {
        "success": True,
        "subscription_type": compra.plan,
        "product_id": compra.product_id,
        "expira_ms": compra.expira_ms,
        "entorno": compra.entorno,
    }


@app.post("/api/apple/notificaciones")
async def notificaciones_apple(request: Request):
    """
    App Store Server Notifications V2 — Apple avisa aquí de renovaciones,
    cancelaciones, reembolsos y expiraciones.

    Sin esto, alguien que cancela o pide reembolso seguiría figurando como
    suscriptor. Se responde 200 en cuanto la notificación es auténtica, aunque
    después no se pueda aplicar: si devolviéramos error, Apple reintentaría el
    mismo aviso durante días.
    """
    import asyncio
    import apple_iap

    # Cuerpo ilegible: se rechaza con 400, no con 500. La diferencia importa —
    # ante un 5xx Apple entiende «falla pasajera» y reintenta el mismo aviso
    # durante días; ante un 400 entiende que ese aviso no va a poder procesarse
    # nunca y lo deja de mandar.
    try:
        cuerpo = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Cuerpo no es JSON válido")

    firmado = (cuerpo or {}).get("signedPayload")
    if not firmado:
        raise HTTPException(status_code=400, detail="Falta signedPayload")

    try:
        aviso = await asyncio.to_thread(apple_iap.verificar_notificacion, firmado)
    except apple_iap.CompraInvalida as e:
        # Aquí sí conviene rechazar: si la firma no es de Apple, no es de Apple.
        print(f"🚨 Apple notificación no verificable: {err(e)}")
        raise HTTPException(status_code=400, detail="Notificación no verificable")

    tipo = str(aviso.rawNotificationType or "")
    subtipo = str(aviso.rawSubtype or "")
    print(f"🍎 Apple aviso: {tipo}/{subtipo or '—'} uuid={aviso.notificationUUID}")

    # El aviso de prueba que se dispara desde App Store Connect no trae compra.
    if tipo == "TEST":
        return {"ok": True, "tipo": tipo}

    datos = aviso.data
    if not datos or not datos.signedTransactionInfo:
        return {"ok": True, "tipo": tipo, "nota": "sin transacción"}

    try:
        compra = await asyncio.to_thread(
            apple_iap.verificar_transaccion, datos.signedTransactionInfo
        )
    except apple_iap.CompraInvalida as e:
        print(f"⚠️ Apple aviso {tipo}: transacción no aplicable ({err(e)})")
        return {"ok": True, "tipo": tipo, "nota": "transacción no aplicable"}

    # ¿De quién es esta suscripción? El `appAccountToken` es el id de Supabase
    # que la app mandó al comprar.
    user_id = compra.app_account_token
    if not user_id:
        print(f"⚠️ Apple aviso {tipo}: sin appAccountToken, no se sabe a quién aplicar")
        return {"ok": True, "tipo": tipo, "nota": "sin cuenta asociada"}

    if tipo in apple_iap.NOTIFICACIONES_QUE_QUITAN_PLAN:
        nuevo_plan = "gratuito"
    elif tipo in apple_iap.NOTIFICACIONES_QUE_DAN_PLAN:
        nuevo_plan = compra.plan
    else:
        # Informativos (incluye apagar la renovación automática, que NO quita el
        # plan: lo conserva hasta que expire y entonces llega EXPIRED).
        return {"ok": True, "tipo": tipo, "nota": "informativo"}

    try:
        await asyncio.to_thread(
            _escribir_plan, user_id, nuevo_plan, {"aviso": tipo, "subtipo": subtipo}
        )
    except Exception as e:
        # 200 igual: reintentar no arreglaría un fallo de nuestra base, y Apple
        # insistiría durante días con el mismo aviso.
        print(f"⚠️ Apple aviso {tipo}: no se pudo escribir el perfil: {err(e)}")

    return {"ok": True, "tipo": tipo, "plan": nuevo_plan}


# ═══════════════════════════════════════════════════════════════════════════
# TALLER DE SENTENCIAS — el adelanto completo desde dos documentos
# ═══════════════════════════════════════════════════════════════════════════
#
# El circuito vive en `redactor_adelanto.py` y aquí sólo se expone. Se importa
# DENTRO del endpoint a propósito: si falta `python-docx` o la plantilla, que
# falle esta ruta y no el arranque del servidor entero.

@app.get("/taller/tipos")
async def taller_tipos():
    """El catálogo de asuntos, para que el formulario se construya desde él.

    David: «lo primero sería preguntarle al usuario qué tipo de asunto va a
    proyectar; una vez que seleccione, desplegar los campos que lleva cada
    asunto».

    Esto es lo que lo hace posible: la pantalla no necesita saber nada de
    derecho —ni qué plazo tiene una queja, ni que una revisión fiscal no lleva
    «existencia del acto reclamado»—. Lo pregunta aquí y lo pinta.

    Y el plazo NO es un campo que el secretario deba teclear: lo dice la ley y
    depende del tipo. Lo que sí se le pregunta son las excepciones, porque ésas
    no se deducen del expediente: si la queja es contra una suspensión de plano
    son dos días, y si se omitió tramitar la demanda no hay plazo.
    """
    import tipos_asunto as _ta
    fuera = []
    for clave in _ta.TIPOS:
        v = _ta.vocabulario_de(clave)
        p = _ta.plazo_de(clave)
        est = _ta.estructura_de(clave)
        fuera.append({
            "clave": clave,
            "nombre": v["nombre"],
            "promovente": v["promovente"],       # «quejoso» o «recurrente»
            "combate": v["combate"],             # «conceptos de violación» o «agravios»
            "recurrido": v["recurrido"],
            "escrito": v["escrito"],             # lo que el secretario sube
            "plazo": {"dias": p["dias"], "fundamento": p["fundamento"]},
            "excepciones_de_plazo": [
                {"clave": e["clave"], "cuando": e["cuando"],
                 "dias": e["dias"], "fundamento": e["fundamento"],
                 "en_cualquier_tiempo": e["dias"] is None}
                for e in _ta.excepciones_de(clave)],
            # Para que la pantalla pueda decirle qué va a recibir.
            "apartados": {
                "resultandos": [n for n, _ in est["resultandos"]],
                "considerandos": [n for n, _ in est["considerandos"]],
            },
            "medido_sobre": est["muestra"],
        })
    return {"tipos": fuera,
            "nota": ("La estructura de cada tipo está contada sobre adelantos "
                     "reales del corpus; el plazo sale de la ley, con su "
                     "artículo. Ninguno de los dos se teclea.")}


@app.get("/admin/uso-colecciones")
async def admin_uso_colecciones(user_email: str = ""):
    """Qué colecciones se han tocado desde el último reinicio.

    Sirve para decidir un borrado CON DATOS y no con un grep. Lo que salga en
    cero tras una semana de tráfico normal es candidato; lo que no aparezca
    tampoco se ha tocado. Con dos workers cada proceso lleva su cuenta, así que
    conviene pedirlo varias veces.
    """
    if user_email and ADMIN_EMAILS and user_email.lower() not in ADMIN_EMAILS:
        raise HTTPException(403, "Sólo para administración.")
    import uso_colecciones as _uso
    return _uso.informe()


@app.post("/taller/adelanto")
async def taller_adelanto(
    numero: str = Form(...),
    encabezado: str = Form(...),
    quejoso: str = Form(...),
    magistrado: str = Form(...),
    secretario: str = Form(...),
    notificacion: str = Form(...),           # ISO: 2026-05-11
    presentacion: str = Form(...),
    user_email: str = Form(...),
    # NOTIFICACIÓN PERSONAL POR OMISIÓN — artículo 31, fracción I, de la Ley
    # de Amparo, que vale en toda la república. Antes la omisión era la regla
    # del Boletín Jurisdiccional del tribunal administrativo de Querétaro y se
    # aplicaba, en silencio, al cómputo de un secretario de cualquier estado.
    regla_surtimiento: str = Form("personal"),
    # EL PLAZO NO SE TECLEA: LO DICE LA LEY Y DEPENDE DEL TIPO. Era 15 por
    # omisión para todo, y una QUEJA tiene CINCO días (artículo 98 de la Ley de
    # Amparo) y una REVISIÓN diez (artículo 86). Se contaba con el triple del
    # plazo que corresponde y nadie avisaba. Ahora 0 significa «el de la ley», y
    # sólo se acepta un valor si el secretario lo declara a propósito.
    plazo: int = Form(0),
    # Y LO QUE SÍ HAY QUE PREGUNTARLE, porque no se deduce del expediente: si el
    # asunto cae en una excepción de plazo. En la queja, la suspensión de plano
    # o provisional son DOS días y la omisión de tramitar la demanda no tiene
    # plazo; en el amparo, la norma autoaplicativa son treinta días.
    excepcion_plazo: str = Form(""),
    # LA AUTORIDAD SE LEE DEL ACTO. Exigirla al secretario era la solución
    # equivocada al problema correcto: el dato está en la sentencia reclamada
    # que él ya subió y que ya pasa por OCR. Se acepta si la escribe —manda lo
    # que él diga— y si no, se lee. Sólo cuando no se puede leer se avisa.
    responsable: Optional[str] = Form(None),
    es_recurso: bool = Form(False),
    tipo_asunto: str = Form("amparo_directo"),
    # EL TRIBUNAL VIENE DEL SECRETARIO, NO DEL CÓDIGO. Con `modo=generado` el
    # documento se escribe entero con estos datos y no hereda la identidad de
    # ninguna plantilla ajena: es lo que permite usar esto fuera de un circuito.
    tribunal: str = Form(""),
    ciudad: str = Form(""),
    # EL MODO POR OMISIÓN ES «GENERADO», Y ESTO ERA UN AGUJERO DE FIRMA AJENA.
    # Con «plantilla», si el secretario no sube la suya, se le copiaba una de
    # las cuatro precargadas… que son ENGROSES REALES del Tercer Tribunal
    # Colegiado del Vigésimo Segundo Circuito, con «Querétaro, Querétaro» en el
    # proemio y el nombre propio de sus magistrados en el resultando del turno.
    # Un secretario de Mérida recibía un documento que declaraba competente a un
    # tribunal de Querétaro y turnaba el asunto a un magistrado que no es el
    # suyo. El frontend manda «generado», pero el contrato HTTP caía aquí, y la
    # app móvil o cualquier integración que omita el campo caían con él.
    modo: str = Form("generado"),                   # plantilla | generado
    plantilla: Optional[UploadFile] = File(None),   # opcional: hay precargadas
    acto: UploadFile = File(...),
    conceptos: UploadFile = File(...),
    # EL TERCER DOCUMENTO, Y NO ES UN EXTRA. En el ADL 382/2024 el motor propuso
    # infundado diciendo textualmente «falta el texto de las cláusulas 40 y 83»
    # del contrato colectivo. Ese texto estaba —la cláusula 40 se llama «Faltas
    # Justificadas con Posterioridad», que es el corazón del asunto— en un PDF
    # de constancias que el secretario había subido y que este endpoint no
    # leía: sólo aceptaba el acto y los conceptos. El motor razonó bien con lo
    # que tenía; lo que le faltaba era el expediente.
    #
    # Un contrato colectivo, un reglamento interior o un peritaje no están en
    # ningún acervo público y no pueden estarlo: son del expediente. Si no
    # entran por aquí, no entran.
    constancias: Optional[UploadFile] = File(None),
):
    """Genera el adelanto y lo devuelve como .docx.

    LA VÍA Y EL PLAZO LLEGAN COMO CAMPOS, no se adivinan. Está medido: al
    inferir la vía por palabra clave, el cómputo se iba ±1 día en la mitad de
    los casos, y un plazo mal contado invalida la sentencia. Los confirma el
    secretario, que los tiene delante.
    """
    import datetime as _dtm
    import tempfile

    _taller_puerta(user_email)

    import redactor_adelanto as _ra
    import tipos_asunto as _ta

    tmp = tempfile.mkdtemp(prefix="taller_")
    ruta_plantilla = f"{tmp}/plantilla.docx"

    # LA PLANTILLA YA NO SE PIDE. Está precargada por familia de asunto, y el
    # secretario sólo la sube si quiere usar una suya. Pedírsela era además la
    # causa de un defecto real: en el proyecto 360/2025 se subió un adelanto
    # —que por definición se detiene ANTES del resolutivo— y la sentencia salió
    # sin «Por lo expuesto», sin RESUELVE y sin puntos resolutivos. Las
    # precargadas son proyectos terminados: traen la estructura completa.
    if plantilla is not None and getattr(plantilla, "filename", ""):
        with open(ruta_plantilla, "wb") as fh:
            fh.write(await plantilla.read())
    elif modo.lower() == "generado":
        # No hay plantilla que copiar: el documento se escribe entero.
        ruta_plantilla = ""
        print(f"   📄 TALLER: modo GENERADO — sin plantilla · tribunal "
              f"«{(tribunal or 'SIN INDICAR')[:70]}»")
    else:
        # ═══════════════════════════════════════════════════════════════
        # LAS PLANTILLAS PRECARGADAS DEJAN DE SERVIRSE
        # ═══════════════════════════════════════════════════════════════
        # Los cuatro .docx de `plantillas/` no son formularios: son ENGROSES
        # REALES del Tercer Tribunal Colegiado del Vigésimo Segundo Circuito,
        # con «Querétaro, Querétaro» en el proemio, el nombre propio de sus
        # magistrados en el resultando del turno y su competencia en el
        # considerando primero. Y `ensamblar()` no sustituye ni el tribunal ni
        # la ciudad —`Relleno` ni siquiera tiene esos campos— y el magistrado
        # sólo lo cambia en la línea de rubro, no donde la plantilla lo nombra
        # en prosa. Un secretario de Mérida recibía un documento que declaraba
        # competente a un tribunal de Querétaro y turnaba el asunto a un
        # magistrado que no es el suyo, con el rubro corregido dando la
        # impresión de que la sustitución se había hecho.
        #
        # David: «no dejes plantillas o datos del Tercer Tribunal Colegiado.
        # Todo tiene que ser generado con los campos que va llenando el
        # secretario». Así que esta rama se cierra: o el secretario sube SU
        # plantilla, o el documento se escribe entero con sus datos.
        #
        # Los cuatro ficheros no se borran: siguen siendo el corpus del que se
        # midieron las fórmulas de `banco_plantillas.json`. Lo que se retira es
        # servirlos como documento.
        raise HTTPException(400,
            "El modo «plantilla» sólo vale con la plantilla que tú subas. Las "
            "que había precargadas eran engroses de un tribunal concreto —con "
            "su ciudad y sus magistrados dentro— y servírselas a un secretario "
            "de otro circuito le ponía en el documento una identidad que no es "
            "la suya. Sube la tuya, o usa el modo «generado», que escribe el "
            "proyecto entero con los datos de tu ficha.")

    # Se reutiliza el lector que ya existe: texto nativo gratis, OCR sólo si
    # el PDF viene escaneado.
    # LOS DOS DOCUMENTOS SE LEEN A LA VEZ. Son independientes y el OCR es lo
    # más lento del adelanto: en el ADC 380/2025, ochenta y cuatro páginas de
    # sentencia y treinta y ocho de demanda, uno detrás de otro. Ponerlos en
    # paralelo no cambia una coma del resultado y devuelve la mitad del tiempo.
    import time as _t_ocr
    _t0_ocr = _t_ocr.perf_counter()
    texto_acto, texto_conceptos, texto_autos = await asyncio.gather(
        _extract_text_from_upload(acto),
        _extract_text_from_upload(conceptos),
        (_extract_text_from_upload(constancias)
         if constancias is not None and getattr(constancias, "filename", "")
         else asyncio.sleep(0, result="")))
    print(f"   ⏱️  OCR de los dos documentos: "
          f"{_t_ocr.perf_counter() - _t0_ocr:.1f}s")
    # PARADA DURA. Antes bastaba con 200 caracteres y el redactor escribió un
    # proyecto de 4,133 palabras que empezaba diciendo «no fue posible
    # identificar una sentencia reclamada en el texto proporcionado». Un
    # documento plausible construido sobre nada es peor que un error: el error
    # se ve, y ese texto se firma.
    for etiqueta, txt in (("acto reclamado", texto_acto),
                          ("escrito de conceptos", texto_conceptos)):
        pal = re.findall(r"[A-Za-zÁÉÍÓÚÑáéíóúñ]{3,}", txt or "")
        unicas = {w.lower() for w in pal}
        if len(pal) < 200 or (pal and len(unicas) / len(pal) < 0.12):
            raise HTTPException(400,
                f"No se pudo leer el {etiqueta}: sólo se obtuvieron "
                f"{len(unicas)} palabras distintas en {len(pal)}. El PDF puede "
                f"venir escaneado sin capa de texto útil, o traer únicamente los "
                f"sellos de firma. Vuelve a subirlo o pásalo antes por un OCR: "
                f"NO se genera un proyecto sobre un documento que no se leyó.")

    encargo = _ra.Encargo(
        numero=numero, encabezado=encabezado, quejoso=quejoso,
        magistrado=magistrado, secretario=secretario,
        notificacion=_dtm.date.fromisoformat(notificacion),
        presentacion=_dtm.date.fromisoformat(presentacion),
        regla_surtimiento=regla_surtimiento,
        plazo=plazo or _ta.plazo_de(tipo_asunto, excepcion_plazo)["dias"] or 0,
        excepcion_plazo=excepcion_plazo,
        responsable=responsable, es_recurso=es_recurso,
        tribunal=tribunal, ciudad=ciudad, modo=modo,
        tipo_asunto=tipo_asunto,
        plantilla=ruta_plantilla,
    )
    salida = f"{tmp}/{numero.replace('/', '-')} ADELANTO.docx"
    r = await _ra.generar(chat_client, encargo, texto_acto, texto_conceptos,
                          salida, texto_autos)

    _taller_registrar_uso(user_email, numero, "adelanto")
    _taller_guardar_sesion(user_email, numero, r, tmp)

    print(f"   ⚖️ TALLER: adelanto {numero} · "
          f"{len(r.fases.problemas)} problemas · {len(r.huecos)} huecos")

    from fastapi.responses import FileResponse
    return FileResponse(
        r.ruta,
        media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        filename=salida.split("/")[-1],
        headers={
            # Lo que el secretario tiene que leer ANTES de abrir el documento.
            "X-Oportunidad": "en-tiempo" if r.computo.oportuna else "EXTEMPORANEA",
            "X-Problemas": str(len(r.fases.problemas)),
            "X-Huecos": str(len(r.huecos)),
            "X-Avisos": str(len(r.avisos)),
            "X-Piloto-Secretarios": str(_taller_secretarios_distintos()),
            "X-Piloto-Cupo": str(TALLER_PILOTO_CUPO),
        },
    )


# ═══════════════════════════════════════════════════════════════════════════
# La segunda mitad: el criterio del secretario entra AQUÍ
# ═══════════════════════════════════════════════════════════════════════════
#
# El proceso se parte en dos porque entre las dos mitades hay una PERSONA. La
# máquina lee y ordena; él decide; la máquina redacta la demostración. El
# adelanto queda en memoria entre una llamada y la otra: rehacer los resúmenes
# para resolver costaría otra vez el modelo y otra vez la espera.
# EL ADELANTO NO PUEDE VIVIR EN MEMORIA. Render levanta varios workers de
# gunicorn y cada petición cae en el que toque. Medido en producción: el
# adelanto se guardó en el worker A, /consultar cayó en A por suerte y funcionó,
# y /resolver cayó en B y contestó «no hay un adelanto reciente» sobre un
# expediente que acababa de generarse. Un diccionario de proceso funciona en la
# máquina de uno y falla en cuanto hay dos workers.
_TALLER_SESIONES: dict = {}          # caché del proceso, sobre la persistencia
_TALLER_SESION_TTL = 3600.0


def _taller_llave(email: str, numero: str) -> str:
    return f"{(email or '').strip().lower()}|{numero}"


def _taller_purgar() -> None:
    ahora = time.time()
    for k in [k for k, v in _TALLER_SESIONES.items()
              if ahora - v.get("ts", 0) > _TALLER_SESION_TTL]:
        _TALLER_SESIONES.pop(k, None)


def _taller_guardar_sesion(email: str, numero: str, r, tmp: str) -> None:
    """Lo serializable del adelanto, para que otro worker pueda continuarlo."""
    _TALLER_SESIONES[_taller_llave(email, numero)] = {
        "resultado": r, "tmp": tmp, "ts": time.time()}
    if not supabase_admin:
        return
    e = r.encargo
    estado = {
        "encargo": {
            "numero": e.numero, "encabezado": e.encabezado, "quejoso": e.quejoso,
            "magistrado": e.magistrado, "secretario": e.secretario,
            "notificacion": e.notificacion.isoformat(),
            "presentacion": e.presentacion.isoformat(),
            "regla_surtimiento": e.regla_surtimiento, "plazo": e.plazo,
            "responsable": e.responsable, "es_recurso": e.es_recurso,
            "plantilla": e.plantilla, "coleccion_estatal": e.coleccion_estatal,
            # Sin esto, el /taller/resolver que caiga en el otro worker
            # reconstruye el encargo en modo plantilla y el documento sale con
            # la identidad de un tribunal que no es el suyo.
            "tribunal": getattr(e, "tribunal", ""), "ciudad": getattr(e, "ciudad", ""),
            "modo": getattr(e, "modo", "plantilla"),
            "tipo_asunto": getattr(e, "tipo_asunto", "amparo_directo"),
        },
        "fases": {
            "antecedentes": r.fases.antecedentes,
            "resumen_acto": r.fases.resumen_acto,
            "resumen_conceptos": r.fases.resumen_conceptos,
            "problema_global": r.fases.problema_global,
            "problemas": r.fases.problemas,
            "avisos": list(r.fases.avisos or []),
            # Las constancias viajan con la sesión: el /taller/proponer que
            # caiga en el otro worker las necesita tanto como éste.
            "autos": getattr(r.fases, "autos", "") or "",
        },
        "partes": (r.partes.__dict__ if r.partes else None),
        "computo": {"oportuna": r.computo.oportuna,
                    "parrafo": __import__("fase0_oportunidad").parrafo_oportunidad(r.computo)},
        "avisos": list(r.avisos or []),
        "tmp": tmp,
    }
    # LA PLANTILLA VIAJA CON LA SESIÓN. Vive en el /tmp del worker que atendió el
    # adelanto y el que resuelve no lo ve: `PackageNotFoundError` al reensamblar.
    # Son unos 450 KB por asunto en curso, y se borran con la sesión.
    fila = {"email": (email or "").strip().lower(), "expediente": numero,
            "estado": estado, "consultado": False}
    # En modo `generado` NO HAY PLANTILLA que viajar: el documento se escribe
    # entero. Intentar abrir la ruta vacía reventaba el adelanto entero —y el
    # `logger` de este manejador no existe en este módulo, así que el
    # FileNotFoundError salía disfrazado de NameError y no se veía la causa—.
    if e.plantilla:
        try:
            with open(e.plantilla, "rb") as _fh:
                fila["plantilla"] = "\\x" + _fh.read().hex()
        except Exception as ex:
            print(f"   ⚠️ TALLER: no se pudo guardar la plantilla: {ex}")
    try:
        supabase_admin.table("taller_sesiones").upsert(
            fila, on_conflict="email,expediente").execute()
    except Exception as ex:
        print(f"   ⚠️ TALLER: no se pudo guardar la sesión: {ex}")


def _taller_recuperar_sesion(email: str, numero: str):
    """El adelanto, del proceso o de la base. None si no existe.

    LA MEMORIA GANABA SOBRE LA BASE, Y LA MEMORIA SE QUEDA RANCIA. Éste es el
    fallo del «Consulta primero el acervo» que llevaba semanas apareciendo sin
    explicación y que en una corrida de cinco asuntos tumbó tres.

    La secuencia, con los dos workers de gunicorn que corren en Render:

      1. /taller/adelanto  cae en el worker A → guarda la sesión en A con
                           `consultado: False`.
      2. /taller/consultar cae en el worker B → marca `consultado` en Supabase
                           y en SU copia en memoria. La de A sigue en False.
      3. /taller/resolver  vuelve al worker A → encuentra la sesión en memoria,
                           la devuelve tal cual, ve `consultado: False` y
                           responde 409 «Consulta primero el acervo».

    El secretario acaba de consultar el acervo y el sistema le dice que no lo ha
    hecho. La base sabía la verdad —las cinco filas de la prueba tenían
    `consultado = true`— y nadie se la preguntaba.

    Ahora, cuando la copia en memoria dice que NO se ha consultado, se comprueba
    contra la base antes de creerla. Es una lectura de una columna y sólo ocurre
    en el caso dudoso: si la memoria ya dice que sí, no hay nada que confirmar.
    """
    ses = _TALLER_SESIONES.get(_taller_llave(email, numero))
    if ses:
        if not ses.get("consultado") and supabase_admin:
            try:
                r = supabase_admin.table("taller_sesiones") \
                    .select("consultado") \
                    .eq("email", (email or "").strip().lower()) \
                    .eq("expediente", numero).limit(1).execute()
                if r.data and r.data[0].get("consultado"):
                    ses["consultado"] = True
            except Exception as ex:
                print(f"   ⚠️ No se pudo confirmar la consulta en la base: {ex}")
        return ses
    if not supabase_admin:
        return None
    try:
        r = supabase_admin.table("taller_sesiones") \
            .select("estado, consultado, plantilla") \
            .eq("email", (email or "").strip().lower()) \
            .eq("expediente", numero).limit(1).execute()
        if not r.data:
            return None
        est = r.data[0]["estado"]
    except Exception as ex:
        print(f"   ⚠️ No se pudo recuperar la sesión del taller: {ex}")
        return None

    # Se rehidrata lo justo para poder resolver: los resúmenes, los problemas y
    # la ficha de partes. Volver a leer los PDF costaría el modelo otra vez.
    import datetime as _d
    import tempfile as _tmpmod

    import fase0_oportunidad as _f0
    import fase_partes as _fp
    import fases123_pipeline as _f123
    import redactor_adelanto as _ra

    e = est["encargo"]
    encargo = _ra.Encargo(
        numero=e["numero"], encabezado=e["encabezado"], quejoso=e["quejoso"],
        magistrado=e["magistrado"], secretario=e["secretario"],
        notificacion=_d.date.fromisoformat(e["notificacion"]),
        presentacion=_d.date.fromisoformat(e["presentacion"]),
        regla_surtimiento=e["regla_surtimiento"], plazo=e["plazo"],
        responsable=e.get("responsable"), es_recurso=e.get("es_recurso", False),
        tribunal=e.get("tribunal", ""), ciudad=e.get("ciudad", ""),
        modo=e.get("modo", "generado"),
        tipo_asunto=e.get("tipo_asunto", "amparo_directo"),
        plantilla=e["plantilla"], coleccion_estatal=e.get("coleccion_estatal", ""))
    f = _f123.Fases123()
    for k, v in (est.get("fases") or {}).items():
        setattr(f, k, v)
    partes = None
    if est.get("partes"):
        partes = _fp.Partes()
        for k, v in est["partes"].items():
            setattr(partes, k, v)
    computo = _f0.computar(encargo.notificacion, encargo.presentacion,
                           encargo.regla_surtimiento, encargo.plazo,
                           encargo.responsable)
    resultado = _ra.Resultado(ruta="", computo=computo, fases=f, encargo=encargo,
                              partes=partes, avisos=list(est.get("avisos") or []))
    tmp = est.get("tmp") or ""
    if not os.path.isdir(tmp):
        tmp = _tmpmod.mkdtemp(prefix="taller_")

    # Si la plantilla no está en este worker, se escribe desde la base.
    if not os.path.exists(encargo.plantilla):
        cruda = r.data[0].get("plantilla")
        if cruda:
            try:
                if isinstance(cruda, str):
                    cruda = bytes.fromhex(cruda[2:] if cruda.startswith("\\x") else cruda)
                destino = os.path.join(tmp, "plantilla.docx")
                with open(destino, "wb") as fh:
                    fh.write(cruda)
                encargo.plantilla = destino
            except Exception as ex:
                print(f"   ⚠️ No se pudo restaurar la plantilla: {ex}")

    ses = {"resultado": resultado, "tmp": tmp,
           "ts": time.time(), "consultado": r.data[0].get("consultado", False)}
    _TALLER_SESIONES[_taller_llave(email, numero)] = ses
    return ses


def _taller_marcar_consultado(email: str, numero: str) -> None:
    if not supabase_admin:
        return
    try:
        supabase_admin.table("taller_sesiones").update({"consultado": True}) \
            .eq("email", (email or "").strip().lower()) \
            .eq("expediente", numero).execute()
    except Exception as ex:
        print(f"   ⚠️ No se pudo marcar la consulta del taller: {ex}")


@app.post("/taller/consultar")
async def taller_consultar(
    numero: str = Form(...),
    user_email: str = Form(...),
    # LA ENTIDAD NO PUEDE TENER UNA OMISIÓN. Era «leyes_queretaro», y además se
    # sobreescribía sobre el encargo en cada consulta: el fondo de TODO asunto
    # del país se resolvía con el acervo de Querétaro. Vacío significa «no lo
    # sé», y entonces no se consulta ninguna ley estatal y se avisa, que es
    # honesto; inventar una entidad no lo es.
    coleccion_estatal: str = Form(""),
):
    """Lo que el acervo dice sobre los problemas de ESTE asunto.

    Se le enseña ANTES de pedirle el criterio: decidir el sentido sin ver la
    jurisprudencia obligatoria del tema es justo el error que este utillaje
    existe para evitar.
    """
    _taller_puerta(user_email)
    _taller_purgar()
    ses = _taller_recuperar_sesion(user_email, numero)
    if not ses:
        raise HTTPException(404, "No hay un adelanto reciente de ese expediente. "
                                 "Genéralo primero.")
    import redactor_adelanto as _ra

    r = ses["resultado"]
    if r.encargo is not None:
        # NO SE BORRA LO QUE EL ENCARGO YA TRAÍA. Antes esta línea sobreescribía
        # siempre, así que el valor por omisión del formulario ganaba a la
        # entidad que el secretario hubiera declarado al crear el asunto.
        if coleccion_estatal.strip():
            r.encargo.coleccion_estatal = coleccion_estatal
    material = await _ra.consultar(
        qdrant_client, _embedding_juris,
        lambda t: get_dense_embedding(t, modelo=EMBEDDING_MODEL), r)
    ses["material"] = material
    ses["consultado"] = True
    _taller_marcar_consultado(user_email, numero)
    _taller_registrar_uso(user_email, numero, "consulta")

    return {
        "expediente": numero,
        "problema_global": r.fases.problema_global,
        # Se devuelve el problema ENTERO, no sólo la pregunta: «qué resolvió» y
        # «qué lo combate» son el contraste del que nace, y en pantalla es lo que
        # permite al secretario decidir sin volver al expediente.
        "problemas": [
            {"pregunta": p.get("pregunta", ""), "resolvio": p.get("resolvio", ""),
             "combate": p.get("combate", ""), "impedimento": p.get("impedimento")}
            if isinstance(p, dict) else
            {"pregunta": str(p), "resolvio": "", "combate": "", "impedimento": None}
            for p in (r.fases.problemas or [])],
        "tesis": [{"registro": t["registro"], "rubro": t["rubro"],
                   "instancia": t["instancia"], "obligatoria": t["obligatoria"],
                   "localizacion": t.get("localizacion", ""),
                   "texto": (t.get("texto") or "")[:1200]}
                  for t in material.tesis],
        "normas": [{"cuerpo_legal": n["cuerpo_legal"], "articulo": n["articulo"],
                    "texto": (n.get("texto") or "")[:600]}
                   for n in material.normas],
        "avisos": r.avisos,
    }


@app.post("/taller/contexto")
async def taller_contexto(
    user_email: str = Form(...),
    texto: str = Form(""),
    documento: Optional[UploadFile] = File(None),
):
    """Lo que el acervo no tiene y el secretario sí.

    Cuando el motor no alcanza a proponer lo dice con precisión —«falta el
    texto contractual y el resultado del cotejo», «el acervo no contiene la
    cláusula 64»— y hasta ahora eso era un callejón sin salida: el secretario
    leía el diagnóstico y no podía hacer nada con él.

    Aquí sube el contrato colectivo, el convenio o el acta, o lo escribe a
    mano, y el texto vuelve a él para que lo mande con la propuesta y con el
    estudio. NO se guarda en el servidor: viaja con la petición, que es lo que
    hace que funcione con dos workers y lo que evita quedarse con documentos
    de un expediente ajeno más tiempo del necesario.
    """
    _taller_puerta(user_email)
    partes = []
    if (texto or "").strip():
        partes.append(texto.strip())
    if documento is not None and getattr(documento, "filename", ""):
        extraido = await _extract_text_from_upload(documento)
        if (extraido or "").strip():
            partes.append(f"[{documento.filename}]\n{extraido.strip()}")
    junto = "\n\n".join(partes)
    if not junto:
        raise HTTPException(400, "No llegó ni documento ni texto que aportar.")
    print(f"   ⚖️ TALLER: contexto aportado · {len(junto)} caracteres")
    return {"texto": junto[:60000], "caracteres": len(junto),
            "recortado": len(junto) > 60000}


# ═══════════════════════════════════════════════════════════════════════════
# LA PUERTA DE LA OPORTUNIDAD
# ═══════════════════════════════════════════════════════════════════════════
# El proyecto 382/2024 v5 declaró en el considerando TERCERO que la demanda era
# extemporánea —«resulta evidente su extemporaneidad»— y ochenta párrafos
# después concedió el amparo. Es una incongruencia insubsanable: si la demanda
# es extemporánea la consecuencia obligada es el SOBRESEIMIENTO (artículos 61,
# fracción XIV, y 63, fracción V, de la Ley de Amparo), no el estudio de fondo.
#
# La fecha que provocó el cálculo la tecleé yo en una prueba. Da igual: el
# pipeline ya sabía que era extemporánea —`computo.oportuna` valía False y se
# emitía un aviso— y siguió adelante hasta amparar. Un aviso que no detiene
# nada no es una defensa: es una nota al pie de un desastre.
#
# No se decide por el secretario. Se para y se le dice cuáles son las dos
# salidas, porque una de las dos es un error de dato y la otra es una sentencia
# distinta que este redactor todavía no sabe escribir.
def _puerta_oportunidad(r) -> None:
    c = getattr(r, "computo", None)
    if c is None or getattr(c, "oportuna", None) is not False:
        return
    raise HTTPException(409, (
        "EL CÓMPUTO DA LA DEMANDA EXTEMPORÁNEA y por eso no se escribe el "
        "estudio de fondo: una sentencia que declara la extemporaneidad y "
        "luego ampara es incongruente y no se sostiene en revisión. "
        "Hay dos salidas y las dos son tuyas: (1) si la fecha de presentación "
        "o la de notificación están mal, corrígelas y vuelve a generar; "
        "(2) si el cómputo es correcto, el asunto no se resuelve en el fondo "
        "—procede el SOBRESEIMIENTO conforme a los artículos 61, fracción XIV, "
        "y 63, fracción V, de la Ley de Amparo— y ese proyecto todavía hay que "
        "escribirlo a mano."))


def _con_autos(r, contexto: str) -> str:
    """El contexto del secretario, precedido por las constancias del expediente.

    El contrato colectivo de ESTE centro de trabajo, el reglamento interior o un
    peritaje no están en ningún acervo público y no pueden estarlo. Si el
    secretario los subió, son premisa: van delante de lo que él escriba, porque
    son el documento y lo suyo es el comentario.
    """
    autos = str(getattr(getattr(r, "fases", None), "autos", "") or "")
    if not autos:
        return contexto or ""
    # EL RÓTULO IMPORTA porque el modelo lo copia. Decía «aportadas por el
    # secretario» y el estudio salió diciendo «La constancia de audiencia
    # aportada por el secretario muestra que…». Una sentencia habla en nombre
    # del tribunal y las constancias son DE AUTOS: quién las digitalizó no es
    # parte del razonamiento.
    return ("CONSTANCIAS QUE OBRAN EN AUTOS (son del expediente; cítalas como "
            "«las constancias de autos», «la documental que obra a foja…», "
            "NUNCA como aportadas por nadie):\n"
            f"{autos}\n\n" + (contexto or ""))


@app.post("/taller/proponer")
async def taller_proponer(
    numero: str = Form(...),
    user_email: str = Form(...),
    contexto: str = Form(""),
):
    """LA PROPUESTA DE SOLUCIÓN. Propone, no decide.

    Faltaba este escalón. El secretario veía el acervo y tenía que fijar el
    sentido con eso delante; si no lo fijaba, el proyecto salía con la
    calificación que traía la plantilla —así nació la incongruencia del ADC
    380/2025: efectos de concesión y un resolutivo que negaba—.

    Ahora el motor propone un sentido por problema, con su razón en tres
    renglones y los registros del acervo en que se apoya. El secretario lo
    acepta, lo corrige, o dicta el suyo con la mecánica de siempre.
    """
    _taller_puerta(user_email)
    _taller_purgar()
    ses = _taller_recuperar_sesion(user_email, numero)
    if not ses:
        raise HTTPException(404, "No hay un adelanto reciente de ese expediente.")
    if not (ses.get("material") or ses.get("consultado")):
        raise HTTPException(409, "Consulta primero el acervo: una propuesta sin "
                                 "material es una opinión.")
    if "material" not in ses:
        import redactor_adelanto as _ra0
        ses["material"] = await _ra0.consultar(
            qdrant_client, _embedding_juris,
            lambda t: get_dense_embedding(t, modelo=EMBEDDING_MODEL),
            ses["resultado"])

    r = ses["resultado"]
    _puerta_oportunidad(r)
    import fase5_propuesta as _f5
    problemas = [p if isinstance(p, dict) else {"pregunta": str(p)}
                 for p in (r.fases.problemas or [])]
    if not problemas and r.fases.problema_global:
        problemas = [{"pregunta": r.fases.problema_global}]

    # LAS CONSTANCIAS SE SUMAN AL CONTEXTO. No son algo que buscar en el
    # acervo: son lo que el acervo no puede tener —el contrato colectivo de ESTE
    # centro de trabajo, el reglamento interior, el peritaje— y sin ellas hay
    # asuntos que no se pueden resolver. Van delante de lo que escriba el
    # secretario, porque son el documento y él es el comentario.
    contexto = _con_autos(r, contexto)

    propuestas, avisos = await _f5.proponer(
        chat_client, problemas, ses["material"],
        "\n".join(r.fases.parrafos_acto() or []),
        "\n".join(r.fases.parrafos_conceptos() or []),
        bool(r.encargo and r.encargo.es_recurso),
        contexto)

    # LA PROPUESTA VIAJA DE VUELTA, no se queda aquí. Render corre gunicorn con
    # DOS workers: lo que guarde este proceso puede no existir en el que atienda
    # el /taller/resolver siguiente. Se deja en memoria por si cae en el mismo
    # —es gratis— pero lo que manda es lo que el cliente devuelva, que además es
    # lo correcto: el secretario acepta explícitamente lo que acaba de leer.
    ses["propuestas"] = propuestas
    _taller_registrar_uso(user_email, numero, "propuesta")
    print(f"   ⚖️ TALLER: propuesta {numero} · {len(propuestas)} sentidos · "
          f"{len(avisos)} avisos · modelo {_f5.MODELO_PROPUESTA}")

    return {
        "expediente": numero,
        "modelo": _f5.MODELO_PROPUESTA,
        # El secretario decide sobre esto: se le da entero, no resumido.
        "propuestas": [
            {"problema": p.problema, "sentido": p.sentido, "razon": p.razon,
             "apoyos": p.apoyos, "confianza": p.confianza, "alcanza": p.alcanza}
            for p in propuestas],
        "resumen": _f5.resumen(propuestas),
        "avisos": avisos,
        # Lo que hay que mandar a /taller/resolver para aceptarla tal cual.
        # Esto se manda TAL CUAL a /taller/resolver en el campo `criterios_json`
        # para aceptar la propuesta. El secretario puede editar cualquier razón
        # o cualquier sentido antes de mandarlo: es su criterio el que gobierna.
        "criterios_json": json.dumps(
            [{"problema": p.problema, "sentido": p.sentido,
              "razonamiento": p.razon}
             for p in propuestas if p.alcanza and p.sentido], ensure_ascii=False),
    }


@app.post("/taller/resolver/stream")
async def taller_resolver_stream(
    numero: str = Form(...),
    user_email: str = Form(...),
    sentido: str = Form(""),
    problema: str = Form(""),
    razonamiento: str = Form(""),
    criterios_json: str = Form(""),
    contexto: str = Form(""),
):
    """La sentencia, viéndose escribir.

    David: «que el usuario vea el texto escribiéndose sería de ayuda». El
    estudio son setenta segundos y no hay forma honesta de recortarlos sin
    tocar la calidad; lo que sí se puede es no dejar la pantalla quieta. Esto
    no acelera nada: cambia la espera.

    Emite `text/event-stream`. Cada evento es un JSON con `tipo`:
      texto       → un trozo del estudio según se escribe
      componiendo → el modelo terminó; se está armando el .docx
      listo       → con `descarga`, `avisos`, `palabras`
      error       → con `mensaje`
    """
    from fastapi.responses import StreamingResponse

    _taller_puerta(user_email)
    _taller_purgar()
    ses = _taller_recuperar_sesion(user_email, numero)
    if not ses:
        raise HTTPException(404, "No hay un adelanto reciente de ese expediente.")
    if not (ses.get("material") or ses.get("consultado")):
        raise HTTPException(409, "Consulta primero el acervo.")
    if "material" not in ses:
        import redactor_adelanto as _ra0
        ses["material"] = await _ra0.consultar(
            qdrant_client, _embedding_juris,
            lambda t: get_dense_embedding(t, modelo=EMBEDDING_MODEL),
            ses["resultado"])

    import fase6_estudio as _f6
    import redactor_adelanto as _ra
    r = ses["resultado"]
    _puerta_oportunidad(r)

    if criterios_json.strip():
        try:
            _datos = json.loads(criterios_json)
        except Exception:
            raise HTTPException(422, "criterios_json no es JSON válido.")
        crit = [_f6.Criterio(problema=str(d.get("problema", ""))[:400],
                             sentido=str(d.get("sentido", "")).strip().lower(),
                             razonamiento=str(d.get("razonamiento", "")))
                for d in (_datos if isinstance(_datos, list) else [])
                if str(d.get("sentido", "")).strip()]
        if not crit:
            raise HTTPException(422, "criterios_json no trae ningún sentido.")
    else:
        if not sentido:
            raise HTTPException(422, "Falta el sentido o la propuesta aceptada.")
        crit = [_f6.Criterio(problema=problema or (r.fases.problema_global or ""),
                             sentido=sentido, razonamiento=razonamiento)]

    salida = f"{ses['tmp']}/{numero.replace('/', '-')} PROYECTO.docx"
    import marco_juridico as _mj
    _probs = ([r.fases.problema_global] if r.fases.problema_global else [])
    _probs += [p.get("pregunta", "") if isinstance(p, dict) else str(p)
               for p in (r.fases.problemas or [])]
    try:
        _marco = _mj.bloque(await _mj.construir(
            qdrant_client, lambda t: get_dense_embedding(t, modelo=EMBEDDING_MODEL),
            _probs, (r.encargo.coleccion_estatal if r.encargo else "") or None),
            bool(r.encargo and r.encargo.es_recurso))
    except Exception as _e:
        print(f"   ⚠️ No se pudo construir el marco jurídico: {_e}")
        _marco = ""

    async def emitir():
        try:
            async for paso in _ra.resolver_en_vivo(
                    chat_client, r, crit, ses["material"], salida, _marco,
                    qdrant=qdrant_client, contexto=_con_autos(r, contexto)):
                tipo = paso.get("tipo")
                if tipo == "texto":
                    yield ("data: " + json.dumps(
                        {"tipo": "texto", "dato": paso["dato"]},
                        ensure_ascii=False) + "\n\n")
                elif tipo == "componiendo":
                    yield ('data: {"tipo":"componiendo"}\n\n')
                elif tipo == "listo":
                    res = paso["resultado"]
                    _taller_registrar_uso(user_email, numero, "proyecto")
                    ses["salida"] = res.ruta
                    print(f"   ⚖️ TALLER: proyecto EN VIVO {numero} · "
                          f"{len(res.estudio.split())} palabras · "
                          f"{len(res.avisos)} avisos")
                    # EL DOCUMENTO VIAJA EN EL PROPIO FLUJO. Con dos workers,
                    # una descarga posterior puede caer en el proceso que no
                    # tiene el fichero en su /tmp: el secretario vería el texto
                    # escribirse y luego un 404. Son unos 75 KB en base64.
                    import base64 as _b64d
                    try:
                        _doc = _b64d.b64encode(open(res.ruta, "rb").read()).decode()
                    except Exception:
                        _doc = ""
                    yield ("data: " + json.dumps({
                        "tipo": "listo",
                        "docx_b64": _doc,
                        "nombre": res.ruta.split("/")[-1],
                        "descarga": f"/taller/descargar?numero={numero}",
                        "palabras": len(res.estudio.split()),
                        "avisos": res.avisos,
                        "huecos": res.huecos,
                        "tiempos": _ra.reloj_resumen(),
                    }, ensure_ascii=False) + "\n\n")
        except Exception as ex:
            print(f"   ⚠️ TALLER en vivo: {ex}")
            yield ("data: " + json.dumps(
                {"tipo": "error", "mensaje": str(ex)[:300]},
                ensure_ascii=False) + "\n\n")

    return StreamingResponse(emitir(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache",
                                      "X-Accel-Buffering": "no"})


@app.get("/taller/descargar")
async def taller_descargar(numero: str, user_email: str = ""):
    """El .docx que dejó la generación en vivo."""
    from fastapi.responses import FileResponse
    import os as _os
    ses = _taller_recuperar_sesion(user_email, numero) if user_email else None
    ruta = (ses or {}).get("salida") or ""
    if not ruta or not _os.path.exists(ruta):
        raise HTTPException(404, "No hay documento generado para ese expediente "
                                 "en este proceso. Vuelve a resolver.")
    return FileResponse(
        ruta,
        media_type="application/vnd.openxmlformats-officedocument."
                   "wordprocessingml.document",
        filename=ruta.split("/")[-1])


@app.post("/taller/resolver")
async def taller_resolver(
    numero: str = Form(...),
    user_email: str = Form(...),
    sentido: str = Form(""),                 # fundado|infundado|inoperante|ineficaz
    problema: str = Form(""),
    razonamiento: str = Form(""),            # SU criterio: lo que alinea el estudio
    usar_propuesta: bool = Form(False),      # acepta la de /taller/proponer
    criterios_json: str = Form(""),          # la propuesta devuelta, ya revisada
    contexto: str = Form(""),                # lo que el acervo no tenía
):
    """La sentencia, con el criterio del secretario dentro."""
    _taller_puerta(user_email)
    _taller_purgar()
    ses = _taller_recuperar_sesion(user_email, numero)
    if not ses:
        raise HTTPException(404, "No hay un adelanto reciente de ese expediente.")
    if not (ses.get("material") or ses.get("consultado")):
        raise HTTPException(409, "Consulta primero el acervo: el estudio se funda "
                                 "con lo que ahí se encuentre, no con la memoria "
                                 "del modelo.")
    if "material" not in ses:
        # La consulta la hizo otro worker: se rehace. Son tres segundos, y es
        # preferible a arrastrar 36 tesis por la base de datos entre llamadas.
        import redactor_adelanto as _ra0
        ses["material"] = await _ra0.consultar(
            qdrant_client, _embedding_juris,
            lambda t: get_dense_embedding(t, modelo=EMBEDDING_MODEL),
            ses["resultado"])
    import fase6_estudio as _f6
    import redactor_adelanto as _ra

    r = ses["resultado"]
    _puerta_oportunidad(r)
    # DOS CAMINOS, Y NINGUNO ES «QUE SIGA COMO ESTÉ». O el secretario dicta su
    # criterio, o acepta la propuesta del motor. Antes existía un tercero —no
    # decidir— y era el que producía sentencias incongruentes: el estudio se
    # escribía y el resolutivo se quedaba con la calificación de la plantilla.
    if criterios_json.strip():
        # El camino bueno: el secretario devuelve lo que aceptó, con sus
        # ediciones si las hizo. No depende de qué worker atendió la propuesta.
        try:
            _datos = json.loads(criterios_json)
        except Exception:
            raise HTTPException(422, "criterios_json no es JSON válido.")
        crit = [_f6.Criterio(problema=str(d.get("problema", ""))[:400],
                             sentido=str(d.get("sentido", "")).strip().lower(),
                             razonamiento=str(d.get("razonamiento", "")))
                for d in (_datos if isinstance(_datos, list) else [])
                if str(d.get("sentido", "")).strip()]
        if not crit:
            raise HTTPException(422, "criterios_json no trae ningún sentido.")
    elif usar_propuesta:
        props = ses.get("propuestas") or []
        crit = [_f6.Criterio(problema=p.problema, sentido=p.sentido,
                             razonamiento=p.razon)
                for p in props if getattr(p, "alcanza", True) and p.sentido]
        if not crit:
            raise HTTPException(409, "No hay propuesta en este proceso. Vuelve a "
                                     "pedir /taller/proponer y manda su "
                                     "`criterios_json` aquí, que no depende del "
                                     "worker que atienda.")
    else:
        if not sentido:
            raise HTTPException(422, "Falta el sentido. Dicta tu criterio o "
                                     "acepta la propuesta con usar_propuesta=1.")
        crit = [_f6.Criterio(
            problema=problema or (r.fases.problema_global or ""),
            sentido=sentido, razonamiento=razonamiento)]
    salida = f"{ses['tmp']}/{numero.replace('/', '-')} PROYECTO.docx"
    # El marco jurídico de ESTE asunto. Si los problemas no lo piden, sale vacío
    # y no se escribe: pegar derechos humanos en todos los asuntos era el riesgo
    # que David mismo descartó —«no fijar un marco constitucional para todos los
    # casos, sino sobre la solución en función del problema jurídico»—.
    import marco_juridico as _mj
    _t0_marco = time.time()
    _probs = ([r.fases.problema_global] if r.fases.problema_global else [])
    _probs += [p.get("pregunta", "") if isinstance(p, dict) else str(p)
               for p in (r.fases.problemas or [])]
    try:
        _marco = _mj.bloque(await _mj.construir(
            qdrant_client, lambda t: get_dense_embedding(t, modelo=EMBEDDING_MODEL),
            _probs, (r.encargo.coleccion_estatal if r.encargo else "") or None),
            r.encargo.es_recurso if r.encargo else False)
    except Exception as _e:
        print(f"   ⚠️ No se pudo construir el marco jurídico: {_e}")
        _marco = ""
    if _marco:
        print(f"   ⚖️ TALLER: marco jurídico de {len(_marco)} caracteres "
              f"· {time.time() - _t0_marco:.1f}s")

    r2 = await _ra.resolver(chat_client, r, crit, ses["material"], salida,
                            _marco, qdrant=qdrant_client,
                            contexto=_con_autos(r, contexto))
    _taller_registrar_uso(user_email, numero, "proyecto")

    print(f"   ⚖️ TALLER: proyecto {numero} · {len(r2.estudio.split())} palabras "
          f"· {len(r2.avisos)} avisos")

    from fastapi.responses import FileResponse
    return FileResponse(
        r2.ruta,
        media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        filename=salida.split("/")[-1],
        headers={
            # Esto NO es un proyecto firmable y el secretario tiene que saberlo
            # antes de abrirlo, no en un aviso legal que nadie lee.
            "X-Borrador": "1",
            "X-Palabras": str(len(r2.estudio.split())),
            "X-Avisos": str(len(r2.avisos)),
            # El conteo solo no sirve de nada: el secretario ve «4 avisos» y no
            # sabe cuáles. Van también en claro, recortados a lo que cabe en
            # una cabecera y sin acentos raros que rompan latin-1.
            "X-Avisos-Detalle": _cabecera_segura(r2.avisos),
            # El reloj, para poder medir sin escarbar en los logs.
            "X-Tiempos": _cabecera_segura([_ra.reloj_resumen()]),
            "X-Huecos": str(len(r2.huecos)),
            "X-Advertencias": "1" if r2.advertencias else "0",
        },
    )


@app.get("/taller/estado")
async def taller_estado(user_email: str):
    """Si el piloto sigue abierto y cuánto le queda."""
    n = _taller_secretarios_distintos()
    return {
        "activo": TALLER_PILOTO_ACTIVO and n <= TALLER_PILOTO_CUPO,
        "secretarios": n,
        "cupo": TALLER_PILOTO_CUPO,
        "tiene_acceso": _can_access_redactor_tcc(user_email),
        "aviso": ("Borrador asistido. No es un proyecto firmable: verifique las "
                  "partes, las citas y que estén contestados todos los conceptos."),
    }


